window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["25873066"]={"book":{"id":25873066,"title":"麦肯锡工作法","author":"大岛祥誉","translator":"王柏静","publisher":"中信出版社","pubdate":"2014-5-1","isbn":"9787508644691","tags":["个人管理","麦肯锡","职场","方法论","管理","工作","思维","商业"],"memCount":14},"np":1,"pb":[25],"idx":[{"i":18072,"t":"学习培养自己的人脉","l":"TF1-2","c":"m陌上花开雷","g":1,"p":1},{"i":14322,"t":"善于调节情绪的人才会成功","l":"TF1-1","c":"Jean","g":1,"p":1},{"i":13985,"t":"如何在展开工作前确认关键信息","l":"TF1-1","c":"嘉璇","g":1,"p":1},{"i":13741,"t":"高效汇报3步法","l":"TF2-2","c":"陆琴","g":1,"p":1},{"i":12828,"t":"用“空雨伞”，掌控现在，把握未来","l":"TF1-2","c":"紫雨飘扬","g":1,"p":1},{"i":11796,"t":"用“逻辑分析笔记”将自己的情绪写出来","l":"TF2-1","c":"naity0304","g":1,"p":1},{"i":11520,"t":"高效沟通三步法","l":"TF2-2","c":"陆琴","g":1,"p":1},{"i":10895,"t":"用“三个要点”法简洁传达信息","l":"TF1-1","c":"贾思敏","g":1,"p":1},{"i":8330,"t":"30秒3要点表达法","l":"TF1-2","c":"王哈哈","g":1,"p":1},{"i":7981,"t":"把握问题本质","l":"TF2-2","c":"Lance龙","g":1,"p":1},{"i":7895,"t":"在工作中当别人的行为不能达到你的期望时，你应该怎么做 ？","l":"TF1-1","c":"玄清琳","g":0,"p":1},{"i":7386,"t":"用30秒时间提出3个要点","l":"TF1-2","c":"吕吕","g":1,"p":1},{"i":7360,"t":"增强沟通的效率","l":"TF2-1","c":"刘余庆","g":1,"p":1},{"i":6402,"t":"如何让会议更高效","l":"TF1-2","c":"曹志文","g":1,"p":1},{"i":6069,"t":"麦肯锡的情报收集三部曲","l":"TF1-2","c":"树","g":0,"p":1},{"i":5002,"t":"如何与不喜欢的人共事？","l":"TF1-2","c":"冬青","g":1,"p":1},{"i":4181,"t":"工作的确认与开展","l":"TF2-4","c":"grace","g":0,"p":1},{"i":4180,"t":"工作汇报三步法","l":"TF2-3","c":"grace","g":0,"p":1},{"i":3643,"t":"如何改善与上司的配合","l":"TF1-1","c":"雅韵","g":1,"p":1},{"i":2902,"t":"学会明确会议的“目的”与“目标状态”","l":"TF2-2","c":"许晓勤","g":1,"p":1},{"i":2171,"t":"“空，雨，伞”思考方法","l":"TF1-2","c":"潇湘梅","g":1,"p":1},{"i":1719,"t":"麦肯锡工作法之电梯汇报法则","l":"TF2-1","c":"牛魔王","g":1,"p":1},{"i":1450,"t":"用1分钟作为开头争取沟通时间","l":"TF2-2","c":"牛魔王","g":1,"p":1},{"i":680,"t":"得情报者得天下看麦肯锡情报收集三步法","l":"TF2-1","c":"陈健","g":1,"p":1},{"i":622,"t":"麦肯锡情报收集三步法","l":"TF2-1","c":"陈健","g":0,"p":1}],"ms":[{"id":18072,"topic":"学习培养自己的人脉","learn_goal":"","remark":"无","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"m陌上花开雷","city":"阿坝藏族羌族自治州"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>请问观察家老师拿到观察家记录表、晋级准备表了吗？\u003c/p>\u003cp>在场的小伙伴们都准备好了吗？都准备好的话，我们现在正式开始今天的拆书环节。\u003c/p>\u003cp>\u003cstrong>【自我介绍】\u003c/strong>：\u003c/p>\u003cp>各位老师、观察家、小伙伴们下午好，我是今天的拆书家雷静瑶，来自蜀汉分舵；我的昵称是陌上花开，来自“陌上花开，可缓缓归矣”，大家可以称呼我为静瑶。下面我用三个标签来进一步介绍自己：\u003c/p>\u003cp>1、早起奇迹践行者：早起阅读学习让我的生命更加丰盛。\u003c/p>\u003cp>2、家庭教育践行者：我是两个孩子的妈妈，赋于我的人生使命是努力成为“孩子们的时光领路人”。\u003c/p>\u003cp>3、同时还是一名正在路上的新手拆书家；\u003c/p>\u003cp>我的目标：不断学习，促进自身与他人成长。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>由于今天在场人员不多，咱们就在一个大组进行讨论。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>今天推荐的这本书是刘易斯所编写的《麦肯锡极简工作法》。是世界500强企业必读物。本书介绍了麦肯锡公司内部的秘密武器----极简工作法，其中包括分析问题、收集信息、逻辑思考、推介方案、团队与客户合作、解决问题提升能力以及危机防范等相关内容。\u003c/p>\u003cp>阅读本书，教会我们用简单方法做复杂之事，将工作速度和工作效率提升到极致，对提升自身竞争力很有帮助。\u003c/p>\u003cp>今天，我拆解的图书片段页码（P151页）——主题：学习培养自己的人脉\u003c/p>","ratings_count":1,"texts":[{"id":22316,"quote":"\u003cp>除此之外，学习培养自己的人脉也是优秀员工必须的良好工作习惯。\u003c/p>\u003cp>1、牢记对方的姓名，这是培养自己人脉的开端。另外，当记住了他人的名字后，在见面时可以采用以下方式称呼对方。\u003c/p>\u003cp>（1） 可以在做自我介绍时，立刻就说出对方的名字。\u003c/p>\u003cp>（2） 可以在提问时轻松地说出对方的名字，比如我们可以这样说：“***，请问你是哪里人？”\u003c/p>\u003cp>（3） 在与对方告别时说出对方的名字，比如：“***，我们今天聊得很开心，期待下次见面。”\u003c/p>\u003cp>2、尝试选择不同的场所和时间与对方见面。比如，这次是在午餐时与对方见面的，下次就可以选择晚餐，或者是由吃饭改为喝咖啡，这样可以拉近双方的距离。\u003c/p>","explains":"\u003cp>\u003cstrong>【WHAT】\u003c/strong>\u003c/p>\u003cp>这个拆页介绍了一个优秀员工良好工作习惯之一：学习培养提高自己的人脉。\u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>\u003c/p>\u003cp>大家可以回忆一下自己身边有没有这样的大咖，无论哪个方面出了问题，他总是可以找到门路来解决问题：遇到法律方面的问题，他有律师朋友；涉及工商注册，他工商局有朋友可以咨询；甚至有个头疼脑热，医院都有他的朋友，我们通常觉得他人脉广、万事通。而且通常这类人在工作上的表现也是很优秀的。因而在麦肯锡“学习培养自己的人脉”是优秀员工必备的工作习惯。反之，缺乏人脉关系的人会导致工作效率低下，让自己工作和生活陷入低洼状态，影响自己的仕途。\u003c/p>\u003cp>\u003cstrong>【HOW】及细化步骤\u003c/strong>\u003c/p>\u003cp>我们要怎样培养自己的人脉呢？\u003c/p>\u003cp>第一步：记名字。并运用在以下场景中：\u003c/p>\u003cp>比如：我在今年4月的时候我去办理项目土地预审时，由于资料准备不齐全，没办成，一位女工作人员叫我回去把资料准备齐全了再来。\u003c/p>\u003cp>场景1：当你见面打招呼时能叫出对方人的名字，一下子拉近了关系，每个人对自己的名字都是非常之热爱的。\u003c/p>\u003cp>比如：我认真看了下她的工牌，当时就说了句“晓凤姐，你业务这么熟练，服务态度又这么好，真让人敬佩。我准备好资料再来找你”，她很惊奇又很高兴地说“可以啊”。\u003c/p>\u003cp>场景2：在谈话的过程中加以运用，你亲切的叫出对方的名字，会让人非常愿意跟你开始做朋友。\u003c/p>\u003cp>比如：第二次我再去办手续，直接跟她打招呼“晓凤姐我来了，我是上次来过一次的交通局的小雷，您的气质真好，你一定很喜欢看书吧”，她很主动地帮我检查了各项资料并且还给了我很多建议，为求以后多指教我还加了她的微信。\u003c/p>\u003cp>场景3：在告别时能叫出对方的名字，会增加下次见面的亲切感。\u003c/p>\u003cp>比如：在我拿到批复之后对她说：“谢谢晓凤姐，认识你非常的开心，本周日有个读书会我们一起去参加吧，再见”。\u003c/p>\u003cp>2、常链接。选择不同的地点或不同的方式见面。有了进一步接触的感觉，这样可以拉近双方距离感。\u003c/p>\u003cp>比如：在周日上午我发了个微信给她，约她一个去参加读书会。她说感觉和我很有缘分。我平时喜欢读书，她也喜欢写作，我们现在是很好的朋友。\u003c/p>\u003cp>\u003cstrong>【WHRER】\u003c/strong>\u003c/p>\u003cp>培养提高自己的人脉应用场景比较广泛，无论是工作中，还是在生活中，只要你需要和别人建立链接的时候就可以运用起来。\u003c/p>","interaction":"\u003cp>【A1显像提问】\u003c/p>\u003cp>我们通过以上的拆页，学习了培养提高自己人脉的有效途径一是记名字，二是常链接。好，接下来我们进入练习环节，请大家回忆一下，在自己过去一周或者一个月的生活、工作中因为记不住名字或者没有产生链接，影响自己的人脉或者造成损失的事件呢？\u003c/p>\u003cp>比如：\u003c/p>\u003cp>1. 孩子小升初，想要去到更好的学校，自己托了很多关系，也交了5万元去到那个学校，最后见到校长，怎么这么眼熟，就是想不起来名字，人家可认识你，打招呼说，怎么不早说啊，费这么大劲，你才拍大腿：咋就有资源没链接上。\u003c/p>\u003cp>2. 或者平时很不喜欢社交，也不与人交往，同学聚会、红白喜事都不想参加，轮到自家孩子结婚的时候，没人捧场的尴尬局面。\u003c/p>\u003cp>【现场指令】\u003c/p>\u003cp>请大家具体回忆下：什么时间，什么地点，和谁，因为记不住名字或者没有产生链接的事情？结果如何？温馨提示一下：这里需要的是一件具体的事件。接下来我们就在大组里分享，请大家用2分钟的时间进行分享自己的相关经验，2分钟后，我们结束分享并邀请1位伙伴来为大家当众分享一下他的经验。\u003c/p>\u003cp>已经看到大家组内分享的差不多了，那么接下来邀请一位小伙伴来当众分享一下自己的经历，限时1分钟。\u003c/p>\u003cp>【小组分享】1分钟\u003c/p>\u003cp>【学习者案例记录】：1分钟\u003c/p>\u003cp>分享者火火：她在美国的时候，在昨天去接孩子的时候，认识了一位华人妈妈，加了微信，今天有一点事情需要咨询一下哪位华人妈妈，因为没有记住对方名字，打招呼的时候，有些不好意思，还是厚着脸皮问了对方怎么称呼，对方邀请你加入到孩子学校微信群。\u003c/p>\u003cp>分享者永一：在参加酒席的时候，有一位阿姨很热情的打招呼“永一，小伙子长胖了，最近学习怎么样呢”？，当时有些茫然，一下子想不起来这是谁呢？对我还不么熟悉，后来妈妈说，这是我的幼儿园老师。再分享一个：我是一名财富流教练，在带盘的时候没有记住玩家的名字，总是玩家一，玩家二的称呼，感觉这样有些陌生。\u003c/p>\u003cp>【回应或反馈】\u003c/p>\u003cp> 谢谢 火火和永一的 的分享，分享的案例是：火火在一次和华人妈妈见面的时候，加了微信，但是未备注对方的名字，在需要链接的时候，不知道怎么称呼对方，给自己带来的困扰。永一分享一下在一次婚礼上，自己幼儿园老师和自己打招呼，自己想不起来对方是谁了，非常的尴尬；还有一次在带盘的时候，记不住玩家的名字，总是玩家一、玩家二的称呼，给人感觉有些陌生，产生了距离感。\u003c/p>\u003cp>希望通过今天的拆页，对你们以后的人脉关系上有所帮助.\u003c/p>\u003cp>\u003cstrong>【A2催化应用】\u003c/strong>\u003c/p>\u003cp>今天，我们对“学习培养自己的人脉”有了进一步的了解，为了更熟练的应用这个新方法，接下来请大家设想一下，在未来一到两周你会怎么去应用呢？也就是把刚才学到的知识，运用在什么场景，为这个场景添加目标和行动计划。制定目标行动的时候不是喊口号表决心，而是需要有时间节点可衡量的清晰的步骤。也就是在什么期限内（比如：未来一周）我要在什么场景（见客户、工作伙伴、孩子的老师），如何做（一是记名字，二是常链接），达到什么目的和效果（比如达到拉近彼此关系，让对方成为我的人脉）。接下来给大家2分钟的时间，写下自己的A2目标计划，2分钟后我请一位小伙伴来分享一下你的目标和行动计划。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】：\u003c/strong>因为小伙伴们有一些突发状况，不能语言分享，接下来接小伙伴们把文字分享发到群里面，通过这个拆页，我们运用这个方法可以帮助你建立人脉，我非常的开心。\u003c/p>\u003cp>结束语：由于时间关系，我们今天的分享就到这里。以真诚打动人心，精诚所至金石为开。培养良好的人脉，可以提升我们的工作效率和自身竞争力。\u003c/p>\u003cp>以上就是我今天TF1-2拆书分享的全部内容，希望对大家有所帮助，感谢观察家，感谢各位小伙伴的陪伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}},{"id":22317,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1725886693000,"updated_at":1726305026000,"ria":true},{"id":14322,"topic":"善于调节情绪的人才会成功","learn_goal":"","remark":"在人的心理世界中，情绪扮演着重要的角色。\n当我们拥有积极的情绪时，我们往往精神振奋，战无不胜。\n但是当我们被消极的情绪笼罩时，往往心灰意冷，一事无成。\n那么，我们应该如何调节自己的情绪呢？\n一起来学习本次拆页《麦肯锡经典沟通法：提升个人竞争力的68个高情商策略》-善于调节情绪的人才会成功吧。希望你能在这里找到答案。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"Jean","city":"青岛市"},"club":{"name":"青岛五月风分舵","city":"青岛"},"prologue":"\u003cp>\u003cstrong>各位小伙伴们，大家好！我叫刘婧，婧这个字，代表女子有才能，我想奶奶当时给我起这个名字，是希望我能学有所成吧。实际上，我也算是半个学霸，虽然不敢说学习有多好，但是从小逢考必过，比如高考，比如教师资格证，剑桥国际英语教师资格证，都是一次通关。我非常善于抓取学习重点，所以不管是以前做小学英语教学还是企业成人培训，我都希望让学生们更快更高效地掌握知识，做到事半功倍。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>作为成年人，我们读书的时间有限，很多时候我们读书都是带有功利目的的，为了提升自己的能力或者解决某个问题。拆书是一种学习方法论，它以学习者为中心，把知识关联学习者的经验、规划具体的应用。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书法的关键是3个字母，R-阅读原文；I-用自己的语言阐述文章内容，A-复盘之前，规划未来。对于个人来说，我们可以用便签法来学习某一主题，对于组织来说，拆书法就是一位拆书家在现场带领大家学习，促进一群人将知识拆为己用。\u003c/strong>\u003cbr>\u003cbr>\u003cstrong>那什么是拆书帮呢？\u003c/strong>\u003cbr>\u003cstrong>拆书帮是基于拆书法的学习爱好者社群，在全国各地都有拆书帮分舵，他是非营利性青年自组织，其使命是帮助更多学习爱好者成长为拆书家。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>今天我作为拆书帮的一名拆书家，将和大家一起共读的内容摘自《麦肯锡经典沟通法：提升个人竞争力的68个高情商策略 善于调节情绪的人才会成功》。我先用2分钟的时间来带着大家读一下拆页。\u003c/strong>\u003c/p>","ratings_count":3,"texts":[{"id":18328,"quote":"\u003cp>\u003cstrong>职场人士必须意识到你遭遇到不顺心的事情是在所难免的，并着手寻求解决问题的具体办法。以下是麦肯锡公司培训讲师斯洛特给出的建议：第一，正确对待遗憾。不要害怕遗憾，没有遗憾的生活，不是完整的生活。人生最大的遗憾，就是从来没有遇上遗憾。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二，做最糟糕的设想。当某一不好的信息传来，可以自问：“这事会坏到什么程度？”设想越糟糕，往往越使人坦然。做最糟糕的设想，有时还会使人在与事实做比较后，产生一种轻松感：不过如此而已！\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三，多一点幽默感和乐观主义精神。幽默感与一个人的知识水平、文化素养和精神境界有关。那些科学巨匠和艺术大师往往对生活中的艰难和不公正报以苦涩的微笑，使烦恼和郁闷化为乌有，然后若无其事、精力充沛地干该干的事。有意识地培养幽默感和乐观态度，实际上是一种积蓄，积蓄消除不良情绪的能量。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第四，转移兴奋中心。消极情绪往往会在大脑皮层形成兴奋中心，使乐观情绪处于相对抑制状态。要改变这种状态，最好的办法是使兴奋中心转移，即有意识地找事情做，借以分散注意力。可以强迫自己读书、作画或写文章，可以去野外郊游，总之，尽量去找自己平时爱干的事情干。这时消极情绪会逐渐淡化。自己的注意力集中在眼前的工作上，即使是事后想起不顺心的事情时，那种不良感觉也会减弱甚至消失。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>有时候，不良情绪靠自己独自调节还不够，还需要借助别人的疏导。当你有了苦闷的时候，可以把闷在心里的一些苦恼向家人、朋友倾诉，诉说委屈和痛苦，发牢骚等。这样不仅可以排除心头的烦恼，还可以得到他人的帮助。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>智商并不是通向成功的唯一要素。更重要的是，你要具有强大的情商控制力，让你的性格和情绪得以完善，成功者其实就是善于调节情绪的人！\u003c/strong>\u003c/p>","explains":"\u003cp>\u003cstrong>通过本拆书页，你将学习调节坏情绪的4种方法。（What）\u003c/strong>\u003c/p>\u003cp>\u003cbr>\u003cstrong>在职场中，遇到不顺心的事情很难避免，如果我们一味沉浸在坏情绪当中无法自拔，他就会抑制我们的乐观情绪，同时还会让我们无心应对别的工作，得不偿失。但如果我们能快速地整理好自己的情绪，积极寻求事情的解决方法，全身心地投入到应该做的事情当中，坏情绪就可以慢慢消散。（Why）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>我们应该如何做呢？(How）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong> \u003cstrong>把失败看成人生常态，没有遗憾的人生是不完美\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong> \u003cstrong>遇到烦心事，做最坏的打算\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong> \u003cstrong>培养自己的幽默感和乐观主义精神，就像有句话说的，生活以痛吻我，我却报之以歌。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>4.\u003c/strong> \u003cstrong>去做一些自己平时喜欢做的事情，分散注意力，逐渐将坏情绪淡化。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>如果上面这些方法还不能帮你消除坏情绪，还可以向家人和朋友寻求帮助，让他们帮自己化解坏情绪。\u003c/strong>\u003c/p>\u003cp>\u003cbr>\u003cstrong>当你在工作和生活中遇到不顺心的事情时，就可以使用此方法来进行自我调节。（Where）\u003c/strong>\u003c/p>","interaction":"\u003cp>\u003cstrong>我来给大家分享一个我自己的故事：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A1：有一次，我给客户找老师，客户和老师沟通了两次以后，想让老师提供一个更详细的知识框架。但是老师却说，需要真正着手做，进一步的调研，才能设计方案。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>客户和老师的设计思路我都能理解，但是客户和老师却不想彼此迁就，每个人都想顺着自己的思路去工作。因为我和这个客户没有在培训方面正式合作过，但是我非常希望能赶快和客户成一单，从而促进后期的合作。所以，我心里就有个想法，就是要让老师退一下，先给客户出一个他想要的方案。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>于是，我在老师和客户之间进行了很长时间的沟通协调，但是最终也没有说服任何一方。因为这个事情，耽误了自己很多时间，正常的工作也无法完成，到了这个地方，我已经感觉到自己情绪非常糟糕，我根本没有心思做别的事情，就是想不明白为什么这个事情老师就不能让一让，而且就想直接放弃。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>和我一起合作的姑娘看出了我的不爽，她提醒我，想想现在我们还能做些什么，再努力一下，即使不成功也没关系。我非常感谢她，她做的就是让我把事情做最坏的打算，从而更好地接受最后不一定能成功的事实。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A2：在接下来的一个月，如果客户再来找我找师资，首先我还是会积极努力的帮助客户匹配好的老师资源，尽可能协助双方沟通。整个过程中，我会抱着必胜的信念去做，但是，我也会在心里记住，这个事情的最终决定权不在我的手里，而是取决于客户，我只能尽自己最大的努力去做，但是也有可能不成功。这样做，我就可以保证一个好的心态，即使最后客户没选择，我也可以很快地投入其他工作当中。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>另外，当以后客户和老师陷入这种焦灼的状态中时，我会限定自己和老师以及客户沟通的次数，再明确了老师和客户的具体要求之后，如果双方都不肯让步，那么我会立即结束和老师的沟通，然后再去寻求其他老师的协助，不会让自己在一件事情上拖延太多时间。如果最后确定没有合适的老师，我也要及时和客户表达歉意，然后开始其他的工作，慢慢转移没有成功这个注意力，不让他影响自己的心情。\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1665147306000,"updated_at":1667287741000,"ria":true},{"id":13985,"topic":"如何在展开工作前确认关键信息","learn_goal":"","remark":"《麦肯锡工作法》这本书的作者大岛祥誉，是世界顶尖顾问公司麦肯锡的前咨询顾问，这本书就是他的现身说法，以“品质*效率”为主题，为我们介绍了麦肯锡精英们彻底实践的工作法以及最重要的39个习惯。“麦肯锡人”总带着闪耀的光环，为何他们从麦肯锡毕业后，还能活跃于各个行业，取得非凡的成绩？原因就在于麦肯锡独特的工作法，让员工的竞争力大大提升，并且终生受用\n整本书不足200页，日本人的写作风格，简洁明了，通篇纯粹的方法论，浅显易懂让你看完就可以快速应用。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"嘉璇","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"\u003cp>大家晚上好，我是李嘉璇，在北京土生土长，曾经在互联网公司工作15年，基本与互联网广告运营相关，去年年底集齐BAT（百度，阿里，腾讯）就退出互联网江湖，跨入抗衰老领域自主创业。最近一年迅速学习掌握了很多抗衰老的知识，无论是皮肤的护理还是健康的生活方式，其实都是为了让我们能够由内而外保持年轻和健康。如果大家有这方面的需求，欢迎随时探讨。\u003c/p>\u003cp>我是一年前第一次在五道口参加线下活动，就对“拆书帮”感兴趣，今年7月份正式加入宇宙中心分舵，成为拆书帮的一员。希望和大家一起在这个有爱的组织里面共同精进成长。\u003c/p>\u003cp>第一次听到拆书帮的名字就觉得很有意思，那么拆书帮到底是一个什么样的组织呢？拆书帮是基于拆书法的学习爱好者社群，以分舵的形式存在，我们所在的就是北京宇宙中心分舵。\u003c/p>\u003cp>拆书法是一种学习方法论，“拆”不是“拆散”，而是转化和内化，是书中的知识转化为自己的能力，也就是拆为己用。能够学以致用才是读书学习最终的意义和价值。拆书法可以应用在个人学习和组织学习，个人学习的应用是RIA便签法，R-是书中的原文，I-是用自己的语言重述信息，A-描述自己的相关经验以及未来的应用。组织学习的应用就是我们现在的这种形式，是一位拆书家用RIA便签法将一本书加工出一场现场学习，引导和帮助现场学习者把知识拆为己用。\u003c/p>\u003cp>我是通过参加了几次线下的拆书活动后，能够把拆书家分享的知识点应用到自己的生活里，所以非常喜欢这种学习分享的方式，也是参加了全国训练营之后，对RIA便签法更深的理解，能更好的运用到日常的读书学习当中。\u003c/p>\u003cp>所以我加入了宇宙中心分舵，开启了我的拆书家成长之旅，希望在这样爱读书爱分享环境里面，和大家共同精进成长，也能够影响更多身边的一起终身成长。\u003c/p>","ratings_count":1,"texts":[{"id":17988,"quote":"\u003cp>《麦肯锡工作法》\u003c/p>\u003cp>习惯17．工作过程中与上司进行确认\u003cbr>\u003cbr>身为部下的你，在接到上司安排的工作时，必须在规定间内，保质保量地完成任务。因此，你必须和上司确认下三点。\u003cbr>1．这份工作的期限。\u003cbr>2．工作的意图和方向性。\u003cbr>3．要求的品质。\u003cbr>很多人都容易忘记确认“1”的期限。他们以为只要上司记得工作期限就够了。但由于上司十分繁忙，所以他们会更多地把时间都用在说明工作内容上。如果你认为这是“没有时间限制，只要空闲时完成的工作，那就大错特错了。\u003cbr>等过几天上司想起来，问你“那件事怎么样了”，结果你根本没有做，上司肯定会勃然大怒吧，因为他的小组没有取得成果，肯定让他也感到十分苦恼。对于这种部下的评价，怎么可能好呢？\u003cbr>你的努力得到回报了吗？在工作的过程中，应该与上司逐一确认工作的意图和方向性，以及品质是否合格。\u003cbr>如果你在接受工作后，中途没有和上司做进一步的确认，就按照自己的想法埋头工作，两星期后参加会议。当你做工作报告时，上司的脸色一下子就变了。“我之前说的话你都没听到吗？完全不是这样的！”\u003cbr>这说明上司的指示与你所理解的内容出现了偏差，你付出的一番辛苦，结果却和上司的指示背道而驰。\u003cbr>为了避免出现这种情况，越是复杂且期限较长的工作，越应该在过程中与上司进行确认。这将对你的工作成果起决定性的作用。\u003c/p>","explains":"\u003cp>原文片段是麦肯锡精英39个工作好习惯之一，是为了让我们接到工作任务后，展开具体工作前，能够准确理解上级对工作内容的预期，使得工作成果能够符合预期。避免出现因信息不同步、理解不够具体等问题，导致虽然付出了时间和精力，但是最终却没有让上级满意的情况。\u003c/p>\u003cp>除了在工作中需要与上级的沟通确认信息，我们平时与他人的合作或接受他人的请求，也可以事先确认好重要信息，不浪费时间走弯路。这些信息的确认，同样也适用于为自己的行动制定计划，自己想的越清楚，取得的成果越满意。\u003c/p>\u003cp>我先按照自己的理解给大家分享一些应用场景，分享结束之后大家也可以根据自己的经验和思考进行更深入的探讨。\u003c/p>\u003cp>在开始行动之前，有三点非常重要的信息需要确认——时间期限、意图方向和品质要求\u003c/p>\u003cp>我们先来看在工作中与上级确认信息的场景\u003c/p>\u003cp>时间期限：工作任务的交付时间是最基础的信息，如果没有按时完成，就算工作做的再出色也无济于事。这个时间期限可能是“时间点”，也可能是“时间段”。按照以往的经验，如果比较简单的任务或者比较近的完成时间，就需要确认到具体日期，最好明确到小时，这就是完成的时间点。对于需要较长时间完成的比较复杂的任务，或者上级也不太确定非常具体时间的，可以和上级商定一个时间段(比如下月月初、第四季度等等)。这样也比较容易倒推时间，合理安排执行过程中关键时间节点和进度，给自己留出一定时间，避免卡着时间匆忙完成，忙中出错。如果上级给出的时间要求是“尽快完成”“越快越好”之类的描述，那就评估一下自己手头的工作，预判一个可以完成的时间点，问上级是否可以，然后按照约定好的时间去完成工作任务。\u003c/p>\u003cp>意图方向:百度了“意图”的含义，是希望达到某种目的的打算。“方向”在生活中代表了人生的理想和追求的目标。确认工作的具体意图和方向是工作内容的核心。需要去理解和确认做这项工作是基于什么动机？要达到什么样的目的？解决什么样的问题？明确了这些信息，我们展开工作之前就知道为什么要做，以及完成工作任务要达到的目标和结果。\u003c/p>\u003cp>和确认时间期限一样，如果上级能够把意图和方向描述很清楚，我们就按照具体的要求去做就可以。但是如果上级也只是上级接了个任务，对具体的信息不是非常确定，那我们可以主动用“老板让做这件事是什么背景？”“是要解决什么问题？”等这样的问题，和上级一起探寻这项工作的意图和方向，之后达成一致，方便展开具体工作。\u003c/p>\u003cp>品质要求：是衡量完成的工作质量一个标准，展开工作前要与上级确认合格的标准是什么？以及是不是有和更高标准的要求或期待？比如要完成一个月度工作报告ppt，可以请教上级对ppt风格、字体排版等有什么要求，是不是有模板可以参考？需不需要添加一些动画效果？比如要完成一场线下的活动，除了既定的活动流程完整执行以外，对会前的邀请形式、现场的布置等有更高的要求？\u003c/p>\u003cp>以上三个信息的确认方式，可以用于很多需要他人确认信息的场景，原则就是开始行动前无论对方是否能够给出明确的信息或要求，都要我要把这三个关键与对方达成一致。\u003c/p>\u003cp>那么，在个人计划的场景中，因为不需要与他人讨论或协商，就需要自己独立思考，把这些信息想得很清楚。\u003c/p>\u003cp>首先要思考的就是为什么要做这件事？动机是什么？要达成什么样的目的？来确定一个短期目标(意图和方向)\u003c/p>\u003cp>比如为了提升文案写作水平，方便以后随时输出吸引人的产品营销文案，先练习撰写100条文案\u003c/p>\u003cp>然后再根据自己的实际情况确定一个时间点（时间期限）\u003c/p>\u003cp>通常这个时间点就根据要达成目标的时间倒推就可以，所以上面这个举例的给自己训练时间可以是一个月，在8月底完成\u003c/p>\u003cp>对于品质的要求，可以参考在这件事上比较成功的案例作为榜样，借鉴学习。\u003c/p>\u003cp>可以去网上搜索一些案例，也可以请教在营销或写作方面写作方面\u003c/p>\u003cp>与他人合作和自己计划的两种场景，也会交叉出现。并且对于比较复杂的周期比较长的工作任务，工作进行的过程中，以上三个信息是能够循环使用的。也就是在对当前完成的工作任务进行复盘的时候，很可能对这三个信息进行一些调整和优化，对下一个阶段行动展开提供指导。\u003c/p>","interaction":"\u003cp>A1:\u003c/p>\u003cp>6月的618大促之前，我们小团队建立了3天快闪群，是大团队社群营销的先锋，也成了榜样。团队领导希望我们进行经验分享。接到这个任务之后，第一时间和领导电话确认了以下信息。\u003c/p>\u003cp>我：我们要在什么时间进行分享？\u003c/p>\u003cp>领导：这个周三下午2点有团队例会，你就在这个会上分享就行（明确时间期限）\u003c/p>\u003cp>我：我们这次分享的目的是？\u003c/p>\u003cp>领导：受NDO的限制，咱们团队大多数人没有建立过社群，你们这次3天的快闪群效果很好，所以希望把你们梳理建立社群和社群运营的流程，总结的社群营销的经验，分享给大家，让大家知道如何建立社群，通过什么样的互动活动增加群成员的活跃度和参与度，提升各团队顾客粘性和销售业绩。（明确意图方向）\u003c/p>\u003cp>我：在腾讯会议分享吧？对展示内容格式有什么要求吗？\u003c/p>\u003cp>领导：没有特别的要求，图文结合把建群和运营的过程说清楚就行。\u003c/p>\u003cp>我: 那我整理个PPT吧，把前期的筹备、福利活动的策划、分享环节安排等用文字描述清楚，再把我们自己制作的活动图片、邀约海报展示一些,这样图文并茂呈现比较清楚，还有一些关键时刻的录屏视频，让大家更直观的了解整个过程和关键点。这样可以吗？\u003c/p>\u003cp>领导: 好的，可以。期待你的精彩分享！(明确品质要求。在领导没有具体要求的情况下，自己主动提出，并征求领导意见)\u003c/p>\u003cp>最终此次分享得到了各个团队的好评，分享后各团队的社群也遍地开花\u003c/p>\u003cp>A2:\u003c/p>\u003cp>拆书家晋级的拆书分享，可以看做一个自我规划和与他人合作的相结合的工作任务，今天是1-1的分享，我计划在8月完成1-2的拆书分享。\u003c/p>\u003cp>在着手准备1-2的分享之前，先按照三个关键信息逐一确认。\u003c/p>\u003cp>时间期限——就是自己的计划，期望在8月29日完成拆书分享，需要与分舵长老确认时间是否可以。如果没有问题，倒推时间，在8月15日确定选书和拆页，8月19日完成拆书逐字稿，给观察家留出批阅的时间，也给自己留出修改的时间\u003c/p>\u003cp>意图方向——认真阅读拆书家成长手册，需要对1-2的训练目标非常清晰，比1-1提升的技能，是需要带领学习者分组学习讨论，并催化学习者规划应用。\u003c/p>\u003cp>品质要求——这里分为分享前的准备和现场呈现，与1-1类似，需要提前准备拆书预备表，可以向师父要一份是成功拆书的1-2的预备表进行参考，完成逐字稿之后请师父批阅。对于更高品质的现场呈现，需要请教师父用什么样的方式呈现和表达，是能够让分享效果更好的。比如分组有什么要点？在引导学员讨论的时候，用什么样的指令会更清晰？对分享的学员提供的事例和应用，应该如何总结？\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1660645699000,"updated_at":1661823507000,"ria":true},{"id":13741,"topic":"高效汇报3步法","learn_goal":"","remark":"在快节奏的职场中，跟上级汇报时， 在平行部门沟通时。还没交代完情况， 就被对方中断，被对方提问进行。 \n那是因为的你的陈述不够直击重点，不够高效呀。\n掌握“高效汇报3步法”能帮助我们快速将事情讲清楚道明白，为沟通双方营造高效沟通的氛围。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"陆琴","city":"长沙市"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>大家好， 我是陆琴，我的三个标签是外贸工作者，讲师， 宝妈。 今天是我的第TF2-2的拆书晋级场。我要拆解的片段仍旧是关于沟通，高效沟通。为了今天学习活动的开展，我把现场的小伙伴分几个小组，从我右手边起，两人或三人为一组（根据现场实际情况来）。\u003c/p>\u003cp>【FAB法】介绍图书（1-2分钟）\u003c/p>\u003cp>（F）今天我要拆的片段选自《麦肯锡工作法：麦肯锡精英的39个工作习惯》，这本书是一本职场技能类的经典书籍，由日本作家大岛祥誉所著。这本书讲述的是全球顶尖咨询公司之一的麦肯锡咨询公司他们团队的工作方法。\u003c/p>\u003cp>（A）相较于其他职场类书籍，这本书有着麦肯锡的强大背书，同时书中给出的是贴近实际工作业务，以实现“品质*效率”为主题，介绍了麦肯锡内部人士重视的39个工作习惯。\u003c/p>\u003cp>（B）\u003c/p>\u003cp>B1:培根说过：“习惯是一种顽强而巨大的力量。本书中的39个工作习惯是麦肯锡亲身实践的“立竿见影”的简单习惯，只要掌握这些习惯就能提高职场人士解决问题的能力。\u003c/p>\u003cp>B2: 今天要分享的片段就是关于怎么30秒高效沟通将事情说清道明。9成以上的人习惯按照事情的时间顺序传递信息， 这样容易造成长篇大论。 但对于领导而言，时间非常宝贵，没有时间听这些不利于决策的过程， 甚至还会认为你抓不住重点，能力不行，导致你错失一些升职加薪的机会。\u003c/p>","ratings_count":1,"texts":[{"id":17772,"quote":"\u003cp>片段1:(P60)\u003c/p>\u003cp>《麦肯锡工作法》\u003c/p>\u003cp>高效沟通3步法---\u003c/p>\u003cp>不管是说明还是“报、联、商”，首先都要将想要传达的内容氛围一下3个要素。\u003c/p>\u003cp>1. 现状的掌握情况。\u003c/p>\u003cp>2. 对现状的解释以及理由。\u003c/p>\u003cp>3. 结论以及解决方法。\u003c/p>\u003cp>最简单的例子就是第一章中提到过的“空、雨、伞”。 假设你要全一个准备出门的人带雨伞， 那么过程应该是这样的。\u003c/p>\u003cp>例1. 建议对方带雨伞\u003c/p>\u003cp>1. 现状的掌握情况。\u003c/p>\u003cp>“**先生，请等一下！抬头看一看， 满天都是乌云。”\u003c/p>\u003cp>2. 对现状的解释以及理由\u003c/p>\u003cp>“这说明一会儿很有可能突然下雨。可能会被淋湿。”\u003c/p>\u003cp>3. 结论以及解决方法。\u003c/p>\u003cp>“请带上这把雨伞。”\u003c/p>","explains":"\u003cp>【学习目标】\u003c/p>\u003cp>通过原文拆页片段，在工作事项或项目的跟进中， 能掌握“高效汇报3步法”能帮助我们快速将事情讲清楚道明白，为沟通双方营造高效沟通的氛围。 \u003c/p>\u003cp>【举例子】在我们职场工作中，常常会出现这样一个画面，在上司需要你手头某个项目的进展汇报时，你开始将时间拉到项目开端，如从4月份接受该项目，我做了哪些哪些工作， 然后娓娓道来到，结果由于配合方不给力，事情搁置，没能完成。 上司听了之后，一脸茫然，对于你的描述， 不清晰你对该汇报的主张与目的是什么，是你有解决方案自己搞定让上司仅知悉就好，还是说你需要上司如何来支持你。 估计没个5-10来分钟，上司难以get到汇报人的点（主张）。 大家都知道上司的时间非常宝贵， 因此高效的汇报就十分必要。 \u003c/p>\u003cp>通过原文拆页片段，我提炼出了“高效汇报3步法”\u003c/p>\u003cp>第一步：明现状\u003c/p>\u003cp>第二步：道缘由\u003c/p>\u003cp>第三步：给结论与解决方法\u003c/p>\u003cp> 举个例子，我的工作每周都需要跟上司做周度汇报， 其目的是让上司知悉我手头各项工作的状况和进展进度。 就上周5，在上司的办公室，安排了30分钟做周度工作汇报。在汇报前，我在本子上列出了手头跟进的10多项工作；那这样的沟通是不是很挑战？我运用了高效汇报3步法，进行各工作的汇报。 其中一件就是，我们外派员工去工厂学习的项目进度汇报。 \u003c/p>\u003cp>第一步：先明现状，把目前项目的情况讲清楚，我跟上司说“目前，我司的驻厂学习的厂家与课程内容初步确定，但本周推进缓慢；”\u003c/p>\u003cp>第二步：道缘由：“因为，工厂负责人本周较忙，具体驻厂细节和学习目标未能确认；”说明本周推进该项工作缓慢的主要与核心原因。\u003c/p>\u003cp>第三步，给结论与解决方法：“我跟对方约了下周电话会议来落实，计划3月底启动项目，派送第一批驻厂学习员工。”让对方清晰的结论与解决方法。\u003c/p>\u003cp>那我的汇报是：“目前，我司的驻厂学习的厂家与课程内容初步确定，但本周推进缓慢；因为，工厂负责人本周较忙，具体驻厂细节和学习目标未能确认；我跟对方约了下周电话会议来落实，计划3月底启动项目，派送第一批驻厂学习员工。”100个字， 30秒把整件事情进展说明清楚。\u003c/p>\u003cp>【Where预防异议+讲解】有些朋友反馈， 我的事情真的还蛮复杂，那你在汇报前可以利用该工具来帮你厘清思路，抓住核心的现状，缘由和结论与解决方法，来达到高效沟通。同时也需要审视沟通的事项，我们的“高效汇报3步法”对于双方都知悉的未完待续的事项，对于其阶段性的进展汇报是非常高效。如果是已经完成的的事项，我们只要总结反馈。 如果是较为复杂方案的探讨，那势必是集思广益，我们就要选用其他方法了， 如头脑风暴等。总而言之， 在工作进展汇报中，能1句话说明白的我们不用2句。 \u003c/p>\u003cp>最后关于这3步的顺序，没有固定的要求。一般来说，相对正向振奋的进展信息，比方说是出乎意料好的情况， 我们可以将第3步先结论，再明现状与道缘由。\u003c/p>","interaction":"\u003cp>【A2】拆书家提问设计\u003c/p>\u003cp>（逐字稿）：\u003c/p>\u003cp>请大家想想未来的一周甚至一个月内，在办公室跟上司或主管汇报工作进展；在公司与其他部门共同推进项目的沟通，以及与合作公司的合作事项的进展沟通，\u003c/p>\u003cp>请小组内相互分享你会遇到的场景， 注意只需要说明任务沟通场景就可以， 不用发散。\u003c/p>\u003cp>下面给到每人1分钟的时间分享讨论。\u003c/p>\u003cp>\u003cu>Summer 汇报场景\u003c/u>：未来一周在公司和上司汇报会议室场地租赁事宜\u003c/p>\u003cp>【A2+】拆书家提问设计\u003c/p>\u003cp>（逐字稿）：\u003c/p>\u003cp>感谢这几位伙伴的场景分享，大家有具体任务沟通场景了。接下来，请大家想象下， 下周你来到上司的办公室，他每天不是会议中，就是在会议的路上，时间非常宝贵。你会怎么用今天学到的“高效汇报3步法”\u003c/p>\u003cp>第一步：明现状；第二步：道缘由；第三步：出结论与解决方法 。\u003c/p>\u003cp>在写下的汇报事件上， 如何高效沟通？给到大家每个人2分钟的时间，小组内互相分享你的实际应用。\u003c/p>\u003cp>\u003cu>Summer 高效汇报规划的分享：\u003c/u>\u003c/p>\u003cp>\u003cu>明现状：办公室租赁项目盈收落后\u003c/u>\u003c/p>\u003cp>\u003cu>道缘由：宣传力度不强， 我司费用较高，大家不知道我们会议室能租赁；\u003c/u>\u003c/p>\u003cp>\u003cu>给结论和解决方法：发传单，地推的形式进行推广，市面行情的调查，通过这样的形式提升盈收。\u003c/u>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1657413169000,"updated_at":1657500077000,"ria":true},{"id":12828,"topic":"用“空雨伞”，掌控现在，把握未来","learn_goal":"","remark":"宣传语:\n\n是不是当问题发生时，捶胸顿足，当初为什么没想到。\n\n如何能把握当下，决胜未来“空雨伞”是个不错方法，帮忙你看清现状，及时作出方案，赢得未来。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"紫雨飘扬","city":"武汉市"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>大家好，我是吉淑娟，是一名IT产品经理。今天要和大家分享的片段出处《麦肯锡工作法》，此书的作者大岛祥誉是麦肯锡的资深培训师，他总结了麦肯锡内部员工最重视的39个工作习惯，熟练掌握这些习惯，可以让你的工作效率和竞争力至少提高50% 。\u003c/p>\u003cp>在正式开始之前，我们首先来进行一个分组...\u003c/p>","ratings_count":1,"texts":[{"id":16785,"quote":"\u003cp>今天我选取了书中一个片段，主题是【运用空、雨、伞--让你做到未雨绸缪】\u003c/p>\u003cp>请大家用1分钟时间阅读原文，阅读完毕请举手示意。\u003c/p>\u003cp>\u003cstrong>《麦肯锡工作法》 P17\u003c/strong>\u003c/p>\u003cp>今天你打算出去玩，一出门却发现天上都是乌云，那你就会带伞出门，这样如果真的下雨了，就不会被淋湿。这个看似简单的决策过程，其实就是解决问题的过程，可以分解为\u003cstrong>空、雨、伞\u003c/strong>三步。\u003c/p>\u003cp>\u003cstrong>l\u003c/strong> \u003cstrong>空\u003c/strong>，就是指我们\u003cstrong>面临的环境、现状和事实\u003c/strong>，天空都是乌云；\u003c/p>\u003cp>\u003cstrong>l\u003c/strong> \u003cstrong>雨，\u003c/strong>就是对我们对“空”的观察，也就是对\u003cstrong>当下状况的解释\u003c/strong>，有乌云就代表很有可能会下雨，你很有可能会被淋湿；\u003c/p>\u003cp>\u003cstrong>n\u003c/strong> \u003cstrong>伞\u003c/strong>，就是指我们因“雨”而做出的决策，也就是\u003cstrong>解决的办法\u003c/strong>，只要你带伞出门，就不会被淋湿。\u003c/p>\u003cp>\u003cstrong>事实，解释，以及解决办法\u003c/strong>，三点环环相扣，麦肯锡就把这种思考和解决问题的方法称为“空雨伞”。\u003cu>你要学会分析当下的状况，在事情发生之前就做好准备，就不会在问题来临时手足无措。\u003c/u>\u003c/p>\u003cp>实际工作中的情况更复杂，但一般也可以拆解为这三点。再举一个例子，这周末你要和心仪的姑娘进行第二次约会，你打算开车带她去郊外玩，结果车子在路上堵得水泄不通，姑娘的心情越来越差，最后给了你一个白眼，不欢而散。这就是不懂得用“空雨伞”方式思考的结果。既然选择了周末出行，就应该预料到可能会出现堵车、下雨等各种风险，并提前做好准备，你可以在手机里下一些姑娘喜欢的音乐，或者为她准备一个小小的礼物，姑娘说不定还会觉得你很贴心呢。\u003c/p>\u003cp>那把这个心仪的姑娘换成重要的客户呢？道理是一样的。不打无准备之仗，只有在每一次出发之前，利用你已经收集到数据和资料，尽可能地预估可能会出现的各种问题，并准备相应的解决办法，才能够在大雨来临之时，避免被淋湿。\u003c/p>","explains":"\u003cp>看到伙伴们大部分都完成阅读，我们一起来看一下这段文字带给了我们什么。\u003c/p>\u003cp>【Why】我们在工作、生活中经常会面临各种雾里看花情况，对事情缺乏预见性，只有在问题发生之后才会开始后悔，为什么没有早点想到？\u003c/p>\u003cp>【What】文中的“空、雨、伞”就是帮我们发现现象，做出预测和判断，最后选择合适的解决方案。\u003c/p>\u003cp>【How】具体步骤包括空、雨、伞。\u003c/p>\u003cp>\u003cstrong>1、空\u003c/strong>：\u003cstrong>事实，即现状的情况。\u003c/strong>比如，我们国庆准备带全家回洛阳，提前看了天气预报，那几天，洛阳高温只有14°这就是现状。\u003c/p>\u003cp>\u003cstrong>2、雨：对现状的解释，和预测\u003c/strong>\u003c/p>\u003cp> 由于当时武汉平均都是30°+的天气，比较热，而洛阳的早晚温差比较大，和武汉相差十几度，如果不考虑周全，骤热骤冷的天气，很容易让孩子们生病。\u003c/p>\u003cp>3、\u003cstrong>伞：结论，以及解决方法\u003c/strong>\u003c/p>\u003cp> 为了全家人不被两边的天气折磨，决定即带夏装，还要带些厚点的秋装抵抗低温的寒冷，比如回去时穿着夏装，半路上天气冷了，就可以马上穿上厚衣服，回来时也一样，可以顺利从深秋过渡到夏天。\u003c/p>","interaction":"\u003cp>\u003cstrong>接下来是我们小组分享的环节。\u003c/strong>\u003c/p>\u003cp>大家回想下，你生活中有没有出现过因为没有根据情况进行预判导致的失误呢？如果有，具体是什么事情呢？\u003c/p>\u003cp>请大家在组内轮流进行分享，每个人1分钟，大家都分享结束之后，我再来邀请1位小伙伴分享。\u003c/p>\u003cp>（4分钟）\u003c/p>\u003cp> \u003cstrong>【能够成功催化学习者A2的应用】技能点\u003c/strong>\u003c/p>\u003cp>感谢伙伴们的分享。大家想想接下来一周你可以用“空雨伞”三步骤来预测和处理一件什么事情呢？为了方便，我制作了一张表格，请大家在表格上写下来。我们写的时候，要假设一个具体的场景下，比如什么时间、什么地点，参与者发生了什么样事情，并依次写出“空、雨、伞”这三个步骤的具体内容。\u003c/p>\u003cp>给大家2分钟时间。。。。请一位伙伴分享一下。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1640056296000,"updated_at":1640854104000,"ria":true},{"id":11796,"topic":"用“逻辑分析笔记”将自己的情绪写出来","learn_goal":"","remark":"《麦肯锡情绪管理法》 用“逻辑分析笔记”将自己的情绪写出来","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"naity0304","city":"潍坊市"},"club":{"name":"潍坊飞鸢分舵","city":"潍坊"},"prologue":"\u003cp>【学习目标】\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够运用逻辑分析笔记的三个步骤，将情绪稳定冷静下来，找到解决问题的办法。\u003c/p>\u003cp>\u003cstrong>环节1：图书介绍（2分钟）\u003c/strong>\u003c/p>\u003cp>【自我介绍】：\u003c/p>\u003cp>大家好！我是田妮，很高兴认识大家。我是一名学前教育工作者，我喜欢孩子，喜欢阅读，希望通过学习提升自我，助人达己。\u003c/p>\u003cp>\u003cstrong>【图书介绍（FAB法）】\u003c/strong>：\u003c/p>\u003cp>今天我拆解的片段选自《麦肯锡情绪管理法》中“将自己的情绪写出来”部分。在阅读前,我先来为大家介绍一下这本书。\u003c/p>\u003cp>【Feature】\u003cstrong>:\u003c/strong>\u003c/p>\u003cp>这本书是麦肯锡系列书籍之一，由麦肯锡资深合伙人、日本畅销书作家大岛祥誉书写。\u003c/p>\u003cp>【Advantage】\u003cstrong>:\u003c/strong>\u003c/p>\u003cp>与同类书相比较，这本书和通常情绪管理的书最大的不同是它不让你陷于情绪困扰本身，而是直击情绪产生背后的本质，将问题解决，从而消除情绪的产生根源。类似中医病根去了，症状就没了！\u003c/p>\u003cp>【Benefit】\u003cstrong>:\u003c/strong>\u003c/p>\u003cp>在职场中，面对各种压力，你如何处理自己的负面情绪，利用情绪更好地完成任务？这本书能帮你解密。它通过简单易学的4个步骤、8个技巧和6种方法，用简练的语言、详实的例子，帮助大家将情绪“可视化”，把情绪问题变成具体问题来解决，从而达成管理情绪，让自己成为职场精英的目的。\u003c/p>","ratings_count":1,"texts":[{"id":15740,"quote":"\u003cp>\u003cstrong>环节2：R阅读原文（2分钟）：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请大家打开刚才下发的拆页，这个片段摘自书中的第92-95页(有图)，讲的是逻辑分析笔记的三个步骤，给大家2分钟左右时间阅读，看完的请抬头或举手示意我。好，请开始阅读。\u003c/strong>\u003c/p>\u003cp>片段：将自己的情绪写出来——“逻辑分析笔记”\u003c/p>\u003cp>来源：日本作家 大岛祥誉《麦肯锡情绪管理法》\u003c/p>\u003cp> （北京时代华文书局）p92-95（有图，实际只有2页）\u003c/p>\u003cp>冷静分析情绪的“逻辑分析笔记”\u003c/p>\u003cp>首先,需要准备一个A4大小的笔记本。在左侧页面写上日期和发生的事情。比如“今天被上司训斥‘我交给你的任务怎么还没完成’”。\u003c/p>\u003cp>再在下面写出当时的情绪,“太过分了”“令人生气”“很难过”……\u003c/p>\u003cp>将情绪写出来之后,再将自己感到“难过”、感到“生气”的原因写在下面。\u003c/p>\u003cp>“眼看那项工作任务就要完成了,结果却被这样说,真令人生气”“我明明很努力地在做了,上司一点也不理解我,真让人难过”。\u003c/p>\u003cp>然后,再针对这些原因进行更加深入的思考,比如“对看不到自己辛苦付出的上司感到愤怒和失望”“对上司不认可自己的成绩感到不安”“长此以往自己恐怕没有升职的可能,这种担心和不安变成了愤怒”。这样就能发现自己的情绪其实不仅仅是愤怒,其中还隐藏着各种各样的情绪。\u003c/p>\u003cp>最后,用“ So what”(这样做的目的是什么)和“Why so”(为什么这样做)对情绪进行深入的思考。\u003c/p>\u003cp>当对情绪进行自我分析的时候,“ So what”(这样做的目的是什么)和“ Why so”(为什么这样做)是非常有效的两个框架。\u003c/p>\u003cp>这也是麦肯锡问题解决方法的基础,通过不断地自问自答,使逻辑变得更加缜密和牢固。\u003c/p>\u003cp>假设现在的问题是“必须通过营销来获得新顾客”。那么通过思考“ So what”(这样做的目的是什么),就会发现“通过获得新顾客来提高销售额”,然后再思考“Why so”(为什么这样做)，就会发现“通过提高销售额来保证公司的利润”。\u003c/p>\u003cp>这样一来我们就发现了更加接近本质的课题:“如果提高公司整体的利润是最终目的，那么有没有其他的改善点呢?”\u003c/p>\u003cp>在逻辑分析笔记的左侧进行一定程度的自我分析之后，接下来就可以利用“So what”(这样做的目的是什么)和“Why  so”(为什么这样做)在右侧页面上写出解决办法。比如“在接到工作任务时向上司说明自己的状况&quot;“接受工作任务后将其作为‘自己的工作’承担起责任”。\u003c/p>\u003cp>将自己在职场产生的情绪都如实地记录下来，在思考导致这些情绪产生的原因的同时思考解决办法。这也相当于一种将情绪变为有待解决的问题的训练。\u003c/p>\u003cp>通过将情绪可视化，可以使自己把握情绪的内在情况，然后利用逻辑思考来找出对情绪问题的解释和解决办法。逻辑分析笔记也是对自己情绪和问题解决的宝贵记录，日后可以当作情绪管理的实践记录来使用。\u003c/p>","explains":"\u003cp>\u003cstrong>环节3：I拆书家讲解引导（6分钟）\u003c/strong>\u003c/p>\u003cp>好，我看到大家基本都看完了。\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>这个片段是告诉了我们一种---如何利用的三个步骤把负面情绪变成“可视化”的问题来解决的逻辑分析笔记法，利用这种方法可以帮助我们解决问题，从根本上达成管理情绪的目的。\u003c/p>\u003cp>\u003cstrong>【Why强调不这么做的坏处】(约1.5分钟)\u003c/strong>\u003c/p>\u003cp>在聊具体的步骤前,我想先来说说我自己经历的情绪管理失败的例子。\u003c/p>\u003cp>\u003cstrong>(自己的例子)\u003c/strong>\u003c/p>\u003cp>我们六一亲子活动当天的早上，正忙着清点家长孩子数量，准备乘车出发时，朱园长过来跟我反映，中班的小李老师哭着不要参加活动了，原因是她晕车还要主持活动却不能坐在车前面，她不能理解也拒绝接受忍辱负重的现实，老师们已经都去劝过了，还是不行，希望我能出面劝说。我一听这事就有些恼火，没有责任心，不顾全大局，再说也没有时间沟通了，就直接生气地说：“既然接受不了，非要回家那你就回家吧!”\u003c/p>\u003cp>\u003cstrong>(大多数人常见做法)\u003c/strong>\u003c/p>\u003cp>跟我一样，在碰到问题或冲突引发矛盾时，大多数人的做法都是：\u003c/p>\u003cp>1.被负面情绪所控制。比如：伤心、发怒等\u003c/p>\u003cp>2.被事件表面现象所迷惑。\u003c/p>\u003cp>\u003cstrong>(不按拆页做的坏处)\u003c/strong>\u003c/p>\u003cp>1.大部分人很容易被负面情绪所控制，陷入负面情绪里而不能自拔。这将容易造成贻误时机，错过解决问题的最佳时间；还会影响后续的工作顺利进行；更不利于同事朋友之间的和睦相处。\u003c/p>\u003cp>2.被事件表面现象所迷惑，会忽略事件产生的本质问题，解决起来也是治标不治本，以后还会有类似情况的再次发生。\u003c/p>\u003cp>\u003cstrong>【How】（约4分钟）\u003c/strong>\u003c/p>\u003cp>而使用情绪管理法的“逻辑分析笔记”这个方法，能让我们避免出现上述不利情况，快速找出问题本质，从根本上解决问题，杜绝矛盾及负面情绪的产生。还是用我刚才的例子，我们一起采用逻辑分析笔记法，看看问题应该如何解决。\u003c/p>\u003cp>\u003cstrong>第1步：写。\u003c/strong>写出引起自己生气、难过、烦躁等负面情绪的时间、地点、人物、原因、经过、结果。\u003c/p>\u003cp>比如：刚才，在大门口，小李老师因为晕车要求坐在车前面，没同意她的无理要求就拒绝继续参加活动，为此，我很生气、烦躁、失望、焦虑、愤怒。\u003c/p>\u003cp>\u003cstrong>第2步：辩。需要有两辩。\u003c/strong>\u003c/p>\u003cp>1.分辨事件发生的起因；\u003c/p>\u003cp>2.换位思考双方尽可能多的负面情绪，找到情绪产生的合理性原因。\u003c/p>\u003cp>（感受负面情绪时，可以考虑出自己知道的所有负面情绪的词汇，然后一个个的对应考虑自己当时是否存在上述情绪。）\u003c/p>\u003cp>1.事件的起因是小李老师晕车（前期大家都不知道这事）却发现自己不能坐在车前面而生气难过，甚至说出了不参与活动的话。\u003c/p>\u003cp>2.换位思考，分辩双方负面情绪产生的合理性原因。\u003c/p>\u003cp>李老师：a.难过：自己晕车不被接纳，让别的老师以为自己自私，不顾大局。b.委屈：同样都是人，为啥老师就得忍，不被尊重。c.担心：担心晕车后不能完美的主持节目，会被家长和同事笑话，影响整个活动质量。d.逃避：那还不如不参加也不会丢人。\u003c/p>\u003cp>我：a.生气：李老师不提前告知，现在也不可能让家长再给她让座；b.失望：不能以大局为重，临阵脱逃；c.烦躁：没时间了可事情必须解决，否则李老师真不去，以后可能存在没面子继续在我园工作的情况，那更麻烦；d.懊恼：自己提前没有考虑到老师也存在身体不适的问题。\u003c/p>\u003cp>\u003cstrong>第3步：解。\u003c/strong>根据第二步辨别出的起因，找出根源所在，解决问题。当然，有些原因比较清晰，可以很容易找到。如果原因不很清晰，那么你可以尝试代入一下，用你现在找到的原因代入场景中，看是不是矛盾就不会产生，如果是那恭喜你找了是根源；如果不是，请多问自己几个Why so，相信问题根源一定会找到。\u003c/p>\u003cp>找到上述事件发生的起因后，我认为本次事件的根源在于解决小李老师晕车不能坐在车后面的问题，同时也应该承认自己工作的疏忽。我又再次跟她沟通，承认在开始设计活动前忽视了调查老师的情况和感受，以后活动会注意；同时也再次肯定她一直以来的责任心，并摆出她不参加将给大家带来的困难和影响；小李老师听后表示自己当时确实情绪过于激动不冷静，自己也存在没提前告诉大家晕车情况的问题，并表示还是希望能参加活动。后经协商家长，由一位自驾的家长带小李老师一同到达景区。问题解决，一切自然都顺畅起来，负面情绪自然也就不再存在。\u003c/p>\u003cp>通过这个例子，相信大家一定更清晰地明白了这个方法的使用步骤了。\u003c/p>\u003cp>【Where】\u003c/p>\u003cp>这个方法很好用，适用的面也比较广。可以用于工作中与同事或领导之间产生矛盾出现负面情绪时；也可用于家庭成员之间因为意见相左发生矛盾时；当自己想客观地了解自己，解决现状问题时也可使用这个方法。当然，这个方法不适用于同事之间已经有私人恩怨的矛盾冲突中，也不适用于心理疾病患者（自闭症焦虑症等）的消极情绪处理。\u003c/p>","interaction":"\u003cp>\u003cstrong>环节4：A1激活学习者经验（显像提问）（2分钟）\u003c/strong>\u003c/p>\u003cp>下面请大家回顾一下，自己最近的一次比较强烈的消极情绪经历。是在工作中跟同事领导？还是在家里跟孩子或家人？他们是不是让你产生了气愤、紧张、焦虑、担忧、郁闷、失望、挫败、抑郁、伤心、恐惧、自责等中的一种或几种情绪? 那么请你回忆一下造成你产生了这些负面消极情绪的事件，发生在什么时间、什么地点、因为什么人、因为什么事？请想一想，1分钟后，我们请一位小伙伴分享一下。\u003c/p>\u003cp>\u003cstrong>【A1学习者案例记录】\u003c/strong>\u003c/p>\u003cp>袁晓莉分享内容：昨天我跟我儿子一同去足球班参加第二次试课，课后儿子表示很喜欢，于是报名缴费后，办理领装备等手续时，看到装备和队服，儿子一会儿这队服不好，一会儿装备有问题等，我听来听去，感觉就是儿子又想反悔了。我很生气，也批了孩子一通，一路互不搭理回家了。到现在想起来我还很生气呢。\u003c/p>\u003cp>\u003cstrong>环节5：A1+学习者反思加工（7分钟）\u003c/strong>\u003c/p>\u003cp>感谢小伙伴的分享。现在，请大家结合本次片段教给大家的三步法，把自己的案例进行反思和加工，如果再遇到类似情况，你可以怎样应用刚才学的方法去应对，从而解决问题。\u003c/p>\u003cp>按照原来的分组方法，请大家小组内分享。每人1-2分钟的时间，总计5分钟，最后我们请每组派一名代表分享一下自己的经验。下面请各组开始。\u003c/p>\u003cp>\u003cstrong>【A2学习者案例记录】\u003c/strong>\u003c/p>\u003cp> 袁晓莉主动要求分享：通过刚才对这个片段的学习和讲解，我分析了一下当时的情况，我认为当时孩子出现后悔的情绪可能有两点：1.昨天天气特别热，儿子训练了一个多小时，应该是非常疲惫的，所以在看到问题后情绪也不稳定，我应该不急于评判，等回家休息后再谈，可能就没事了。2.孩子比较内向，感觉应该是还没有做好跟正式队员一样的思想准备，看到要穿队服，感觉自己水平还不足，怕丢人的情绪存在。这个我回家后可以通过鼓励等方式解决。这个方法很有效，帮到了我，谢谢！\u003c/p>\u003cp>谢谢小伙伴们的分享。（根据分享情况简短点评）\u003c/p>\u003cp>最后，请大家将写好的便签交给我，感谢大家的配合，我的分享到此结束！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1624440376000,"updated_at":1624440464000,"ria":true},{"id":11520,"topic":"高效沟通三步法","learn_goal":"","remark":"在工作事项的商谈中， 在日常事情的联络中， 向上级汇报中， 向下级指导中，“高效沟通要点梳理3步法”助力你快速将事情讲清楚道明白。","level":"TF2-2","duration":16,"status":30,"type":0,"chaishujia":{"username":"陆琴","city":"长沙市"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>大家好， 我是陆琴，我的三个标签是外贸工作者，讲师， 宝妈。 今天是我的第TF2-2的拆书晋级场。我要拆解的片段仍旧是关于沟通，高效沟通。为了今天学习活动的开展，我把现场的小伙伴分几个小组，从我右手边起，两人或三人为一组（根据现场实际情况来）。\u003c/p>\u003cp>【FAB法】介绍图书（1-2分钟）\u003c/p>\u003cp>（F）今天我要拆的片段选自《麦肯锡工作法：麦肯锡精英的39个工作习惯》，这本书是一本职场技能类的经典书籍，由日本作家大岛祥誉所著。这本书讲述的是全球顶尖咨询公司之一的麦肯锡咨询公司他们团队的工作方法。\u003c/p>\u003cp>（A）相较于其他职场类书籍，这本书有着麦肯锡的强大背书，同时书中给出的是贴近实际工作业务，以实现“品质*效率”为主题，介绍了麦肯锡内部人士重视的39个工作习惯。\u003c/p>\u003cp>B1:培根说过：“习惯是一种顽强而巨大的力量。本书中的39个工作习惯是麦肯锡亲身实践的“立竿见影”的简单习惯，只要掌握这些习惯就能提高职场人士解决问题的能力。\u003c/p>\u003cp>B2: 今天要分享的片段就是关于怎么30秒高效沟通将事情说清道明。9成以上的人习惯按照事情的时间顺序传递信息， 这样容易造成长篇大论。 但对于领导而言，时间非常宝贵，没有时间听这些不利于决策的过程， 甚至还会认为你抓不住重点能力不行，导致你错失一些升职加薪的机会。\u003c/p>","ratings_count":1,"texts":[{"id":15442,"quote":"\u003cp>片段1:(P60)\u003c/p>\u003cp>《麦肯锡工作法》\u003c/p>\u003cp>高效沟通3步法---\u003c/p>\u003cp>不管是说明还是“报、联、商”，首先都要将想要传达的内容氛围一下3个要素。\u003c/p>\u003cp>1. 现状的掌握情况。\u003c/p>\u003cp>2. 对现状的解释以及理由。\u003c/p>\u003cp>3. 结论以及解决方法。\u003c/p>\u003cp>最简单的例子就是第一章中提到过的“空、雨、伞”。 假设你要全一个准备出门的人带雨伞， 那么过程应该是这样的。\u003c/p>\u003cp>例1. 建议对方带雨伞\u003c/p>\u003cp>1. 现状的掌握情况。\u003c/p>\u003cp>“**先生，请等一下！抬头看一看， 满天都是乌云。”\u003c/p>\u003cp>2. 对现状的解释以及理由\u003c/p>\u003cp>“这说明一会儿很有可能突然下雨。可能会被淋湿。”\u003c/p>\u003cp>3. 结论以及解决方法。\u003c/p>\u003cp>“请带上这把雨伞。”\u003c/p>","explains":"\u003cp>【学习目标】\u003c/p>\u003cp>通过原文拆页片段，在工作事项跟进沟通中， 能掌握“高效沟通3步法”能帮助我们快速将事情讲清楚道明白。\u003c/p>\u003cp>【举例子】在我们职场工作中，常常会出现这样一个画面，在上司需要你手头某个项目的进展汇报时，你开始将时间拉到项目开端，如从1月份接受该项目，我做了哪些哪些工作， 然后娓娓道来到，结果由于配合方不给力，事情搁置，没能完成。 上司听了之后，一脸茫然，不清晰你对该汇报的主张，是你有解决方案自己搞定让上司仅知悉就好，，还是说你需要上司如何来支持你。 估计没个10来分钟，上司难以get到汇报人的点（主张）。 大家都知道上司的时间非常宝贵， 因此高效的沟通就十分必要。 \u003c/p>\u003cp> 举个例子，我的工作每周都需要跟上司做周度汇报， 其目的是让上司知悉我手头各项工作的状况和进展进度。 就上周5，在上司的办公室，安排了30分钟做周度工作汇报。在汇报前，我在本子上列出了手头跟进的10多项工作；那这样的沟通是不是很挑战？我运用了高效沟通3步法，进行各工作的汇报。 其中一件就是，我们外派员工去工厂学习的项目进度汇报。 \u003c/p>\u003cp>第一步：先明现状，把目前项目的情况讲清楚，我跟上司说“目前，我司的驻厂学习的厂家与课程内容初步确定，但本周推进缓慢；”\u003c/p>\u003cp>第二步：道缘由：“因为，工厂负责人本周较忙，具体驻厂细节和学习目标未能确认；”说明本周推进该项工作缓慢的主要与核心原因。\u003c/p>\u003cp>第三步，给结论与解决方法：“我跟对方约了下周电话会议来落实，计划3月底启动项目，派送第一批驻厂学习员工。”让对方清晰的结论与解决方法。\u003c/p>\u003cp>那我的汇报是：“目前，我司的驻厂学习的厂家与课程内容初步确定，但本周推进缓慢；因为，工厂负责人本周较忙，具体驻厂细节和学习目标未能确认；我跟对方约了下周电话会议来落实，计划3月底启动项目，派送第一批驻厂学习员工。”100个字， 30秒把整件事情进展说明清楚。\u003c/p>\u003cp>【预防异议+讲解】有些朋友反馈， 我的事情真的还蛮复杂，那你在汇报前可以利用该工具来帮你厘清思路，抓住核心的现状，缘由和结论与解决方法，来达到高效沟通。同时也学要审视沟通的事项，我们的“高效沟通3步法”对于双方都知悉的未完成事项，对于其进展的汇报，商谈，联络都是非常高效。如果是已经完成的的事项，我们只要进行现状的说明汇报即可。 如果是较为复杂方案的探讨，那势必是集思广益，我们就要选用其他方法了， 如头脑风暴等。总而言之， 在工作进展沟通中，能1句话说明白的我们不用2句。 \u003c/p>\u003cp>最后关于这3步的顺序，没有固定的要求。一般来说，相对正向振奋的进展信息，比方说是出乎意料好的情况， 我们可以将第3步先结论，再明现状与道缘由。\u003c/p>","interaction":"\u003cp>A2\u003c/p>\u003cp>拆书家提问设计\u003c/p>\u003cp>（逐字稿）：请大家想想未来的一周甚至一个月内，在办公室跟上司或主管汇报工作进展；在公司与其他部门共同推进项目的沟通，以及与合作公司的合作事项的进展洽谈，请小组内相互分享你会遇到的场景， 注意只需要说明任务沟通场景就可以， 步用发散。\u003c/p>\u003cp>下面给到每人1分钟的时间分享讨论。\u003c/p>\u003cp>学习者案例记录： \u003c/p>\u003cp>分享者：娜姐\u003c/p>\u003cp>下周5在公司向老板汇报部门内训师的筹备工作。\u003c/p>\u003cp>A2+\u003c/p>\u003cp>拆书家提问设计\u003c/p>\u003cp>（逐字稿）：\u003c/p>\u003cp>感谢这几位伙伴的场景分享，大家的具体任务沟通场景了。接下来，请大家想象下， 下周你来到上司的办公室，他的桌上摆满了各种文件，恰好有个文件，就是你们手头需要汇报，他才能签批。你会怎么用今天学到的“高效沟通3步法”第一步：明现状；第二步：道缘由；第三步：出结论 。在写下的汇报事件上， 如何高效沟通？给到大家每个人2分钟的时间，小组内互相分享你的实际应用。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>分享者：瑞斯小姐姐\u003cbr>事件：金融类的客户，广告上线不符合公司常规流程，然后我们那他的资料区总部特批，目前状态在总部风控部特批， 缘由是总部时间紧张，没有推进。 \u003c/p>\u003cp>汇报内容：经理， 目前金融类客户的广告特批暂无推进，由于总部风控部近期工作量大， 一直未审核；我们需要您和总部沟通推进，等待总部放行，在3月底完结这个案子。  \u003c/p>\u003cp>想必经理在了解这个案子前因的情况下， 就当下的情况能快速决策并推进该事项。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1620738023000,"updated_at":1621312025000,"ria":true},{"id":10895,"topic":"用“三个要点”法简洁传达信息","learn_goal":"","remark":"运用这个方法可以在时间紧张的时候快速准确传递出有用的信息","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"贾思敏","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"\u003cp>大家好，我叫贾思敏，目前在一家建设公司做安全管理工作，平时比较喜欢看书，而且比较喜欢看致用类书籍，希望能够运用知识提升自己的能力，利用别人的一些有效经验帮助自己解决工作和生活中的问题。几年前和拆书帮结缘，参加了一场拆书帮和十点读书会联合组织的活动，听了佐江老师拆《微习惯》这本书，当时了解到拆书帮这个组织就还挺感兴趣的，一群学习爱好者一起升级打怪，锻炼自身能力。今年参加了两次线下活动之后，终于踏上了成为拆书家的旅程，希望可以在这个过程中和大家共同成长。\u003c/p>\u003cp>下面我来介绍一下什么是“拆书”？什么是“拆书帮”？\u003c/p>\u003cp>“拆书”是一种学习方法论，它强调以学习者为中心，而不是以知识为中心，需要学习者将自己的经验和学到的知识进行关联，然后规划出具体的目标和行动，运用这种方法来提升能力或者解决问题。\u003c/p>\u003cp>想要了解拆书法就必须知道拆书法的\u003cstrong>一个核心和两种形式。\u003c/strong>\u003c/p>\u003cp>一个核心就是RIA拆书法。什么是RIA？RIA是三个英文单词的缩写。\u003c/p>\u003cp>R（reading），是指阅读原文拆页，这个拆页主要是来源于一本致用类书籍，这是拆书法的适用边界。\u003c/p>\u003cp>I（interpretation）是指重述知识，它指的是用自己的话将这段内容说一遍。当你能够用自己的语言把一段内容讲清楚，才算真正理解了这段内容。\u003c/p>\u003cp>A  （appropriation）是指拆为己用，A又包括了A1和A2两个层面。\u003c/p>\u003cp>A1是描述自己的过往经验，看看自己有没有经历过什么和原文匹配的成功或失败的事情，而且是可以用拆页中的方法来解决的 。\u003c/p>\u003cp>A2就是要设想一下未来你可能在什么样的情况，会用这个拆页中的方法来处理问题。\u003c/p>\u003cp>拆书有两种形式：\u003c/p>\u003cp>第一个层面是个人层面的学习法，主要就是运用RIA便签法。\u003cbr>第二个层面是组织层面的拆书法。有一个人做为拆书家，引导一群对某个主题有兴趣的学习者，进行一场现场学习，类似于达到一种培训的效果。\u003cbr>\u003cbr>\u003c/p>\u003cp>而“拆书帮”就是一个运用拆书法来进行学习的组织，这个组织的使命就是帮助更多的学习爱好者成长为拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":14791,"quote":"\u003cp>为了让大家更好地理解什么是拆书法我们就一起来体验一下这个过程。我摘取了一段原文发给大家，请大家花一分钟的时间进行阅读，读完之后可以抬头示意我。\u003c/p>\u003cp>R原文拆页： \u003c/p>\u003cp>原文来自《麦肯锡工作法》 作者：[日]大岛祥誉        \u003c/p>\u003cp>为了在30秒内简洁地向对方说明情况，麦肯锡的优秀经营顾问们经常使用被称为“3个要点”的技巧。他们平时思考的时候就养成了将要点分成3部分的习惯。所以，越是在短时间内，他们所传达的内容越清晰、简洁、接近本质。\u003c/p>\u003cp>反之，如果是持续30秒以上的交流，那么最想传达的内容可能变得不那么明确了。\u003c/p>\u003cp>那么，应该如何总结出3个要点呢？\u003c/p>\u003cp>首先要将想要传达的内容分为以下3个要素：\u003c/p>\u003cp>1.现状的掌握情况。\u003c/p>\u003cp>2.对现状的解释，以及理由。\u003c/p>\u003cp>3.结论，以及解决方法。\u003c/p>\u003cp>最简单的例子就是第一章中提到过的“空、雨、伞”。假设你要劝一个准备出门的人带雨伞，那么过程应该是这样的。\u003c/p>\u003cp>建议对方带雨伞\u003c/p>\u003cp>1.现状的掌握情况。\u003c/p>\u003cp>“xx先生，请等一下!抬头看一看，满天都是乌云。”\u003c/p>\u003cp>2.对现状的解释，以及理由。\u003c/p>\u003cp>“这说明一会儿很有可能突然下雨。可能会被淋湿。”\u003c/p>\u003cp>3.结论，以及解决方法。\u003c/p>\u003cp>“请带上这把雨伞。”\u003c/p>\u003cp>在实际应用中，顺序应该变更为“结论→理由”。特别是在商业领域，一般情况下都应该首先告诉对方结论，然后再告诉理由。\u003c/p>\u003cp>“请带上这把雨伞。抬头看一看，满天都是乌云，这说明一会儿很有可能突然下雨。”\u003c/p>","explains":"\u003cp>时间到。相信大家都已经读完了，我们来一起看一下这份拆页。\u003c/p>\u003cp>这段拆页来自一位日本的作者叫做大岛祥誉的书——《麦肯锡工作法》，这段拆页主要讲了一个在30秒内简洁传达信息的方法，叫做“三个要点”法，这个方法需要具备3个要素：1.现状的掌握情况。2.对现状的解释，以及理由。3.结论，以及解决方法。作者举了一个“建议对方带雨伞”的例子来说明这个方法。最后他还提到“在实际应用中，特别是在商业领域，应该首先告诉对方结论，然后再告诉理由。”\u003c/p>\u003cp>那我们来总结一下就是：\u003c/p>\u003cp>首先，讲出结论，重点是你期待的行动是什么；\u003c/p>\u003cp>然后，描述现状，与结论相关的信息是什么；\u003c/p>\u003cp>最后，解释理由，得出结论的推测是什么。\u003c/p>\u003cp>学习完这段拆页，我们来想一想在什么情况下我们可以使用这种方法呢？是不是在时间紧的时候比较适用啊？或者对方事情多没耐心听你多说的时候，比如向领导汇报工作、在电梯里和领导或者同事交流的时候、向面试官做自我介绍等等。不适合使用的地方呢？比如闲聊的时候？聊天的时候用这种方法很容易把天给聊死。\u003c/p>","interaction":"\u003cp>关于这个方法我就一个经验可以分享。事情是这样的：上个季度我们单位接受了上级单位的安全巡查，查出了很多问题需要整改，我们主任安排我针对安全责任书的问题督促各个部门整改到位，我按照他的要求下发了通知，要求各个部门20号之前交给我，但过程中出现了一些问题，很多部门对目标的理解有差错，所以没有按时完成。当天部门周会的时候，主任让我汇报这件工作的完全情况，我啰啰嗦嗦跟他汇报了一大堆，从头到尾地说了事情起因是怎样的，过程又是怎样的，现在是个什么结果。说到一半，我们主任就说，别说了别说了，你就说现在是个什么情况，下一步要怎么做。我听他这么一说，心里就想他是不是觉得我很烦啊？是不是嫌弃我工作做得不好啊？现在想起来，如果当时我用“三个要点”的技巧来汇报，简洁明了，可能就不会惹领导嫌弃了。\u003c/p>\u003cp>如果下一次我再遇到这种情况，我就可以对照这三个步骤这样说： \u003c/p>\u003cp>首先讲出结论：“责任书的整改完成时间需要推后。”\u003c/p>\u003cp>然后描述现状：“好几个部门还没完成。”\u003c/p>\u003cp>最后解释理由：“他们对安全目标的降级分解有误解，需要重新和他们解释具体做法。”\u003c/p>\u003cp>就这样三句话，简洁明了，是不是比之前那种方式要好很多。\u003c/p>\u003cp>好，关于这个方法我们就学到这里，希望大家可以把这个方法好好运用起来，在需要快速准确传达信息的时候可以给大家提供一个思路。\u003c/p>\u003cp>我的讲解就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1609506133000,"updated_at":1610780603000,"ria":true},{"id":8330,"topic":"30秒3要点表达法","learn_goal":"学习30秒3要点表达法传达信息","remark":"在30秒以内以3个要点清晰简洁地想对方传达信息的方法，避免没有重点的表达丧失难得机会。","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"王哈哈","city":"哈尔滨市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp;&nbsp; 大家好，我是王哈哈，本舵会员长老，如果想加入拆书帮成为一名拆书家,欢迎活动后加我微信好友，携手共同成长的拆书帮了解一下~ \u003cbr>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 在跟随我完成本次拆书学习后，你将学会在30秒内以3个要点清晰简洁地向对方传达信息的方法，避免没有重点的表达丧失难得的机会。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 和大家一起拆解的片段来源于《麦肯锡工作法》，作者大岛祥誉曾就职于世界一流的咨询公司麦肯锡，后独立创业从事培训和咨询服务。书中介绍了麦肯锡精英的39个工作习惯，包含丰富的案例和清晰的说明。它能帮助你选择和培养你需要的好习惯，提升工作和生活的品质，提高解决问题的效率。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 因为今天人数比较少，只有三个人，我们就不分组讨论了，一会儿大家一起交流就好。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":0,"texts":[{"id":11960,"quote":"\u003cp>请大家用2分钟时间阅读一下拆页。\u003c/p>\u003cp>原文来自《麦肯锡工作法》 作者：[日]大岛祥誉&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; P60-61\u003c/p>\u003cp>为了在30秒内简洁地向对方说明情况，麦肯锡的优秀经营顾问们经常使用被称为“3个要点”的技巧。他们平时思考的时候就养成了将要点分成3部分的习惯。所以，越是在短时间内，他们所传达的内容越清晰、简洁、接近本质。\u003c/p>\u003cp>反之，如果是持续30秒以上的交流，那么最想传达的内容可能变得不那么明确了。\u003c/p>\u003cp>那么，应该如何总结出3个要点呢？\u003c/p>\u003cp>首先要将想要传达的内容分为以下3个要素：\u003c/p>\u003cp>1.现状的掌握情况。\u003c/p>\u003cp>2.对现状的解释，以及理由。\u003c/p>\u003cp>3.结论，以及解决方法。\u003c/p>\u003cp>最简单的例子就是第一章中提到过的“空、雨、伞”。假设你要劝一个准备出门的人带雨伞，那么过程应该是这样的。\u003c/p>\u003cp>建议对方带雨伞\u003c/p>\u003cp>1.现状的掌握情况。\u003c/p>\u003cp>“xx先生，请等一下!抬头看一看，满天都是乌云。”\u003c/p>\u003cp>2.对现状的解释，以及理由。\u003c/p>\u003cp>“这说明一会儿很有可能突然下雨。可能会被淋湿。”\u003c/p>\u003cp>3.结论，以及解决方法。\u003c/p>\u003cp>“请带上这把雨伞。”\u003c/p>\u003cp>在实际应用中，顺序应该变更为“结论→理由”。特别是在商业领域，一般情况下都应该首先告诉对方结论，然后再告诉理由。\u003c/p>\u003cp>“请带上这把雨伞。抬头看一看，满天都是乌云，这说明一会儿很有可能突然下雨。”\u003c/p>","explains":"\u003cp>\u003cstrong>主题：\u003c/strong>\u003cstrong>30\u003c/strong>\u003cstrong>秒\u003c/strong>\u003cstrong>3\u003c/strong>\u003cstrong>要点表达法\u003c/strong>\u003c/p>\u003cp>&nbsp; 好，下面我讲讲我和这篇拆页的缘分。\u003c/p>\u003cp>上周我的主管领导问我：小王，之前让你跑的合同怎么样了？\u003c/p>\u003cp>我和领导汇报：领导啊，根据对方的要求，我们需要先维护网上系统，再更新企业法人信息……\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 领导直接打断我问：停停停，别和我说这些有的没的，那我们现在该做什么了？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我心里咯噔了一下，心想一定是被领导嫌弃啰嗦了。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 九成以上的人习惯按照事情的时间顺序传递信息，但是这样容易变成长篇大论，领导可没时间听这些不利于决策的过程，甚至还有可能会被认为办事水平不行丧失升职加薪的机会。那该怎么办呢？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 今天的拆页片段就提供了一种在30秒内以3个要点清晰简洁地向对方传达信息、引导行动的方法，我叫它30秒3要点表达法。\u003c/p>\u003cp>\u003cstrong>首先，讲出结论\u003c/strong>，重点是你期待的\u003cstrong>行动\u003c/strong>是什么；\u003c/p>\u003cp>\u003cstrong>然后，描述现状\u003c/strong>，与结论相关的信息是什么；\u003c/p>\u003cp>\u003cstrong>最后，解释理由\u003c/strong>，得出结论的推测是什么。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 学会用这个方法，相信我的汇报就不会再被领导嫌弃了：\u003c/p>\u003cp>\u003cstrong>首先讲出结论\u003c/strong>：“我们需要去政府部门申请新增资质备案。”\u003c/p>\u003cp>\u003cstrong>然后描述现状\u003c/strong>：“这项业务是第一次开展。”\u003c/p>\u003cp>\u003cstrong>最后解释理由\u003c/strong>：“只有在政府部门备案成功才能进行其他工作，新增资质备案需要提供的材料有一二三四五-五样。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 在对方没时间或者没耐心的时候特别适合用30秒3要点表达法，比如向领导汇报工作、电梯对话、向面试官做自我介绍等等。人与人之间的交流时间再短，也还是有个30秒的机会在，重要的是在表述之前需要花时间准备，在表述中传达真正重要的内容。要注意在闲聊的时候别用这样的表达，容易30秒把天聊死。\u003c/p>","interaction":"\u003cp>下面请大家回想一个近期你或者其他人在交谈中传达信息的情景，尤其是那种有个人说说说但是其他人根本不知道他到底要讲什么的情况，或者是我们想表达些什么但是其他人不了解我们要表达的内容。在小组内分享。分享时要讲出时间、地点、交谈的对象、表述的大致内容。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 讨论时间为4分钟，组内每人1分钟发言时间，自己计时。4分钟后我们选出一位伙伴用1分钟时间分享给大家。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 学习者W向大家分享他刚工作时候的经历：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我刚工作的时候在人力资源部，直属上司让我在单位向品质部的领导沟通改预算。改预算的原因很多，人员超编、奖金数过高了等等超过了拨给那个部门的金额。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我和另一部门领导沟通的时候，和他说：岳处你好，你把人改一下，或者明年不要晋升这么多人，或者做一下薪酬调整这样年底不会超……\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 说了很多之后还没有说完，对方还是没听明白我要表达什么，语气很不耐烦的问我：你到底要说啥？！\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我说：你们部门的预算超标了，需要你改一下预算。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 感受：我想我要是用这种方法，我可以先用这种方法先说结论-需要改预算，再说几条建议这样会好很多。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 谢谢这位伙伴的分享。你想让对方做什么事，但是对方一直不知道你要表达什么，而且对方还没有耐心听下去，你的时间又很有限，你就可以用这种方法调整一下表达方式。\u003c/p>\u003cp>接下来我们思考一下30秒3要点表达法未来可以怎么应用。在一周内的某一天，最好是明天，设想一个符合这种方法的表达机会，比如向领导汇报工作、向他人布置任务、书友之间推荐书籍，或者向客户介绍自家的产品等等。\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 给大家\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>分钟的时间\u003c/strong>，将自己表述设计写在拆页背面的框架内。写好之后请示意我。\u003c/p>\u003cp>&nbsp;&nbsp; 1分钟过的很快，我看到大家都写了很多，如果没写完也不要紧，活动结束后我会联络你收集便签的。本次的拆书就到这里，希望你能将今天拆书学到的内容应用到未来的生活和工作中，谢谢大家！\u003c/p>\u003cp>收集学习者Y的便签\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 目标和期限：在未来一周内用30秒3要点表达法引导病人讲述病史并且把病情结论讲给病人听。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 在询问病人病史时，经常听到：“十年前……”、“当年……”、“之前吧……”一类的话，10分钟过去一点和疾病有关的内容都没有问到。为了更快更好的了解病人的病史，为病人服务，我打算下周尝试用“30秒3要点法”引导病人说出病史并且把病情结论讲给病人听。\u003c/p>\u003cp>引导病人做法：\u003c/p>\u003cp>\u003cstrong>首先引导病人讲出结论\u003c/strong>：你来医院最不舒服的症状是什么？是咳嗽、额头或身体哪里发热？身上哪里很疼？还是其他哪里难受？\u003c/p>\u003cp>\u003cstrong>然后引导病人描述现状\u003c/strong>：你的这个症状（复述症状）持续多长时间了？症状有加重吗？\u003c/p>\u003cp>\u003cstrong>最后和病人一起找到解释理由\u003c/strong>：你感觉你做的哪件事对这个症状有影响？（根据症状具体询问食物、行动或是情绪等等）中间有用药缓解吗？曾经有类似的症状或病情吗？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 在引导病人说出他自身情况之后，再用“30秒3要点法”把病情讲给患者，以有咳嗽症状的病人为例。\u003c/p>\u003cp>\u003cstrong>首先讲出结论\u003c/strong>：我了解了你的病情，你的症状很轻/严重，平时注意休息/用XX药/进步一检查/住院。\u003c/p>\u003cp>\u003cstrong>然后描述现状\u003c/strong>：你现在每天XX时间段咳嗽，同时有XX状况的痰，之前的检查结果是XXX……(复述病人说出的症状重点及检查结果)\u003c/p>\u003cp>\u003cstrong>最后解释理由\u003c/strong>：我们的主要目的是缓解症状尽快康复，以现在的情况来说休息/用XX药/进步一检查/住院是最好的选择。轻症不用解释太多，重症需要解释到病人理解并作出下一步决定。\u003c/p>\u003cp>收集学习者F的便签：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我感觉这种方法很适合约闺蜜出来逛街，其实我们已经够熟了，关系也非常好，不用在前边跟她扯些有的没的，直接跟她说就行。当然如果不太熟悉的可能就得铺垫一下。\u003c/p>\u003cp>目标：约闺蜜逛街\u003c/p>\u003cp>期限：明天约下个周六\u003c/p>\u003cp>做法：\u003c/p>\u003cp>\u003cstrong>首先讲出结论\u003c/strong>：下个周六我们一起去逛街吧。\u003c/p>\u003cp>\u003cstrong>然后描述现状\u003c/strong>：这东北可怕的夏天这么冷。\u003c/p>\u003cp>\u003cstrong>最后解释理由\u003c/strong>：我们可以逛街看看有没有想买的衣服“御寒”。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1562418492000,"updated_at":1562418532000,"ria":true},{"id":7981,"topic":"把握问题本质","learn_goal":"学习者在工作中遇到问题时会运用批判思维进行“从零开始”的思考","remark":"","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"Lance龙","city":""},"club":{"name":"上海羊角村分舵","city":"上海市"},"prologue":"\u003cp>\u003cstrong>学习目标：让学习者在工作中遇到问题时会运用批判思维先进行“从零开始”的思考，\u003c/strong>\u003c/p>\u003cp>\u003cstrong>从而明确真正的问题\u003c/strong>\u003c/p>\u003cp>（先分组，最好2人一组）\u003c/p>\u003cp>\u003cstrong>——书籍介绍：预估2-3分钟——\u003c/strong>\u003c/p>\u003cp>我估计大家都知道麦肯锡公司，是的，麦肯锡公司是现在世界上最顶尖的经营咨询公司。那么既然是咨询公司，其最重要的业务就是要帮助客户来解决问题。\u003c/p>\u003cp>\u003cstrong>（FAB介绍法之F：特征：核心是“书”，用于满足好奇心）\u003c/strong>\u003c/p>\u003cp>而这本书正是叙述了从“麦肯锡”的主业——解决问题的过程中提炼出来了39个非常重要的“习惯”。正是这些简单的习惯，构成了一条连接问题和答案的最短路程。\u003c/p>\u003cp>掌握了这39个重要的习惯，就意味着掌握了解开问题的金钥匙。\u003c/p>\u003cp>\u003cstrong>（FAB介绍法之A：优势，“比较”，用于建立安全感）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>相比于\u003c/strong>现在市面上有其它很多打着“麦肯锡”旗号的书，比如说，有写作方面的，有说逻辑思维的，有说用人标准的。这本书直击“麦肯锡”的核心业务，将解决问题的方法直接地展现给了我们。&nbsp;\u003c/p>\u003cp>\u003cstrong>（FAB介绍法之B：利益，强调“学习者”，引发兴趣，获得价值）\u003c/strong>\u003c/p>\u003cp>在座的各位想必都做着一份工作，无论是九九六的去公司上班，合伙开个公司每天疲于各种应酬，或者在家里全职照顾孩子，我们之所以有着这样一份“工作”，其实正是因为我们拥有一定的“解决问题”的能力。而这本书正是可以提高我们这“解决问题”的能力。\u003c/p>\u003cp>当然，要想更好地解决问题，我们必须先明确我们真正要解决的问题是什么。接下来先让我们一起看下片段。\u003c/p>","ratings_count":1,"texts":[{"id":11555,"quote":"\u003cp>当我们遇到问题的时候，要保持从零开始的思考，回到原点。\u003c/p>\u003cp>“本公司的XX事业连续两年出现赤字，找不到挽回的方法。问题究竟出在那里？怎么解决才好？请帮帮我们吧。”\u003c/p>\u003cp>麦肯锡的经营顾问们，经常会从客户那里收到这样的请求。\u003c/p>\u003cp>如果按照一般的问题解决流程，首先要找出这项事业的问题，对其进行分析和了解，然后思考解决的方法。\u003c/p>\u003cp>但是，“思考如何将XX事业变成黑字”的方法，并不是最好的解决方法。\u003c/p>\u003cp>为什么？因为这种方法并不是“从零开始”。这只是根据顾客提出的问题给出相应的意见，并不是从“原点”出发的观点。\u003c/p>\u003cp>“从零开始”的思考方式，要考虑什么才是真正的问题，这项事业今后还有没有继续的必要？从这样的角度来进行思考。 \u003c/p>\u003cp>比如说，不管这项事业是多么著名的品牌，在历史和传承上有过怎样的辉煌，但今后如果没有什么发展的话，彻底放弃或许才是最好的选择。\u003c/p>\u003cp>那么真正的问题就不是解决这项事业的赤字，而是在放弃了这项事业以后，如何提高剩余事业的利润。\u003c/p>\u003cp>……\u003c/p>\u003cp>为了使思考更加深入，就必须采取批判的思考方法。\u003c/p>\u003cp>为什么？\u003c/p>\u003cp>真的吗？\u003c/p>\u003cp>真正的问题是什么？\u003c/p>\u003cp>有没有更好的解决办法？\u003c/p>\u003cp>通过这种批判的思考方式和不断地对自我提问，可以使你一步一步地逼近问题的本质。\u003c/p>\u003cp>通过对自己提出这些批判性的问题，可以使思考更加深入，提高视点（成为俯瞰视点），看问题更加全面。批判的思考可以看清问题的本质。\u003c/p>\u003cp>如果能够养成批判思考的习惯，那么就可以自然而然地进行“从零开始”的思考，明确地判断出哪些事情应该做，哪些事情没必要做。\u003c/p>","explains":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>我看大家基本上都已经读完了，如果还没全读完也没关系，可以先听一下我的讲解。\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>\u003cbr>\u003c/p>\u003cp>当我们碰到问题的时候，为了解决它，我们会先将问题提出来然后进行解答。\u003c/p>\u003cp>但是，有时候我们所提出来的这个问题本身却会把我们的思维给限制住。\u003c/p>\u003cp>为了突破它，就需要我们能够“从零开始”进行思考。\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>一旦我们养成“从零思考”的习惯，我们就可以跳出问题本身，站在更高的视角来进行审视，从而看清问题的本质。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>\u003c/p>\u003cp>既然我们现在清楚了“从零开始”的重要性，那么具体来说应该怎么做呢？我们需要怎样做才能养成“从零开始”的思考方式呢？简单来说可以用下面3步来进行。\u003c/p>\u003cp>1.&nbsp;\u003cstrong>跳出当下的问题\u003c/strong>\u003c/p>\u003cp>2.&nbsp;\u003cstrong>从多视角来对于当下所面临的情况提出问题，并进行解答，\u003c/strong>\u003c/p>\u003cp>3.&nbsp;\u003cstrong>重复第二步，直到出现真正的问题。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【举例】\u003c/strong>\u003c/p>\u003cp>我举一个我身边的例子。\u003c/p>\u003cp>我们部门是负责售前的技术支持的，一旦项目合同签订，我们将会把其中采购件的技术细节发给采购部。最近有个海外项目，所有产品已经发货到了海外，但是发现有部分外购件的接口尺寸不一致，于是销售找到了支持这个项目的技术Meryl。\u003c/p>\u003cp>Meryl心里有气，我下单又没有犯错，发货了怎么还来找我呢？不过觉得为公司考虑，还是先努力把事情给解决掉吧！她脑中当时的问题就是“我该如何解决这个技术问题“。于是，她独自和供应商联系，寻找相应的解决方案，要求提供另外的零部件……但是她越努力解决，越是碰到更多的麻烦事儿，比如：供应商推说不是他们的责任，反馈也不及时，额外的采购件的货期也不满足要求……她急得头很大，于是找到了我。\u003c/p>\u003cp>我尝试着用“从零开始”的方法\u003cstrong>跳出她原本的问题\u003c/strong>，\u003cstrong>问了她下面几个问题：\u003c/strong>\u003c/p>\u003cp>Q：为什么发货的产品接口尺寸会不一致呢？\u003c/p>\u003cp>A：我下单的时候都已经备注了尺寸的，但是采购下单那边不体现这个尺寸，而质检也没有检查这块。&nbsp;\u003c/p>\u003cp>\u003cstrong>接着我不断重复问她问题并让她回答，直到得出出现真正的问题。\u003c/strong>\u003c/p>\u003cp>Q：为什么采购下单和你给的会不一致呢？\u003c/p>\u003cp>A：因为采购下单只按照程序走，没管我的备注，而SAP系统上没办法体现这个尺寸。\u003c/p>\u003cp>Q：那现在要解决这个问题，会需要哪些公司内部部门呢？\u003c/p>\u003cp>A：哦，还需要售后部、采购部、质检部的配合。\u003c/p>\u003cp>\u003cstrong>Q：所以，真正的问题是？\u003c/strong>\u003c/p>\u003cp>A：如何和售后部、采购部、质检部一起来解决目前的问题。\u003c/p>\u003cp>于是在回答这一连串问题中，她自己就找到了真正的问题所在。\u003c/p>\u003cp>\u003cstrong>【预防异议1-实践】\u003c/strong>\u003c/p>\u003cp>可能有伙伴会问，从多视角来对当下提问题并给与解答，我不知道怎么提该怎么办呢？\u003c/p>\u003cp>确实，有时候提问会比较难。一般而言可以用“为什么”来探究这个情况发生的原因，用“真的吗？”来确认答案的正确性。最后通过“真正的问题会是什么？”来作为我们的问答思路。\u003c/p>\u003cp>当然要很好的掌握这个技巧，需要平日的不断练习。\u003c/p>\u003cp>\u003cstrong>【预防异议2-适用边界】\u003c/strong>\u003c/p>\u003cp>另外可能还有小伙伴在想我们在任何情况下是不是都必须要进行这种“从零开始”的思考呢？\u003c/p>\u003cp>我的经验是，在工作中，这种“从零开始”的思考方式尤其适用，可以给你带来更多的视角来找出问题的本质。\u003c/p>\u003cp>而在生活中呢，一般情况下可能没必要进行那么复杂的思考。可如果你碰到很棘手的问题的时候，比如说很长时间不管自己怎么做都和女朋友处得不好，可能我们就要用“从零开始”的思考方式从“如何和女朋友相处好”转变为“这个女生是不是适合自己”了。\u003c/p>","interaction":"\u003cp>\u003cstrong>&lt;分步骤催化1&gt;\u003c/strong>\u003c/p>\u003cp>大家想一下最近工作上或者生活上有没有什么困扰自己的事情？\u003c/p>\u003cp>部门领导有没有给你布置了个任务，但是你却不知道如何入手的？\u003c/p>\u003cp>可能是要求做个PPT，你踌躇着怎样才能把这个PPT做好？\u003c/p>\u003cp>可能是一个公司内部汇报，你想着如何写这个汇报可以让领导满意？\u003c/p>\u003cp>请大家把这个想到的问题先写下来，我会请位小伙伴来分享一下。\u003c/p>\u003cp>\u003cstrong>【学员分享1】\u003c/strong>\u003c/p>\u003cp>我有2个困扰自己的问题：\u003c/p>\u003cp>1.&nbsp;如何找到好的素材来写演讲的稿子？\u003c/p>\u003cp>2.&nbsp;如何改变我的声音？\u003c/p>\u003cp>有很多人给我反馈我演讲的声音太平了，虽然我已经很努力地去训练自己的声音了。\u003c/p>\u003cp>\u003cstrong>&lt;分步催化2&gt;\u003c/strong>\u003c/p>\u003cp>谢谢Vicky的分享。\u003c/p>\u003cp>那么我们今天学习了用3步法进行“从零开始”的思考方式，我们用这个方法来探究下你所写下的这个问题是不是真正的问题？真正的问题到底是什么？\u003c/p>\u003cp>比如说，你原本想着“如何才能做好PPT？”\u003c/p>\u003cp>我们可以试着跳出这个问题，先问下自己“为什么要做这个ppt呢？”\u003c/p>\u003cp>“哦，是为了在下一次会议的时候能够说服领导们同意研发 我提出的新产品。”\u003c/p>\u003cp>那么，真正的问题，是不是应该是“如何在下次开会的时候说服领导们同意我的方案”了呢？\u003c/p>\u003cp>请尝试用这样的思路思考下，并在小组中讨论，来找出我们真正的问题到底是什么。\u003c/p>\u003cp>\u003cstrong>【学员分享2】\u003c/strong>\u003c/p>\u003cp>我原本的问题是：怎样写些东西\u003c/p>\u003cp>因为我想要将自己的一些人生经历分享给他人，让他人少走弯路。另外，我觉得我的工作上有碰到短板。\u003c/p>\u003cp>Q：为什么要写作呢？\u003c/p>\u003cp>A：因为想要锻炼自己的表达能力，逻辑总结能力。\u003c/p>\u003cp>Q：为什么要锻炼自己的表达能力呢？\u003c/p>\u003cp>A：为了补足自己的短板，想分享自己的人生经历，想要作为一个副业。\u003c/p>\u003cp>Q：所以真正的问题是？\u003c/p>\u003cp>A：真正的问题是“如何在工作上补短”，前面说的写作只是其中的一个突破点。\u003c/p>\u003cp>非常感谢小伙伴的分享，那么我们今天的活动就到此为止。谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1558866324000,"updated_at":1558866376000,"ria":true},{"id":7895,"topic":"在工作中当别人的行为不能达到你的期望时，你应该怎么做 ？","learn_goal":"学会“训斥的三个原则” 避免当面，保持情绪平和，引导启发 ","remark":"工作的本质是解决问题，每个人不同的思维和行为方式决定了我们解决问题的能力。 \r\n《麦肯锡工作法》正是将作者在麦肯锡工作期间总结出来的思维、行为习惯分享给我们，帮助我们在工作中变得更高效。 \r\n你在工作中遇到过别人的行为让你失望，与你预期不符的情况吗？这种时候你的应对方式是什么呢？更好的应对方式又是什么呢？ \r\n如果你想知道，可以来了解本期的分享主题——“训斥的三个原则”，将帮助我们更好的处理相关事件，从而达到自己的最终目标。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"玄清琳","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"方法","ratings_count":0,"texts":[],"created_at":1557886338000,"updated_at":1557886338000},{"id":7386,"topic":"用30秒时间提出3个要点","learn_goal":"用30秒时间提出3个要点","remark":"30秒的电梯游说，带来巨额资助！你的30秒又能表达多少？\r\n拆书家吕吕将和大家分享如何用30秒时间提出3个要点\r\n","level":"TF1-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"吕吕","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"【⾃自我介绍】 标签⼀一 LV ，⼤大家对LV这个品牌都很熟悉哈，我呢只为⾃自⼰己代⾔言，lv吕吕我来了了。 标签⼆二 锻炼，这个嘛⽬目的很单纯，增强体质，光吃不不胖。 标签三 拆书家，⽬目前是⼀一枚鲜⾁肉，希望早⽇日成为腊⾁肉。 【介绍拆书书籍】今天我给⼤大家分享的书籍是《⻨麦肯锡⼯工作法》，副标题《⻨麦肯锡精英的39个⼯工 作习惯》。这本书的作者⼤大岛祥誉，他是世界顶尖顾问公司⻨麦肯锡的前咨询顾问，这本书就是他 的现身说法，以“品质*效率”为主题，为我们介绍了了⻨麦肯锡精英们彻底实践的⼯工作法，以及最重要 的39个习惯。\r\n【分组】依据现场情况阅读拆⻚页前分组","ratings_count":0,"texts":[{"id":10845,"quote":"\u003cp>【主题】⽤用30秒时间提出3个要点 【图书】《⻨麦肯锡⼯工作法》 【章节】习惯13 【⻚页码】59⻚页&nbsp; &nbsp; &nbsp; &nbsp;当你⽤用“可以占⽤用您1分钟的时间吗”成功地争取到上司的时间之后，接下来就必须简洁地完成 “报、联、商”。&nbsp; &nbsp; &nbsp; &nbsp; 据说在美国的硅⾕谷， 有⼀一位年年轻的经营者在电梯前等待⼀一位著名的投资⼈人，趁着和他共同搭 乘电梯的30秒时间介绍⾃自⼰己的事业，从⽽而成功地获得了了巨额的资⾦金金援助，这就是著名的“电梯游 说”。&nbsp; &nbsp; &nbsp; &nbsp; 先不不管这个成功的创业故事是否真实，但这个⽅方法确实是出⾃自⻨麦肯锡的“电梯测试”。所谓“电 梯测试”，就是在搭乘电梯的30秒内，美地说明现存的问题以及解决⽅方案。 也就是说，在⻨麦肯锡⼯工作的员⼯工，⽤用“可以占⽤用您1分钟的时吗？”得到与上司交谈的许可之后，要 ⽤用30秒的时间说明重点，然后给上司30秒的时间做出判断。 如何总结出“3个”要点? 不不管是说明还是“报、联、商”，⾸首先都要传达的内容分为以下3个要素。 1.现状的掌握情况。 2.对现状的解释，以及理理由。 3.结论，以及解决⽅方法。&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;最简单的例例⼦子就是第-章中提到过的“空、⾬雨、伞”。要劝⼀一个准备出⻔门的⼈人带⾬雨伞，那么过程 应该是这样的。 例例1.建议对⽅方带⾬雨伞 1.现状的掌握情况。 “xx先⽣生，请等-下!抬头看⼀一看，满天都是乌云。” 2. 对现状的解释，以及理理由。 “这说明⼀一会⼉儿很有可能突然下⾬雨。可能会被淋淋湿。” 3. 结论，以及解决⽅方法。 “请带上这把⾬雨伞。”\u003c/p>\u003cp>在实际应⽤用中，顺序应该变更更为“结论⼀一理理由”。特别是在商业领域，-般情况下都应该⾸首先告 诉对⽅方结论，然后再告诉理理由。\u003cbr>\u003c/p>","explains":"\u003cp>I【复述】 Why-⽆无论是⽣生活还是职场，很多场合下我们能⽤用⼏几句句话说清楚的事情要铺垫要委婉要含蓄反⽽而事 倍功半，不不能⾼高效的表达我们的观点陈述我们的理理由。⽽而今天要分享的⽤用30秒时间提出3个要点就 刚好能够解决⼯工作⽣生活中的“啰嗦/费劲” Wht-⾼高效表达的技能 How-30秒时间提出3个要点? 不不管是说明还是“报、联、商”，⾸首先都要传达的内容分为以下3个要素。 1.现状的掌握情况。 2.对现状的解释，以及理理由。 3.结论，以及解决⽅方法。&nbsp;\u003c/p>","interaction":"\u003cp>A1 【故事】&nbsp; &nbsp; &nbsp; &nbsp;上周五复试⼀一个打算⼊入本部⻔门的⼩小姑娘，领导让我和另外⼀一个同事过去⼀一起把关聊⼀一聊，这 个姑娘整体形象⽓气质都⽐比较好，167⾼高挑个⼦子，穿着很正式，⼤大眼⻓长发，笑容也很甜美，跟⼈人交流 有眼神互动，有礼貌并且有过相关类似的⼯工作经验，但是呢就是时不不时喜欢皱眉头，沟通测试环 节⽐比较被动，不不是很愿意主动和别⼈人交流的感觉。就这样的情况我们⾯面试完了了之后，我们电话远 程向领导汇报⾯面试情况。 我说“整体感觉还挺好的喜欢笑给⼈人亲切感，并且还有相关⼯工作经验，但是呢好像在测试阶段不不喜 欢主动跟别⼈人沟通，就咱们⽬目前的状态可能和我们的要求有⼀一些距离·····” 领导说“额，说了了这么多，那你们的建议是留留不不留留？” 我说“留留的⻛风险是万⼀一在客户那⾥里里也不不主动交流沟通，会给客户感觉我们很⾼高冷不不热情；但她却是 整体素质还挺不不错的呢” 领导“我正在开⻋车去赶往客户那⾥里里，怎么那么费劲，你就说客观事实，告诉我你想法就好了了”领导炸 了了我也很想炸，领导⽣生⽓气挂断电话。 【反思】 陈述现状及对现状的解释混合⼀一起反复穿插说，导致领导短时间get不不到客观事实和我个⼈人⻅见解， 加之结论建议不不明确。 A2 【⽬目标】 1⽉月18⽇日节前最后⼀一次⾯面试结果汇报 【⾏行行动计划】 时间；1⽉月18⽇日节前最后⼀一次⾯面 对象：打算⼊入职本部⻔门的实习⽣生 计划：⾯面试完毕后第⼀一时间使⽤用30秒时间提出3个要点 参考⾏行行动话术 1.现状的掌握情况。 姑娘的身⾼高XX外形XX礼貌XX亲切感XX；沟通测试开场断档30秒,我征求本 ⼈人许可情况下录制了了⼩小视频供您参考。 2.对现状的解释，以及理理由。 由正式得体的穿着可以看出她态度认真，30秒的断档可能是准备时 间⽐比较短，会议室后⾯面有⼈人催⽤用，给她留留的准备时间不不充分。\u003c/p>\u003cp>2\u003c/p>\u003cp>2019年年1⽉月9⽇日 星期三 3.结论，以及解决⽅方法。 过往的⼯工作经历加得体的职场形象配上这认真的⾯面试态度，我建议录⽤用， 同步您也可以参考同事欣欣的看法。&nbsp; &nbsp;A1学习者分享～*刚刚我这边呢也是抛砖引⽟玉，接下来3-5分钟，我们⼩小组内部分享⼀一下关于“近期 ⼯工作场合中表达三个关键点总是多少，是否⾼高效呀”～有没有哪位伙伴想跟⼤大家分享⾃自⼰己过往的经 历呢（限⼀一个⼈人）表示肯定感谢\u003c/p>\u003cp>A1学习者分享-孩⼦子找英语辅导班，机构打电话来我们这⾥里里可以吧，我们需求是离家近，⽽而且不不想 周末上课，其实我们也要考虑性价⽐比⾼高不不⾼高，这样沟通效率⽐比较低，⼀一来⼀一回始终没有结论；第 ⼆二位分享的伙伴，最近在找房⼦子，跟房⼦子中介沟通中介总能推荐说服你的理理由⾮非常浪费精⼒力力，但 是呢如果想最好的沟通，抛出⾃自⼰己的需求点。\u003c/p>\u003cp>A2学习者分享～*就上周失败的经验，我通过“报、联、商”⽅方法在下周⾯面试汇报制定了了⼀一次计划， 接下来我们每个⼈人拿⼀一个便便签纸⼀一分钟时间写⼀一下我们各⾃自的应⽤用或⾏行行动步骤吧。刚刚看⼤大家写 的很投⼊入很认真，有没有哪位伙伴想分享⼀一下⾃自⼰己接下来的⾏行行动计划呢（限⼀一个⼈人）肯定表示感 谢\u003c/p>\u003cp>【总结】 “报、联、商”实现三步⾛走30秒⾼高效表达三个关键点。提升⾃自⼰己与⼈人沟通的能⼒力力，这样的学习与成⻓长 让我很受益，希望今天的分享也能让各位受益，谢谢⼤大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1552447238000,"updated_at":1552447238000,"ria":true},{"id":7360,"topic":"增强沟通的效率","learn_goal":"解决与上司、同事、家人沟通中遗漏重要信息的难题，提高沟通效率","remark":"","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"刘余庆","city":"郑州"},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"\u003cp>【自我介绍】：&nbsp;\u003c/p>\u003cp>我是刘余庆，微信名是善良的老刘。很高兴今天能和大家聚在一起进行学习分享,我的分享大概需要18分钟。首先我先用三个标签来介绍自己：1、办公男，每天早九晚五的工作，简单而充实。2、长跑男，一年前开始长跑，截止现在累计跑步175次，1300公里。3、终身学习者，只有自我学习才能取得进步，拆书能帮助我在学习的道路上越走越快。相信有郑州轩辕分舵小伙伴的陪伴，未来我会在学习道路上越走越远！ &nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>【分组】：\u003c/p>\u003cp>现场大家分为2人一组，共计分为2组，谢谢大家（视情况可分为两组或每组3人）&nbsp;\u003c/p>\u003cp>【学习目标】：\u003c/p>\u003cp>通过学习今天的分享内容后，学习者能够运用“信息确认三步法”的三个步骤，辨别出对方交代任务时话语中的真实含义。&nbsp;&nbsp;\u003c/p>\u003cp>【图书介绍】：\u003c/p>\u003cp>[F]:今天我们的拆页来自《麦肯锡工作法》这本书。作者是日本大岛祥誉。大名鼎鼎的麦肯锡咨询公司我们都听说过，它是世界顶尖咨询公司。而麦肯锡能够取得成功，离不开它独特的工作方法。作者曾经在麦肯锡工作多年，将麦肯锡独特工作方法总结为39个工作习惯。\u003c/p>\u003cp>[A]:整本书，页数不多，行文生动，浅显易懂。虽然薄薄的一本书，但是，却将麦肯锡这个顶尖的咨询公司的优秀工作精髓总结的淋漓尽致，并且可操作性很强。\u003c/p>\u003cp>[B]: 如果你对自己的工作效率不太满意，如果你渴望象那些职场精英一样享受工作，积极生活，那么这本书和他的三十九个习惯会帮助你工作更高效，轻松应对职场。\u003c/p>\u003cp>今天我们拆页学习的这个技巧，可以帮助我们解决与上司、同事、家人沟通中遗漏重要信息的难题，提高沟通效率。\u003c/p>","ratings_count":1,"texts":[{"id":10812,"quote":"\u003cp>【原文片段】\u003c/p>\u003cp>习惯17.工作过程中与上司进行确认\u003c/p>\u003cp>身为部下的你，在接到上司安排的工作时，必须在规定的时间内，保质保量地完成任务。\u003c/p>\u003cp>因此，你必须和上司确认以下三点\u003c/p>\u003cp>1.这份工作的期限。\u003c/p>\u003cp>2．工作的意图和方向性。\u003c/p>\u003cp>3．要求的品质。\u003c/p>\u003cp>很多人都容易忘记确认“1”的期限。\u003c/p>\u003cp>他们以为只要上司记得工作期限就够了。但由于上司十分繁忙，所以他们会更多地把时间都用在说明工作内容上。如果你认为这是“没有时间限制，只要空闲时完成的工作”，那就大结特错了\u003c/p>\u003cp>等过几天上司想起来，问你“那件事怎么样了”，结果你根本没有做，上司肯定会物然大怒吧。因为他的小组没有取得成果，肯定让他也感到十分苦恼。对于这种部下的评价，怎么可能好呢？&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>","explains":"\u003cp>【what】\u003c/p>\u003cp>人与人之间主要靠语言去进行沟通交流。今天我们学习一种沟通技巧，它能帮助你甄别、确定信息是否完整，明确对方的真实需求是什么，有效避免信息被遗漏，达到高效沟通的目的。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>工作、生活中每天我们都会接收很多来自外部的信息。而接听对方信息过程中，无遗漏的了解对方语言传达的真实信息，探寻对方真实想法，十分重要。通过今天的方法，能有效明晰对方真实想法、要求，为你们之间沟通交流打下良好的基础。\u003c/p>\u003cp>【不这么做的坏处】\u003c/p>\u003cp>在沟通交流过程中，如果你只是被动接收信息，不探寻把握对方真实需求，难免会造成重要信息的遗漏。影响人与人之间合同协作，给你工作、生活造成困扰。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>当对方已经把沟通中任务的时间、要达到目的、标准说的很清晰了，就没有必要再用这个技巧了。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>那么我们具体应该怎么避免重要信息被遗漏，这需要一定方法，我称为“信息确认三步法”，具体步骤如下：\u003c/p>\u003cp>第一步，确定完成的最后时间？比如：需要我什么时候完成？\u003c/p>\u003cp>第二步，确定意图?比如：需要达到什么目的？\u003c/p>\u003cp>第三步，确定完成标准?比如，需要做的什么程度？需要达到什么效果？\u003c/p>\u003cp>【举例子】\u003c/p>\u003cp>我举个我刚工作时候的例子吧，有次上司着急打电话，交代一项工作，说上级要来调研，你写一个发言稿，开会时候要用。我着急写完，上司看了我写的稿子，说这次上级来是为了解决我们工作中碰到的实际问题！你这写的都是一片祥和，没有任何问题！你这要重新写！\u003c/p>\u003cp>从刚才的经历，我们可以看出来，我的工作方向完全不是领导想要的，如果我在开展工作之前，跟领导沟通一下工作的思路就不会出现这样吃力不讨好的结果。\u003c/p>\u003cp>如果按照今天学到“信息确认的三步法”问题，那我们就需要跟上司这样的沟通：\u003c/p>\u003cp>1.领导，发言稿什么时间完成，时间有啥特殊要求？（确定完成时间期限）\u003c/p>\u003cp>&nbsp;2.以纸质或口头的形式，向领导汇报发言稿内容提纲。（确定意图）\u003c/p>\u003cp>3.可以跟领导确认，这个发言稿大概需要多长分钟？上级领导级别，需要打印多少纸质档案（完成标准）。\u003c/p>","interaction":"\u003cp>【显现提问】\u003c/p>\u003cp>以上是我的亲身经历，我想小伙伴一定也有类似的经历，各位小伙伴注意了，请回顾过去工作、生活中与上司、同事、家人因为对同一问题理解不同，造成你辛苦完成的任务不是对方想要的情景。再回忆一下，你认为造成这种情况发生的具体原因是什么？是时间期限？达到目的？完成标准？等等原因。那么，你再想想是对方没有说清楚，还是你没有问清楚？用手头的便签先把这个情景写下来，然后在小组内分享一下，每位小伙伴都要分享，给大家5分钟时间，一会我要请小伙伴来进行分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>杨芳：去年8月份，我参加英语流利说一个英语演讲，我问主办发需要准备多长时间？主办方告诉我10分钟以内都可以。当时我也没有具体详细问，就准备了8分钟内容。等到上台演讲的时候，主持人在我演讲5分钟的时候就提醒我到时间了，造成我十分的尴尬。我未与主办方就演讲时间细节进行互相确认，造成现场十分尴尬。\u003c/p>\u003cp>谢谢这位小伙伴的分享。\u003c/p>\u003cp>【A1+】学习者案例记录\u003c/p>\u003cp>在刚才大家所想到的情景中，可以想想当你接受到外界信息的时候，你利用今天我们学到的“信息确认三步法”，来确认，如果时光倒退，你会怎么做呢？ \u003c/p>\u003cp>学习者杨芳：第一，问具体演讲时间需要几分钟（确定时间）?\u003c/p>\u003cp>第二，要问我们演讲的受众是谁？观众都是那些？（确定目的）\u003c/p>\u003cp>第三，有没有演讲的特定的格式？主题要求？范文？字数是否有要求（确定标准）\u003c/p>\u003cp>学习者天后：\u003c/p>\u003cp>老公让我买装修用水龙头，我给忘记了，错过了双12的活动。如果回到那时候\u003c/p>\u003cp>第一，和老公确定买水龙头用的最后时间（确定时间）\u003c/p>\u003cp>第二，确定是装修新房子用？还是父母家坏了需要更换（确定目的）\u003c/p>\u003cp>第三，与老公确定水龙头是需要纯铜材质还是普通塑料的？（确定标准）\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>最后我总结一下今天的内容，我们学习了“信息确认三步法”，从时间、目的、标准去探寻对方真实需求，避免重要信息遗漏。\u003c/p>\u003cp>希望今天的分享，对大家日后交流沟通中能起到帮助，使沟通更高效。今天的分享就到这，感谢大家的积极参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1552207015000,"updated_at":1552207410000,"ria":true},{"id":6402,"topic":"如何让会议更高效","learn_goal":"学习者能通过设定会议目的，确认会议状态等方式，让会议更高效","remark":"","level":"TF1-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"曹志文","city":"厦门"},"club":{"name":"厦门鹭岛抚琴分舵","city":"厦门"},"prologue":"大家好我叫曹志文\r\n我选的片段来自《麦肯锡工作法》，“麦肯锡人”总带着闪耀的光环，但他们在这家全球顶级管理咨询公司的平均工作年限仅是3~5年。为何他们从麦肯锡毕业后，还能活跃于各个行业，取得非凡的成绩？原因就在于麦肯锡独特的工作法\r\n这本书的作者是大岛祥誉，在麦肯锡公司从事公司战略制定等咨询项目。是麦肯锡资深培训师。2002年独立创业，从事高管培训、队伍建构及领导力开发等咨询服务。\r\n 我们看下作者在书中推荐了什么方法，让会议用更短的时间解决问题，让会议更高效，节省与会人的时间成本。","ratings_count":2,"texts":[{"id":9703,"quote":"\u003cp>\u003cstrong>明确会议的“目的”与“目标状态”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>摘自《麦肯锡工作方法》\u003c/strong>\u003c/p>\u003cp>你印象中的会议是什么样的？\u003c/p>\u003cp>只知道开始的时间，却不知道结束时间。\u003c/p>\u003cp>浪费了不少时间却没有什么结果。\u003c/p>\u003cp>在繁忙的时候被会议占用了宝贵的时间。\u003c/p>\u003cp>应该做决定的时候，实际上却什么都没定下来。\u003c/p>\u003cp>都是一些用邮件就能解决的报告事项。\u003c/p>\u003cp>肯定有很多人认为这样的会议根本没必要定期召开吧。\u003c/p>\u003cp>如果员工们的这种情绪爆发出来，那么一定会引发很大的问题。\u003c/p>\u003cp>不过一般来说，在这种不满情绪爆发出来之前，总会有人提\u003c/p>\u003cp>出“会议就是这样的”或者“每周开会很正常”之类的言论来使\u003c/p>\u003cp>大家的心情平静下来，结果会议还是照常进行。\u003c/p>\u003cp>不知不觉地，会议变成了一种形式，毫无价值的会议成为大 家“工作”的一部分，每个人对会议的感觉都变得麻木了。\u003c/p>\u003cp>使会议有意义的3个要素\u003c/p>\u003cp>会议的主持人应该清楚自己主持的会议属于哪一种，并且在会议前和会议中，时刻明确会议的“目的”与“目标状态”。\u003c/p>\u003cp>为了使会议变得有意义，需要让会议的参加者都进行事前准备。主持人应该在会议开始前对参加者说明以下内容。\u003c/p>\u003cp>1、会议目的。\u003c/p>\u003cp>2、目标状态(会议想要实现的目标，想要实现的状态)。\u003c/p>\u003cp>3、参加会议的原因。\u003c/p>\u003cp>任何会议都一样。\u003c/p>\u003cp>如果参加者中有很多老员工，那么只要说明目的和目标状态即可。但对新员工和一起共事时间不长的参加者，应该说明要求其参加会议的原因。\u003c/p>\u003cp>开会之前大致地说明期待的目标，可以提高参加者的积极性。\u003c/p>\u003cp>如果在会议开始之后还没有一个明确的会议目标，甚至需要向参加者询问目标状态，那么这样的会议就是失败的。 \u003c/p>\u003cp>会议正式开始后，主持人要保证会议的目的性不要出现偏离。如果所有参加者都能够时刻明确会议的目的还好，但有时会出现参加者过于激动导致会议偏离本来目的的情况，以至于会议最终没有取得任何成果。\u003c/p>\u003cp>要想解决这个问题，方法也很简单，那就是在会议室的白板上明确地写下会议的目的和目标状态。措辞尽量简洁。\u003c/p>\u003cp>例:\u003c/p>\u003cp>目的：关于xx问题的解决\u003c/p>\u003cp>目标状态：xx问题的解决办法，以及由谁在什么期限内完成\u003c/p>\u003cp>有时候就连会议的主持人也会过于激动，所以应该时刻确认会议的话题是否偏离了目的，并且保证参加者的讨论也在正确的方向上。\u003c/p>\u003cp>一旦发现讨论偏离了目的，可以让大家看白板，然后询间“这次会议的目的是什么”。这样就可以将参加者的意识拉回到正确的目的上来。\u003c/p>","explains":"\u003cp>看完拆页，回想起一年前我在一个团队中参与开发一个新软件，软件功能不明确；我们每两周召开一次例会，产品和开发人员碰头确定接下来2周时间要完成哪些新软件功能，确定后细化执行；最初的一段例会我想之为“连续剧”式会议，而且是类似湖南台版本的“连续剧”。湖南台连续剧特点很鲜明，30分钟的电视剧，10分钟的前情提要，10分钟的下集预告，插播10分钟的广告，外加10分钟的松散剧情；我们前期的会议也非常类似，前半段大家在努力的回忆着上次会议的思路，为什么要做这些功能；中间半段讨论，提出很多新的想法，甚至抛开以前的思路；最后想法无法确定结论，我们下回分解。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; &nbsp;大家都会吐槽这样的会议浪费时间，大家有没有仔细计算过一场无效会议浪费了我们多少时间？根据我的经验，一场会议加前后准备将花费我们四分之一天的工时，甚至更长，一场会议至少四个人，大家可以计算一下一场无效会议最少浪费多少成本；如果采用简单的方法就能节省这些成本，是否值得学习？我们来看看麦肯锡使用什么方法解决低效会议的：\u003c/p>\u003cp>主持人应该在会议开始前对参加者说明以下内容，而且最好以邮件提前通知：\u003c/p>\u003cp>1、会议目的（Purpose）：比如这次会议要解决什么问题\u003c/p>\u003cp>2、目标状态（State）：比如说明问题发生的背景，现象，影响等\u003c/p>\u003cp>3、参加会议的原因（Reason）：如果有新人参加，要提醒新人与会的原因，是旁听还是学习；如果是老员工可忽略这条。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 会议时也可以把这几点写在白板上，会议一旦跑题，主持人可以请大家看白板，并询问：“本次会议的目的是什么？”，把会议拉回正轨\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 这几个技巧简称为PSR方法，也可以不正经的记为“漂亮死人”方法；\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 以刚才我开发软件的例子来说，随着我们例会的深入，大家也意识到了问题，每次例会前，会议主持人在邀请邮件中写下这几个要点：\u003c/p>\u003cp>1、会议目的：参考已列出的软件新功能列表，在会议上讨论可行性，以及负责人和完成时间。\u003c/p>\u003cp>2、目标状态：项目整体思路是怎样的，现在进入到项目那个阶段，和已经完成的功能。 \u003c/p>\u003cp>3、因为没有新人参加，忽略参加会议的原因。\u003c/p>\u003cp>如此之后，会议确实更加明确，高效的达成决议。\u003c/p>","interaction":"\u003cp>A1:\u003c/p>\u003cp>接下来进入练习时间，大家体验一下这样的方法对我们是否有帮助，请大家按照顺时针方向2人一组，进行讨论，如果有剩下的小伙伴就近加入一组；小组已分好，回到我们练习中来。\u003c/p>\u003cp>我们读过这个拆页，了解到为了让会议更有效可以运用“会议目的，目标状态，会议原因”简称“漂亮死人”方法解决，那么，请小伙伴们回忆下自己过去经历过类似的无效或者低效会议，或者自己作为主持人用过类似方法提高会议效率，回忆尽量具体。2分钟后请1个小伙伴分享自己的经历。\u003c/p>\u003cp>学员分享：\u003cbr>\u003c/p>\u003cp>学员：经常公司开大会，会议没有通知主题，也没有限定时间，大家在会议上东说一件事西说一件事，会议开了很久都不知道在开什么主题；\u003c/p>\u003cp>拆书家：那会议最终是否有结论？\u003c/p>\u003cp>学员：最终也没有结论\u003c/p>\u003cp>拆书家：以后在碰到这种会议怎么办呢？\u003c/p>\u003cp>学员：以后都不想去参加这样的会议了\u003c/p>\u003cp>拆书家：下次如果可以，尝试要求主持人提供会议目的，目标状态等必要资料，看下有没改善\u003c/p>\u003cp>学员：好的\u003c/p>\u003cp>A2:\u003c/p>\u003cp>请小伙伴们规划一下在日后作为主持人组织会议中运用“漂亮死人”方法，场景要具体，时间要明确，并在便签纸上记录下行动方法\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>何时组织会议：\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>会议主题：\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>会议目的（P）：\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>目标状态（S）：\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>参加会议的原因（R无新人可以忽略）：\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>学员一：\u003c/p>\u003cp>何时组织会议：&nbsp;技术会议 11.24\u003c/p>\u003cp>会议主题： &nbsp; &nbsp;技术交流\u003cbr>\u003c/p>\u003cp>会议目的（P）： 增加技术交流机会\u003c/p>\u003cp>目标状态（S）： 目前交流为零状态\u003c/p>\u003cp>参加会议的原因（R无新人可以忽略）：忽略\u003c/p>\u003cp>学员二：\u003c/p>\u003cp>何时组织会议：&nbsp;每周一例会\u003c/p>\u003cp>会议主题： &nbsp; &nbsp;指标短板提升\u003cbr>\u003c/p>\u003cp>会议目的（P）： 某项指标的短板提升\u003c/p>\u003cp>目标状态（S）： 指标进程太差，缺口太大\u003c/p>\u003cp>参加会议的原因（R无新人可以忽略）：结合自身的业务，项目，与指标短板相结合\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1541461197000,"updated_at":1541461197000,"ria":true},{"id":6069,"topic":"麦肯锡的情报收集三部曲","learn_goal":"收集高质量情报","remark":"绝大多数的工作，都是从最基础的情报收集“research”开始的，这其中最重要的是收集的质量。如果工作质量高则工作效率会迅速提升，品质也同样会得到提高，这周四来拆书帮紫禁之巅，让我们共同学习训练情报收集三部曲，提高收集信息的质量。","level":"TF1-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"树","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，我是树，字士载，号伯约， 既喜欢独处看书，也喜欢和朋友们撸串聊天侃大山，很高兴能够与大家欢聚一堂，一起共同度过一个美好的晚上。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 请大家和身边的小伙伴每两个人一组。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 大家都知道麦肯锡是全球顶级的管理咨询公司，那么是什么让它成为咨询行业里的常青树呢？\r\n &nbsp; &nbsp; &nbsp;麦肯锡资深培训师大嶋祥誉在书中拆解了公司内部的秘密武器：麦肯锡的专业作风、解决问题的技巧、分析框架的养成、处理信息的能力、提升自我的策略、展现成果的方法，还有麦肯锡式的思考方式。学会《麦肯锡工作法》，让我们不进麦肯锡也能变成优秀的“麦肯锡人”，在团队中脱颖而出！ \r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":9316,"quote":null,"explains":"\u003cp>在读完拆页后呢，我们看到一个词，那就是“情报”，什么是情报呢？是在某一领域内，获取有价值的信息，就是获取情报，这是我们在大数据网络时代每个人的必修课，那么怎样收集到高质量的情报呢？麦肯锡的情报收集三部曲值得借鉴：\u003c/p>\u003cp>第一、明确“情报收集的目的”。所以第一步的核心在要准，找准方向，比如我想通过投资股市来挣钱，这那么我的目标是要挑选出好公司，那么我情报收集的目的就是要找出哪些重要指标可以快速判断一个公司的优劣。\u003c/p>\u003cp>第二、“海量”调查。第二步要广，这里“海量”调查的目标是通过资料、书籍、网络获取相关公司及行业有用的、全面的、最新的信息，不能只依赖网络，网络信息大部分是经过加工的，影响自己的判断，获取的信息要辅助自己从自我视角切换到俯瞰的视角去进行全方位研判分析，建立假设。\u003c/p>\u003cp>第三、去现场。第三步的重点在实，要在第二步深入调查的基础上，为了验证假设，前往现场一探究竟，比如一家公司的大小、位置、产品质量、服务态度、客户群体等一一了解，并与竞争对手的进行对比，得出最后的结论。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;上周在看央视《交易时间》时，介绍了一位投资者的成功经验，他的成功就很好的应用了这三步，在经过几年的股市沉浮之后，他想重仓投资一个公司的股票，在选择前首先他根据多年来的炒股经验确定了鉴别公司优劣三个重要指标：每股净资产、每股未分配利润、每股资本公积金,并根据指标由低到高来筛选出10个公司；第二步通过新闻报道、书籍、网络进一步对所筛选公司的经营状况进行整体的研判对比分析，筛选出2个公司；第三步对最后的两个公司不远万里实地考察，验证对比相关数据，得出最后要投资的股票并购买，三年后抛出该股票翻了近两番。\u003c/p>","interaction":"\u003cp>不知道大家有没有因为自己情报收集不准确或因为情报质量高而引发的故事呢？比如向领导汇报某件事因为只是从网络搜索后整合信息而没有去实地考察而与领导掌握的情况不符，或者在给领导写演讲稿时因为调查清晰，论据充足而得到领导的赏识?\u003c/p>\u003cp>请想想自己有没有类似经历或相关的经验在小组内分享\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;鼓：在上个月领导要求给一个项目要做PPT给他汇报，我连夜加班给领导叫了过去，第二天领导把我做的ppt又重新做了一遍，下午我去汇报的时候发现，完全没有用我做的ppt连背景都换了，领导认为我没有抓住他的重点，资料收集不准确。\u003c/p>\u003cp>&nbsp; &nbsp; 熊：关键是第一步，好多情况下是因为没有搞清楚搜集到做搜索一件事的目的是什么，不然就像先打开谷歌，让后一路维基百科一直这样搜索下去，会越搜越远，老板上周交给我一件事的时候，老板希望我给出个结果，但是我可能只说些有哪些亮点，没有给出具体的数据，所以需要先明确目的，把自己框里面，才能更高效的完成任务。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 在接下来的一周里，大家有没有需要收集的情报呢？这些情报会是什么呢？请写出来，接下来如果用今天的三步法去收集你所需要情报，大家会怎么做呢？请把三步分别列出来，欢迎大家回去后将运用后的效果反馈给我。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;康康：手头的项目做几节中国历史线上课，第一步明确 搜集情报的目的：了解市面上已有的课程的详情，包括平台、体量、定位、作者、定价、文案、销量。第二步海量调查：1.搜索引擎搜索“历史”“课程”等关键词；&nbsp; 2.在知识付费平台，如“喜马拉雅”“得到”“蜻蜓fm”等搜索课程，进行对比，选出两家重量级历史线上平台，第三步去现场实地考察，深入了解线下的制作课程模式。\u003c/p>\u003cp>通过本次拆书，运用麦肯锡的情报收集三部曲：明确“情报收集的目的”、“海量”调查、去现场来持续训练我们的情报收集能力，我是树，愿与大家一道共同进步成长，以昂扬的斗志面对生活的荆棘。\u003c/p>\u003cp>&nbsp; &nbsp;谢谢大家！\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1536917386000,"updated_at":1536917419000},{"id":5002,"topic":"如何与不喜欢的人共事？","learn_goal":"让你更舒服的与不喜欢的人共事","remark":"拆书主题：如何与不喜欢的人共事？\r\n你是否有过某个同事，一举手一投足都让你心烦？\r\n你是否有过某个客户，一开口就觉得给你负能量？\r\n你是否有过某个供应商，一看他/她讲话做事你就气不打一处来？\r\n以上情境，就算你想方设法躲开了这一拨人，但是，这样的人总是会再碰到。这种情况对你的工作效率和生活质量影响非常大。本周三，拆书家冬青将分享给你麦肯锡的工作秘诀，帮你学会如何与不喜欢的人共事。","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"冬青","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"（自我介绍）\r\n大家下午好！我是冬青。刚才介绍过我自己，我是一个希望通过拆书让自己更有内涵的PPT软件应用培训师。\r\n（分组）\r\n为了方便大家与身边的小伙伴讨论学习，我们分一下组。今天我们一共十几位小伙伴，刚好坐成了3桌，我们按桌子分成3组。\r\n今天我要分享的一本书叫《麦肯锡工作法》，麦肯锡是全球顶级的咨询机构，作者曾经在麦肯锡工作过，这是一本关于（如何提高职场工作效率）的书。它的主要内容是（职业态度、职场礼仪、思考、解决问题等）。","ratings_count":0,"texts":[{"id":8096,"quote":"\u003cp>\u003cstrong>【图书介绍】《麦肯锡工作法》\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【页码】第\u003c/strong>\u003cstrong>137\u003c/strong>\u003cstrong>页\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【主题介绍】如何与不喜欢的人共事？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【时长】约\u003c/strong>\u003cstrong>10-15\u003c/strong>\u003cstrong>分钟\u003c/strong>\u003c/p>\u003cp>大家曾受到过彼此之间利害关系或人际关系的阻碍吗？\u003c/p>\u003cp>即便是麦肯锡，也是由人组成的集体，所以要说完全不会产生任何情绪问题，也是在撒谎。\u003c/p>\u003cp>麦肯锡也会出现“我和那位客户的负责人怎么也合不来”、 “不喜欢团队里的那个人”等情况。&nbsp;&nbsp;&nbsp;&nbsp; \u003c/p>\u003cp>不过，即便存在诸如此类的情绪问题，他们也可以做到不让情绪影响工作的质量。&nbsp;&nbsp;&nbsp;&nbsp; \u003c/p>\u003cp>一位心理专家经常说，掌握各种信息的人，总会遇到一两件事情让自己不由自主地赞同，或者产生共鸣。\u003c/p>\u003cp>\u003cstrong>首先，清楚对方是什么类型的人\u003c/strong>。\u003cstrong>其次，\u003c/strong>有意识地关注对方的优点与长处也很重要。因此，试图\u003cstrong>发现对方\u003c/strong>\u003cstrong>10\u003c/strong>\u003cstrong>个以上的\u003c/strong>优点与长处，将产生显著的效果。或者，也可以将其称为寻找对方身上\u003cstrong>自己由衷敬重的特质\u003c/strong>。\u003c/p>\u003cp>令人不可思议的是，通过发现能与对方产生情感共鸣的部分，哪怕只有一小部分，也可以实现与之共享。&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003c/p>\u003cp>这样一来，在彼此合作的过程当中，等自己意识到的时候，工作也许已经出人意料地愉快地展开了。\u003c/p>\u003cp>如果大家现在正苦恼于“不得不一起共事，但是因为情绪上的问题，进展并不顺利”，那么我建议大家暂且撇开对对方的情绪，尝试从多种角度重新考虑与对方相关的信息。\u003c/p>","explains":"\u003cp>好的。我看到大家都已经读完了这个原文片段。\u003c/p>\u003cp>各位伙伴，你是否有过某个同事，一举手一投足都让你心烦？\u003c/p>\u003cp>你是否有过某个客户，一开口就觉得给你负能量？\u003c/p>\u003cp>你是否有过某个供应商，一看他/她讲话做事你就气不打一处来？\u003c/p>\u003cp>以上这些情况，其实对你的工作效率和生活质量影响非常大。就算你想方设法躲开了这一拨人，但是，正所谓“有人的地方就有江湖”，这样的人总是会再碰到。\u003c/p>\u003cp>现在当我们再碰到类似问题的时候，我们可以试试一个新的方法。这个方法来自于这本《麦肯锡工作法》。\u003c/p>\u003cp>这个片段很简单，如何与不喜欢的人共事呢？&nbsp;我整理出书中提到的方法：\u003c/p>\u003cp>\u003cstrong>第一步，分析清楚对方是什么类型的人。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步，发现对方\u003c/strong>\u003cstrong>10\u003c/strong>\u003cstrong>个以上的自己由衷敬重的特质。\u003c/strong>\u003c/p>\u003cp>我给大家解释一下，第一步清楚对方是什么类型的人，可以理解为尽量多地给对方贴标签。举几个例子，我们可以说某个人“懒”、“缺心眼”、“攻击性强”等等，当然要私下贴，别公开。如果大家刚好学习过性格分析，比如DISC、MBTI、九型人格，那就直接用上，其实人内心里最喜欢给别人贴各种标签了，尤其对自己不喜欢的人，待会儿大家体验一下这一步没准会上瘾的~\u003c/p>\u003cp>第二步发现对方10个以上的自己由衷敬重的特质，这个当然可能不那么容易做得到，但是非常关键，相信麦肯锡，请你认真写出10个，自然就会觉得原先不喜欢的人其实也没那么差，也是能合作的。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>举一个我的例子，我自己很不喜欢负责给我们报销的财务同事，因为他常驻当时我们在的那家公司的上海总部，经常丢失我们寄给他的报销发票，还推卸责任给快递和公司前台，结果查到后来还是他自己管理文档没有条理导致的。我有的时候着急就会直接跟他吵起来，结果吵到上面去也没解决。学习了今天的这个技巧以后，我会分析一下这个同事，并且认真想一想他身上值得我敬重的10个以上特质，来撇开我对他的情绪，尝试从多种角度重新考虑与对方相关的信息，确保正常的工作沟通。\u003c/p>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>现在我给每个小组3分钟的时间，请每个伙伴组内分享一下，最近或过去自己曾经碰到的，明明不喜欢却不得不还在一起共事的情形。\u003c/p>\u003cp>（小组讨论）\u003c/p>\u003cp>时间到。我想先请这位小伙伴分享一下自己的例子可以吗？\u003c/p>\u003cp>（学员发言）&nbsp;\u003c/p>\u003cul>\u003cli>\u003cp>请问你曾经有过跟不喜欢的人共事的经历吗？\u003c/p>\u003c/li>\u003c/ul>\u003cp>（学员回答）\u003c/p>\u003cul>\u003cli>\u003cp>请问你觉得什么原因不喜欢呢？\u003c/p>\u003c/li>\u003c/ul>\u003cp>（学员回答）\u003c/p>\u003cul>\u003cli>\u003cp>但你确实需要与他/她共事对吗？\u003c/p>\u003c/li>\u003c/ul>\u003cp>（学员回答）\u003c/p>\u003cp>&nbsp;谢谢分享！所以，我们很有必要通过一些方法来调节自己的情绪，更有效地与对方共事。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>现在，我想给大家2分钟时间，每个小伙伴，用今天学到的技巧，在便签纸上写下，接下来你回到工作环境中，将如何与那个你最不喜欢打交道的人改善工作关系。\u003c/p>\u003cp>（大家练习）\u003c/p>\u003cp>时间到！\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>今天我们学的是与不喜欢的人共事的方法，第一，分析对方是什么类型的人；第二，罗列10个以上对方身上值得你敬重的地方。\u003c/p>\u003cp>希望能对大家有所帮助！我今天的拆书到此结束！谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1523811373000,"updated_at":1523811373000,"ria":true},{"id":4181,"topic":"工作的确认与开展","learn_goal":"学习者在接到上级安排的工作时，知道从三个方面与上司确认，并知","remark":"身为下属，如果想要高质量完成工作，在接到工作任务的时候必须和上司确认三个方面，期限、方向和品质。大多数的工作，都是由情报搜集开始的。如何做好情报搜集也有三步：明确目的，大量调查，拿到一手资料。","level":"TF2-4","duration":50,"status":29,"type":0,"chaishujia":{"username":"grace","city":"福州"},"club":{"name":"福州闽江分舵","city":"福州"},"prologue":"大家好，我叫谢婧，今天要跟大家拆的书籍是《麦肯锡工作法》。F:《麦肯锡工作法》作者是大岛祥誉，曾就职于世界最顶尖的咨询公司麦肯锡。在书中，他将麦肯锡精英的工作习惯进行了提炼，介绍了如何在工作中实现“品质*效率”的39个习惯。\r\nA:这本书非常易读，将39个习惯用非常浅显易懂的语言和例子进行了介绍，跟同类书籍相比，该书每一个章节的篇幅都非常短小，语言都很精炼，几分钟就能读完，内容既不枯燥也不晦涩。而且都跟每天的工作紧密相关。\r\nB:如果你希望自己的工作更上一层楼，如果你想知道精英们都是如何工作，如果你想兼顾工作效率与成果，你可以从这本书中获得不少启发。","ratings_count":1,"texts":[{"id":7161,"quote":null,"explains":"\u003cp>身为下属，如果想要高质量完成工作，在接到工作任务的时候必须和上司确认三个方面：\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 工作完成的期限\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 工作的目的和方向\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 工作要求的品质，或者说工作验收的标准\u003c/p>\u003cp>为什么要确认这三个方面呢？\u003c/p>\u003cp>大家回想一下自己的工作经历，有没有被上司批评的经历？你知道自己为什么被批评吗？如果你在接到工作任务之时就与上级进行确认，是不是会让你的工作更好地得到上级的认同？\u003c/p>\u003cp>比如说，我们有一次要做一个课程的开发，领导让我去做一些相关理论的研究。我花了很多的精力，研究了一整套理论体系，在会议上做工作的汇报。结果汇报完，领导问我，你讲这个是什么意思？为什么要讲这个？我当时心里想，不是让我找相关理论吗？\u003c/p>\u003cp>领导接着说，我是让你找一些跟我们流程相关的理论补充，或者我们有哪些不正确的地方，可以用理论来纠正的。你拿了整套的理论来颠覆我们的认知，对我们有什么帮助？\u003c/p>\u003cp>从刚才的案例，我们可以看出来，我的工作方向完全不是领导想要的，如果我在开展工作之前，跟领导沟通一下工作的思路就不会出现这样吃力不讨好的结果。如果按照工作确认的三个方面，那我们就需要跟领导做这样的沟通：\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 领导，您觉得我的工作在XX时间完成可以吗？或者问领导，这些工作您需要我在什么时候完成。\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 在形成工作思路之后，大约是领导布置完工作半天或者一天之后，跟领导沟通大的工作方向思路，比如说，我把这个体系的理论梳理一下您看行吗？如果并不是领导想要的方向，就会马上给你反馈，不至于走错方向。\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 工作要求的品质，可以跟领导确认，最后的结果我是用ppt还是word呈现？我需要研究多少范围？等等，从验收标准上跟领导做一个确认，这样就能够完成让领导比较满意的工作。\u003c/p>","interaction":"\u003cp>请大家回顾一下，你是不是有被领导批评的场景，批评的原因跟工作开始之前的确认有没有关系？回想一下平时在接到上级布置的任务时，是怎么回应的？是回答一句好，就埋头去干了吗？有没有从这三个方面进行确认？\u003c/p>\u003cp>Y丫，年底了，比较繁忙，领导要做一个18年的绩效考核方案，因为没有跟领导很明确的沟通，等我把任务做好了，他领导挺不满意的，我的想法跟他的想法不一致，在指标上，领导想全方位的考评到，我觉得像主管级的指标是按关键绩效指标考核，这方面出现了出入就被领导批评了。通过学习这个，在沟通方面，是没有做到很明确的沟通。也就是没有达成领导的工作标准，没有很明确的沟通。\u003c/p>\u003cp>林魁：虽然我没有在职场，但是我在学校读研究生，跟我的导师工作。我的导师是英国的，英国的文化跟中国的文化不一样，比较严谨。有时候我在适应中。比如修改一份SCI，导师去英国出差，让我修改一份SCI，导师从英国回来的时候，询问了我的进度。因为之前没有跟他确认好，但是他人比较好，我把修改的发给他，其他内容完成得好，但是时间抓得不够紧。自己觉得挺惭愧，经过今天的拆书，对我以后学习有很大的帮助。\u003c/p>\u003cp>相信大家下次接到这样的任务之后，都能够进行很好的确认。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":7162,"quote":null,"explains":"\u003cp>这里讲的“情报搜集”其实指的是工作前期的调研工作。调研工作包含了对于工作的需求分析，从我们的经验发现，调研工作做得越全面越有深度，你的工作就越有质量。如何做好工作调研呢？主要有三步：\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 明确调研的目的\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 做大量的调查\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 拿到一手材料\u003c/p>\u003cp>如果不做这些调研工作的话，后续的工作可能缺乏基础，不能很好的开展。\u003c/p>\u003cp>举一个我自己的例子好了。我们讲课，大家常常会觉得讲得好不好跟老师的内容或者讲授的方式有关系，但其实不是这样的，前期的调研工作做得越详实，越有针对性，就能够上得越好。\u003c/p>\u003cp>第一步：明确调研的目的。做课程调研的目的是为了了解学员的需求，知道学员想学什么，遇到了什么问题，这样的课堂就能够有针对性地解决学员的痛点。所以每一次的情报搜集，都需要知道为什么要做，要获得哪些的信息。\u003c/p>\u003cp>第二步：做大量的调查。对于授课来说，大量的调查包含对学员的尽量大的覆盖面，还包括对课程内容的调研。对要讲的内容调研越充分，对内容研究越深，了解其他人是怎么讲这个课程的，对课程的建构有什么帮助。\u003c/p>\u003cp>第三步：到现场。其实指的是拿到很细节的材料，一手的资料。比如课程的调研，指的一方面是跟学员面对面的沟通，通过访谈深入了解学员的需求，另外一方面是到授课现场去踩点，做授课的准备。所以说，大部分的工作，前期都可以通过“情报搜集”或者说调研来完成的。\u003c/p>\u003cp>大家可能会有疑问，是不是所有的工作都需要情报搜集呢？或者所有的工作都需要从这三个方面入手？这其实是给大家提供了一个参考的维度和方向，可以根据实际的情况进行调整。\u003c/p>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>下面请大家用5分钟的时间，做一个小组的讨论，\u003c/p>\u003cp>假设你是摩拜单车的产品经理，你需要决定是否在市场上增加自行车的投放，为了做这个决策你可以如何灵活应用情报搜集三部曲。\u003c/p>\u003cp>请小组代表做一个分享。\u003c/p>\u003cp>晓庆：第一步，是否增加摩拜单车的投放，是我们情报搜集的目的。海量调查，我们会用访谈法，问卷调查法，去调研行业领军人物的看法，搜集各方的数据，去了解和做做一个调查趋势和规律。第三步去现场，是去现场，看单车的使用率，看竞争对手的投放量，看自行车的投放率，看是否增加自行车的投放。\u003c/p>\u003cp>钱丹：按三个步骤，第一个，明确情报搜集的目的，是否增加A区域的投放量。第二个，海量调查，偏书面，我们要先调查清楚，我们有多少底子做这个调查，我们有多少人多少费用来做这个调查，在这个基础之上做一个投放量的调查。在限制条件内做最充分的调查。问卷调查或者请专家头脑风暴的方式，提建议。其他的比如组里的其他成员做文字搜集。第三步去现场，是根据所有搜集的书面材料，去印证能达到的目的。去现场相对来说，主要是验证。最后是结合实际情况出一份调研报告。\u003c/p>\u003cp>非常感谢两个小组的分享。简单点评一下，两个组都能应用情报搜集的三部曲。目的都很明确，都是决定是否增加自行车投放。第二步，两组都提到用访谈法，问卷法来去现场，晓庆和丫丫这一组想了非常丰富的方法，能拿到一手数据，钱丹和林魁这一组目的主要是去印证是否吻合，通过这些方法去验证自己的决策。可以看到大家都很好的应用这些方法去讨论。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>分步一：刚才是基于固定的场景做讨论，其实绝大多数的工作都是从调研开始的。请大家说说，在接下来的工作中，哪些场合可以应用情报搜集三部曲？\u003c/p>\u003cp>丫丫：薪酬调研，做薪资方案的时候。非常需要调研。要了解同行同水平的薪酬标准，接下来走方案才有一个参考的依据。\u003c/p>\u003cp>晓庆：拆书三级，要做一个前期的调研。还有培训之前的调查。包括做一些考生的信息也需要前期调研。\u003c/p>\u003cp>林魁：做科研，要做一个领域的研究，就要研究科研的意义所在。\u003c/p>\u003cp>钱丹：要不要办健身卡。\u003c/p>\u003cp>分步二：你打算如何应用今天学到的情报搜集三部曲。\u003c/p>\u003cp>丫丫：首先明确目的，做薪资方案。海量搜集相关的数据，搜集数据之后去现场。调研员工的需求。\u003c/p>\u003cp>晓庆：明确情报搜集的目的为了三级定级成功。海量调查分为几个方式，把三级的材料，把各级的要求进行细致的了解，查阅已经通过的实录，实录的特点和要求。跟大佬访谈，成功原因，也从反面去看失败的原因。去现场，可以去参加其他人的三级定级，观摩定级现场。会遇到什么问题，更细致的准备。\u003c/p>\u003cp>林魁：research钥匙。假设我的钥匙丢了，明确情报搜集的目的是什么。首先是找钥匙，因为很重要。海量调查，问老师有没有看到我的钥匙，问舍友，翻一下书包，调查的形式和方法。去现场，就是按刚才的假设，去实现三个方案。先去最大的可能性，看书包，给舍友，实在没有找一下周边。\u003c/p>\u003cp>钱丹：办健身卡。目的是要不要办。海量调查，上网查，淘宝卖多少钱，闲鱼上卖多少钱，找教练转让多少钱，同样的价钱赠送什么到官网上找。到其他家，竞争对手各自年卡多少钱。问清楚私教，能调查的都调查回来。去现场，给每个健身馆打电话，去体验一下，器械环境。最后做出决定。\u003c/p>\u003cp>通过刚才几位同学的分享，大家都可以很好的应用三步法在工作中应用。丫丫是一个非常契合的工作场景，薪酬制定，晓庆跟生活有一点相关，是有目标的场景，非常吻合，也很详细。林魁的场景不是很典型的工作场景，用到情报搜集的方法，我觉得不是特别适合调研的方法，是比较小的事情，用到的方法应该是比较简单的。钱丹说到的健身馆，听到最多的关键词是钱，其实除了钱，还是需要环境、效果可能需要调研的更丰富一点。看来大家\u003c/p>\u003cp>最后我来总结一下，今天TF2-4跟大家分享了两个内容，第一个内容是希望大家能够学会接到工作任务之后跟上级做一个确认，明确时间、方向和品质。第二个是情报搜集三部曲，明确调查目的，海量调研和去现场。希望大家有收获。谢谢大家！\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1512458297000,"updated_at":1512458297000},{"id":4180,"topic":"工作汇报三步法","learn_goal":"通过本次拆书学习，学习者能够用三步法进行工作汇报","remark":"当你想要跟上级汇报工作的时候，要养成把汇报内容清晰、简练地传达的习惯。本次拆书要分享的就是如何用三步法进行汇报。","level":"TF2-3","duration":20,"status":29,"type":0,"chaishujia":{"username":"grace","city":"福州"},"club":{"name":"福州闽江分舵","city":"福州"},"prologue":"大家好，我是谢婧，今天要拆的书籍是《麦肯锡工作法》。\r\nF:《麦肯锡工作法》作者是大岛祥誉，曾就职于世界最顶尖的咨询公司麦肯锡。在书中，他将麦肯锡精英的工作习惯进行了提炼，介绍了如何在工作中实现“品质*效率”的39个习惯。\r\nA:这本书非常易读，将39个习惯用非常浅显易懂的语言和例子进行了介绍，跟同类书籍相比，该书每一个章节的篇幅都非常短小，语言都很精炼，几分钟就能读完，内容既不枯燥也不晦涩。而且都跟每天的工作紧密相关。\r\nB:如果你希望自己的工作更上一层楼，如果你想知道精英们都是如何工作，如果你想兼顾工作效率与成果，你可以从这本书中获得不少启发。","ratings_count":1,"texts":[{"id":7160,"quote":null,"explains":"\u003cp>这个片段的核心观点是，当你想要跟上级汇报工作的时候，要养成把汇报内容清晰、简练地传达的习惯。主要包含以下3个要素：\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 现状\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 对现状的解释以及理由\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 结论，以及解决办法。\u003c/p>\u003cp>而在实际汇报中，应该用结论-理由的顺序。所以三步应该是请示结论+阐述现状+解释理由。如果不这么做的话，不但条理很混乱，还有可能抓不到重点。\u003c/p>\u003cp>比如说，我有一个场地出租的方案要跟上级确认，可能通常的做法是直接问上级，我们定价288/4小时是否合适。如果只说结论，领导会缺乏判断的依据，他需要你补充相关的信息，所以汇报的时候不仅要把结论请示领导，还要说出你的判断理由，让领导可以明确地给出反馈。\u003c/p>\u003cp>如果运用3步汇报法，可以这样说：\u003c/p>\u003cp>第一步请示结论：领导，您觉得我们的场地出租定价288/4小时合适吗？\u003c/p>\u003cp>第二步阐述现状：我们的定价是成本价基于设备折旧费用，按三年折旧，每个月使用20天计算出来的，\u003c/p>\u003cp>第三步解释理由：我们的竞争对手定价是488/4小时，而我们是内部使用，按成本价计算就差不多了。\u003c/p>\u003cp>这样，我们就通过结论先行，把现状、理由和结论都进行了汇报。大家可能有疑问，汇报中能分得这么清楚吗？实际上，三步法给大家提供的是一个汇报的思路和框架，在汇报中可以灵活应用。\u003c/p>","interaction":"\u003cp>拆书家提问设计：\u003c/p>\u003cp>我们刚刚学习了汇报的三步法，现在一起做一个演练：\u003c/p>\u003cp>请大家认真倾听一下要演练的场景：\u003c/p>\u003cp>假设你是OFO单车的CEO，你希望投资人继续投资OFO，你如何用三步法进行汇报。\u003c/p>\u003cp>学习者案例记录\u003c/p>\u003cp>晓庆：投资人您好，您可以再为我们OFO单车注入五千万的资产。因为，目前OFO在市场上占有率高达50%，这个趋势还在不断上升过程中。在这么高的市场占有率中，如果有更多的现金流到我们的市场，我们可以做更多的投资，可以获得更多的利润。同时，您的公司也需要一些品牌的推广，我们OFO在市场占有率这么高的情况下，我们可以在单车上提供您的产品的品牌宣传。所以您注入5000万资产是非常值得的。\u003c/p>\u003cp>林魁：您好，我是OFO的代表，我想跟你洽谈一下，贵公司继续加大OFO的投入。现在我们的使用客户正在增大，使用客户正在进一步增长，同时，随着市场阶层的加深，在维护与管理方面也有了新的要求和挑战。我们了解到贵单位是专注于机械制造方面，特别是在自行车制造方面有一定的优势，是龙头企业。同时，现有的产业需要创新和创造。我们已经有了具体的规划方案，也有几家企业愿意跟我们合作。不过我们更愿意跟贵单位合作，在今后的合作中可以达到双赢。\u003c/p>\u003cp>谢谢大家的分享，我来总结一下，两位都用到了结论先行，在现状和理由上，是基于市场占有率这一个现状，说了两个理由，一个是现金流让投资人获利更多，一个是利于品牌的推广。林魁也讲得非常好，他从多个层面进行现状的分析和理由的判断，因为市场市场容量的增加，应用阶层的增加所以需要增加投入，这就是一个现状加一条理由，另外一个方面是，现状是龙头企业，理由是合作后会提升实力和认可度达到双赢，信息量很丰富。如果在说现状的时候有更多的数据会更好。\u003c/p>\u003cp>今天给大家分享的是工作汇报三步法，谢谢大家！\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1512452165000,"updated_at":1512452328000},{"id":3643,"topic":"如何改善与上司的配合","learn_goal":"如何摸清上司的类型并进行相应的配合","remark":"拆书家雅韵1-1定级","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"雅韵","city":"合肥市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"【自我介绍】\r\n大家好！我是今天的拆书家，雅韵，“雅”是文雅的“雅”，“韵“是韵律的“韵”。谐音是“亚运会”的“亚运，这样是不是好记了？\r\n我是一位人力资源从业者，2017我的目标之一是在公司内部推动读书会活动，为打造学习型企业建立基础，也帮助我的同事们从阅读中获取知识与成长。但是如何帮助我的同事快速的“学以致用”，把书上的工具和方法转为己用，提升自己的个人能力是我面临的挑战。幸好遇到了“拆书”这个工具，它将成为帮助我达成目标的利器。\r\n同时，也很高兴通过“拆书帮“这个平台，能有机会与在座的各位进行交流与学习，希望2017年我们都能达成自己的目标，更上一层楼！","ratings_count":0,"texts":[{"id":6544,"quote":"\u003cp>【\u003cstrong>拆书帮及拆书方法介绍\u003c/strong>】\u003c/p>\u003cp>在开始今天的拆书之前，先简单的跟大家介绍一下什么是“拆书”和“拆书帮”。2013年，赵周老师在《这样读书就够了》这本书中，首次提出了“拆书”的概念，这是一种强调以提升个人能力、解决问题为目标的成人学习方法。它追求的是“学以致用”的学习效果。而所谓的“拆书法”又称为“RIA便签读书法”。这个方法常用的辅助工具是便签和笔，分为“RIA”三个步骤。R是指阅读书本中的某个片段，I是指用自己的语言复述片段，A又可以细分为A1和A2两个部分： A1是让学习者反思过去的经验。A2是让学习者规划自己未来的行动。 而“拆书帮”是由赵周老师发起的，基于便签读书法应用的学习爱好者社群。它是一个公益性质的社群，目前在全国已有32个城市分舵，还有20多个筹备分舵。而我们霸都合肥的分舵也在积极筹备之中，欢迎有更多的朋友加入我们，一起拆书、一起成长！\u003c/p>\u003cp>【\u003cstrong>片段\u003c/strong>】\u003c/p>\u003cp>今天我们要学习的片段选自《麦肯锡工作法》，请大家阅读手中的片段内容。看完的小伙伴可以向我举手示意。\u003c/p>\u003cp>深受上司喜爱的部下都有一个共同特点，那就是具有摸清上司类型的能力。\u003c/p>\u003cp>在现实工作中，我们应该从中立的视角观察上司属于什么类型，然后做出相应的配合。这样的话你的工作肯定会变得非常顺利。\u003c/p>\u003cp>接下来为大家介绍几个比较有代表性的类型，以及配合的方式。看看你的上司属于什么类型？\u003c/p>\u003cp>1. &nbsp; &nbsp; 情感型还是理智型？\u003c/p>\u003cp>【情感型】直率、感情丰富、有气势、重视共鸣、容易感动、不但追求结果同样重视过程，用自己的感性来描述自己的经验和方法。\u003cbr>\u003c/p>\u003cp>对于这种类型的上司应该采取如下的配合方法：\u003c/p>\u003cp>谈话准备：在正式开始之前，用“今天天气不错”“您的孩子身体怎么样”之类的寒暄来拉近与对方的关系。\u003c/p>\u003cp>谈话节奏：把节奏交给对方，配合对方的节奏来进行交流。\u003c/p>\u003cp>谈话内容：可以坦白地说出自己的请求或让对方决定。对于自己不懂的内容可以直接说“不清楚”，然后请对方解释。时间允许的情况下也可以闲聊一些工作之外的内容。\u003c/p>\u003cp>感情表现：采用“非常感谢”“很高兴”“没问题”等具有共鸣的感情词语，配合适当的身体语言。\u003c/p>\u003cp>【理智型】自制、重视理论、准备周全、沉着冷静、讨厌借口和浪费时间、对逻辑讨论有反应。\u003c/p>\u003cp>对于这种类型的上司应该采取如下的配合方法。\u003c/p>\u003cp>谈话准备：无关的话题都是浪费时间。开门见山地直入主题。\u003c/p>\u003cp>谈话节奏：除非得到特殊的指示，否则必须由自己决定节奏。\u003c/p>\u003cp>谈话内容：尽可能详细地按照顺序进行描述，然后寻求对方的评价和指示，不要闲聊。\u003c/p>\u003cp>感情表现：不需要。\u003c/p>\u003cp>2. 单独型还是复合型？\u003c/p>\u003cp>【单独型】这种类型的上司当一件工作结束后才会开始接下来的工作，不擅长同时处理多个工作。\u003c/p>\u003cp>对于这种上司应该集中在一件工作上进行商讨和汇报。因为这种类型的上司并不在意花费时间，所以你可以诚恳地找他商量问题。\u003c/p>\u003cp>【复合型】这种类型的上司擅长同时处理多项工作，但容易遗忘，出现问题处理一半就不了了之的情况。\u003c/p>\u003cp>对于这种类型的上司可以一下提出多个问题。他们时常会提出很好的创意，非常适合作为咨询和激发灵感的对象。\u003c/p>","explains":"\u003cp>&nbsp; &nbsp;大家在工作中可能有这样的体会，就是与领导在工作配合上会发生一些不顺，这经常是由于上级的类型不同，沟通方式与对方习惯不匹配造成的问题。如果我们准确地分析出领导的类型，用相应的沟通方式去处理，则可以帮助我们与领导建立起良好的配合关系，工作少一些阻力，多一些助力。少一些沟通不畅，多一些愉悦的心情。反之，如果跟领导沟通不畅，可能很好的点子或者方案却得不到理解和支持，工作难以开展，也得不到正面评价。\u003c/p>\u003cp>对于这样的问题，片段中给出的建议是：\u003c/p>\u003cp>1. &nbsp; &nbsp;分析自己上级是那种类型。\u003c/p>\u003cp>【情感型】比较偏感性，追求结果的同时也重视过程。\u003c/p>\u003cp>【理智型】偏理性型，重视理论和事先准备，对逻辑讨论有反应。\u003c/p>\u003cp>【单独型】可称为“单线程”，就是倾向结束一项工作再开展下一项工作。\u003c/p>\u003cp>【复合型】擅长“多线程”，即同时处理多项任务，但是容易忘记。\u003c/p>\u003cp>2. &nbsp; &nbsp;针对上司的类型，分别采取相应的配合方式。\u003c/p>\u003cp>【情感型】以寒暄开场，拉近感情。让对方主导谈话节奏，不懂的问题也可以请教对方。沟通过程中有一些积极的反馈，比如“很高兴”，“没问题”等来保持与对方的情感互动。\u003cbr>\u003c/p>\u003cp>【理智型】自己控制谈话节奏，开场直奔主题，详细说明后等待对方评价意见。勿闲聊。\u003c/p>\u003cp>【单独型】每次集中汇报一项工作，而且可以与上级深入探讨。\u003c/p>\u003cp>【复合型】可以一次沟通多项工作任务，而且适合向对方咨询一些需要创意和灵感的问题。\u003c/p>","interaction":"\u003cp>【\u003cstrong>A1\u003c/strong>】\u003c/p>\u003cp>我就曾经遇到一位合作不顺的上司。公司大boss在我上岗前，跟我谈了公司的现状和对我的期望。就是公司团队成员分别来自两个合作方：一所高校和一家上市公司，相互之间存在很大的工作风格和文化差异，希望我作为人力资源负责人能整合公司文化，帮助团队融合。我的直接上级则是来自高校的一位老师。\u003c/p>\u003cp>我入职后在公司内部做了一些访谈和调研，然后带着对HR工作的思考和建议去找这位领导沟通接下来的工作计划。当我找到这位领导，谈到我了解的公司现状和问题分析时，就被她打断了，也来不及沟通后面对HR工作的设想和计划。后面在各种工作安排和合作中，总是疙疙瘩瘩。双方的互评也比较负面。\u003c/p>\u003cp>当时觉得无法合作下去，开玩笑跟大老板说”看来我跟xx领导八字不合“，后来以辞职结束这段痛苦的合作经历。其实我和当时的这位领导都很敬业，个人角度也无不合与冲突，主要是体现在工作配合上不顺畅。现在反思，如果再遇到这样的情况，可以中立的分析领导类型，找出适合领导的沟通与合作方式，逐步建立信任，多少会有所改善。工作局面也不会那么被动。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>下周要与公司总经理针对近期工作上的重要事项进行沟通，我会根据片段中给出的主要领导类型来分析我的领导属于那种类型，在相应地准备沟通内容与节奏。\u003c/p>\u003col>\u003cli>\u003cp>上司类型：理智型+复合型\u003c/p>\u003c/li>\u003cli>\u003cp>针对上司的类型，在进行谈话时，注意以下事项：\u003c/p>\u003cp>a) &nbsp;沟通前准备周全，列一张清单及重点，沟通时逐项讨论。\u003c/p>\u003cp>包括重点岗位招聘计划、 &nbsp;下周总部领导接待安排、明年1月年会主题及形式、2017年销售奖金政策调整思路、服务部门能力提升项目进展及下一步计划等内容。\u003c/p>\u003cp>b) 对于要沟通的问题事先全面考虑并分析，形成建议。\u003c/p>\u003cp>比如2017销售奖金计划，需要结合明年的产品策略，体现激励效果。服务能力提升，从维修能力和现场服务水平两个维度进行客服人员能力评估，基于评估结果再进行后续的培训、考核、2017目标设定。\u003c/p>\u003cp>c) &nbsp;沟通时直接切入主题，并按问题清单顺序详细汇报。当中可征询对方的评价和意见。比如是否同意，有何意见等。\u003c/p>\u003cp>d) 如上司对一项事情具体询问考虑点，或者决策原因时，给出有逻辑性的分析。\u003c/p>\u003cp>比如2017销售奖金制度，先提出修改建议，再针对考虑点进行描述，如2016年新政策实施结果发现一些方面需要调整、后续调整将结合2017产品策略需求、鼓励销售追求更高目标、强化激励效果等几个方面进行。\u003c/p>\u003cp>e) 对于有些需要求变的事项，比如明年1月年会的主题，形式，可以请上司给出建议，充分利用其思维活跃有创意的优势。\u003c/p>\u003c/li>\u003c/ol>\u003cp>沟通过程中，集中注意力讨论当前话题，不闲扯无关内容。\u003c/p>\u003cp>【\u003cstrong>总结\u003c/strong>】\u003c/p>\u003cp>今天我们学习了摸清上司的类型，再根据对方的类型在工作中采取相应的方式予以配合，这样我们与上司的沟通合作会变得容易。希望我今天的分享对大家有所帮助，期待我们下次的相聚和交流。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1505057626000,"updated_at":1505059256000,"ria":true},{"id":2902,"topic":"学会明确会议的“目的”与“目标状态”","learn_goal":"学会明确会议的“目的”与“目标状态”，开有意义的会","remark":"你印象中的会议是什么样的？只知道开始的时间，却不知道结束时间？浪费了不少时间却没有什么结果？在繁忙的时候被会议占用了宝贵的时间？应该做决定的时候，实际上却什么也没有定下来？怎样开一次有意义的会议呢？欢迎大家一起来探讨。","level":"TF2-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"许晓勤","city":"东莞"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是今天的拆书家许晓勤。\r\nF:今天我要跟大家拆的这本书是《麦肯锡工作法——麦肯锡精英的39个工作习惯》。本书以实现“品质×效率”为主题，介绍麦肯锡内部人士最重视的“39个工作习惯”。作者是日本人大岛祥誉，是麦肯锡公司资深管理咨询师。\r\nA:这是一本易懂、可操作性强的书，有读者这样评价：“只要实践书中提到的习惯，一定会让其他同事把你视为能干的新人。”\r\nB:本书中的39个工作习惯是麦肯锡亲身实践的“立竿见影”的简单习惯，身处职场的你只要掌握这些习惯就能提高解决问题的能力，并且能够保证工作的品质与效率。在职场中，有一件事是大家都无法避免的，那就是开会。你印象中的会议是什么样的？浪费了不少时间却没有什么结果？在繁忙的时候被会议占用了宝贵的时间？应该做决定的时候，实际上却什么也没有定下来？听到“开会”二字，你是否有点痛苦的感觉呢？今天我们拆解本书的一个工作习惯：明确会议的“目的”与“目标状态”。只要你实践这个习惯，你就可以开有意义的会议。","ratings_count":0,"texts":[{"id":5685,"quote":"\u003cp>P146\u003c/p>\u003cp>使会议有意义的3个要素\u003c/p>\u003cp>为了使会议变得有意义，需要让会议的参加者都进行事前准备。主持人应在会议开始前对参加者说明以下内容。\u003c/p>\u003cp>1.会议目的。\u003c/p>\u003cp>2.目标状态（会议想要实现的目标，想要实现的状态）。\u003c/p>\u003cp>3.参加会议的原因。\u003c/p>\u003cp>任何会议都一样。\u003c/p>","explains":"\u003cp>通常，会议分为4种：1.报告；2、评审（工作进展情况、分析和探讨、人事考察，等等）；3、为了寻找灵感而召开的讨论会；4、提高团队的凝聚力。而无论主持哪一种会议，主持人在开会前，如果能明确会议的三要素“目的”、“目标状态”和“参会原因”，就能使得会议更有意义。\u003c/p>\u003cp>【预防可能的异议】说到这里，可能会有伙伴要问了，例行会议（例如每周开一次的组内会议、每月开一次的店长会议），参会原因已经很明确，还要每次都强调吗？我们认为是这样，如果是部门内部周期性开展的例会，参会者均是“老司机”，那么可以省去说明参会原因。可能还有其他小伙伴要问，会议时间和地点不也是会议要素吗？是的。但我们认为，这两个要素不对会议的意义具备影响。我们讨论的是怎样开有意义的会议。\u003c/p>\u003cp>由此，我们做个小结：会议三要素中，我们要聚焦的是“目的”与“目标状态”。首先，开会之前大致地说明期待的目标，可以提高参加者的积极性。其次，简明扼要地列明会议想要实现的目标、想要实现的状态，可以引导与会者提前做好相关资料的准备和收集工作，提高会议效率。在会议前和会议中，要时刻明确会议的“目的”与“目标状态”。如果在会议开始之前还没有一个明确的会议目标，甚至需要向参加者询问目标状态，那么这样的会议就是失败的。而且在会议正式开始后，主持人要保证会议的目的性不要出现偏离。如果所有参与者能够时刻明确会议的目的还好，但有时会出现参加者过于激动导致会议偏离本来目的的情况，以至于会议最终没有取得任何成果。\u003c/p>\u003cp>举个例子，周二下午我们收到会议通知，内容如下：周三8:45早会，地点：后台小会议室。\u003c/p>\u003cp>这场会议令人期待吗？答案显而易见。收到通知的时候，已经有同事在嘟囔：“整天就知道开会，那么多工作怎么做得完？”会议的目的与目标状态是什么？不明确。实际上，每周三我们团队召开例行早会，会议目的是宣贯最新业务受理指引通知，而目标状态是希望所有办理员在学习之后能正确地按照指引办理好相关业务，不要出现人为失误带来损失和麻烦。\u003c/p>\u003cp>会议开始后，讨论到某一项业务的实际操作时，有办理员提出这项业务太复杂了，要修改受理积分才比较合理，不然没多少人愿意主动受理这类业务。然后，会场就开始了一场关于受理积分标准的激烈讨论了。会议目标偏离了，我们花了好多时间还不能把业务知识宣贯完毕……\u003c/p>\u003cp>其实，解决方法就是明确会议的目的与目标状态，并把它们写在会议室的大白板上，时刻提醒与会者回归会议主题。\u003c/p>","interaction":"\u003cp>【A2】催化应用（分步催化1）（6分钟）\u003c/p>\u003cp>拆书家提问设计（逐字稿）：团队内部例行会议、解决突发问题的会议、跨部门沟通会议、员工沟通会议、党员学习会议、项目汇报……你参加过的大大小小的会议中，哪一次的会议让你感觉缺乏意义？当时的情景是怎样的？请在小组内分享一下。\u003c/p>\u003cp>学习者案例记录:\u003c/p>\u003cp>学员雯雯：有时候，某部门组织个调研会议，与会人员把相关困难、现状抛出来。现场主持会议人员不能对与会人员提的问题做个反馈，只是在听，感觉这个会议意义不大。\u003c/p>\u003cp>其他学员的案例：略。\u003c/p>\u003cp>【A2】催化应用（分步催化2）（6分钟)\u003c/p>\u003cp>拆书家提问设计（逐字稿）：如果你是当时那个会议的主持人，你会如何明确会议的目的与目标状态？请在便签纸上写好，然后在小组内分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学员雯雯:如果由我来组织这次会议的话，我想我可以事前让参与人员知悉以下几个方面的信息，让参与人员感觉会议的意义和价值。\u003c/p>\u003cp>1、会议目的：本次会议主要目的是了解上半年各部门工作开展情况和存在问题。\u003c/p>\u003cp>2、目标状态：会议除了收集开展情况外，还会就大家提出的问题给予相应回应，如可以现场答复解决就现场回应，如现场无法解决则事后将收集到的问题提交相关责任部门跟进解决处理。\u003c/p>\u003cp>3、参会原因。这次会议事关企业发展，也事关各位参会人员的切身利益，所以希望大家积极参与并踊跃发言。\u003c/p>\u003cp>其他学员的案例：略。\u003c/p>\u003cp>结束语：我们今天通过学习明确会议的“目的”与“目标状态”去开一场有意义的会议，希望大家在日常工作和生活中能够运用这个技能，使自己的会议更加有意义，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1497267547000,"updated_at":1497267547000,"ria":true},{"id":2171,"topic":"“空，雨，伞”思考方法","learn_goal":"了解什么是“空雨伞”思考方法，以及在生活中如何运用","remark":"","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"潇湘梅","city":"长沙"},"club":{"name":"长沙橘洲分舵","city":"长沙"},"prologue":"先分组。\r\n“麦肯锡人”总带着闪耀的光环，但他们在这家全球顶级管理咨询公司的平均工作年限仅是3~5年。为何他们从麦肯锡毕业后，还能活跃于各个行业，取得非凡的成绩？\r\n原因就在于麦肯锡独特的工作法。\r\n麦肯锡资深培训师大嶋祥誉在《麦肯锡工作法》中拆解了公司内部的秘密武器：麦肯锡的专业作风、解决问题的技巧、分析框架的养成、处理信息的能力、提升自我的策略、展现成果的方法，还有麦肯锡式的思考方式。《麦肯锡工作法》展现精华的7堂课，让你的竞争力立马提升50%，并且终生受用。\r\n学会《麦肯锡工作法》，让你不进麦肯锡也能变成优秀的“麦肯锡人”，在团队中脱颖而出！","ratings_count":0,"texts":[{"id":4831,"quote":"\u003cp>在寻找解决问题的方法时，麦肯锡有一个非常贴切的比喻。\u003c/p>\u003cp>那就是被称为，“空、雨、伞”的思考方法。\u003c/p>\u003cp>当我们准备出门时看一看天空，好像就要下雨的样子，所以我们会选择带伞出门，这样就算一会儿真的下起雨来，也不至于被淋湿。\u003c/p>\u003cp>当我们将这一过程分为“空、雨、伞”进行思考后，就会发现如下的关系。\u003c/p>\u003cp>“空”表示的是“如今处于怎样的状况”这一“事实”。如果“天空中全是乌云，那么很快就会下雨”。\u003c/p>\u003cp>“雨”，表示的是“如今的状况表示怎么样的含义”这一“解释”。也就是说，根据事实会得出何种结论。随时可能下雨的状况，得出如果被淋湿会影响心情的解释。\u003c/p>\u003cp>“伞”表示的是在了解事实与解释之后，所应该实际采取的行动，也就是“解决办法”。只要带伞出门就不会被雨淋湿。\u003c/p>\u003cp>也就是说，只要掌握“空、雨、伞”思考方法的人，就不会被雨淋湿。\u003c/p>\u003cp>事实、解释，以及解决办法，这三点必须环环相扣。\u003c/p>\u003cp>问题必须得到解决，不管收集到多少情报和数据（事实），如果无法对其进行解释，并且找到解决办法，那么这项工作就是毫无意义的，而且也永远无法结束。\u003c/p>","explains":"\u003cp>“空、雨、伞”的思考方法，对应的是“事实、解释，以及解决办法”。事实、解释，以及解决办法，这三点必须环环相扣。事前准备是解决问题的重要条件。\u003c/p>\u003cp>比如，当我们准备出门时看一看天空，好像就要下雨的样子，所以我们会选择带伞出门，这样就算一会儿真的下起雨来，也不至于被淋湿。\u003c/p>\u003cp>又比如，假设你和一位或许，会成为恋人的女性进行第二次约会。这是决定你们两人今后关系的非常重要的一天。\u003c/p>\u003cp>虽然你们的第一次约会聊得很开心，比较成功，但是，如果今天不顺利的话，恐怕很难有进一步的发展。\u003c/p>\u003cp>本来你打算开车带她去郊外玩，结果当天高速公路，因为发生了事故而堵得水泄不通，车子停在路上纹丝不动。接下来的行动计划都不得不做出改变，对方的心情也越来越差。\u003c/p>\u003cp>在这种情况下，如果是一个真正会工作的人，那么他肯定会针对高速公路出行这一事实，提前做好应对一切风险的准备。因为高速公路的交通情况，是完全不与你的个人意志发生改变的。\u003c/p>\u003cp>为了应对堵车的风险，你也可以提前准备对方喜欢的音乐，或者在手机或平板电脑里拷贝一些双方都感兴趣的，可以打发时间的内容。\u003c/p>\u003cp>别忘了根据上一次约会时悄悄打听到的情报，在车里藏一个对方喜欢的小礼物。\u003c/p>\u003cp>或者因为堵车而不得不取消约会计划之后，才想起应该在车里准备一些他喜欢的音乐则为时晚矣。\u003c/p>\u003cp>这就是在已经下起雨来的时候，还为了买伞而四处奔走的悲惨局面。\u003c/p>","interaction":"\u003cp>\u003cstrong>&nbsp;[A1]激活经验\u003c/strong>\u003c/p>\u003cp>在工作上也是一样，我们周围的环境都不受我们意志的控制而不断的发生着改变，就好像高速公路上的交通情况一样。\u003c/p>\u003cp>那通过读这个拆页，了解了事实、解释，以及解决办法，这三点必须环环相扣。事前准备是解决问题的重要条件。\u003c/p>\u003cp>那么，请想一想自己有没有类似的经历，或相关的经验，现在每人在小组内分享。时间5分钟。\u003c/p>\u003cp>接下来，请××来分享一下你的案例。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>一个小伙伴分享了她要过拆书1-1的经历，说为了过级，她想到了两种结果，一个是过，一个是不过，为了能够一次性通过，就必须按照拆书手册上的要求认真写好拆书逐字稿，然后好好练习，争取过了。但是现场也可能有意外，没有过的话，要认真反思，做好复盘。\u003cbr>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003cstrong>[A2]催化应用\u003c/strong>\u003cstrong>\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>接下来，请大家根据这个“空、雨、伞”，写下一个你的行动规划。\u003c/p>\u003cp>学习者案例记录：一个小伙伴分享A2，加班是事实，为了让自己心情愉悦，决定加班后给予自己奖励，如爬山，电影等。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1489761366000,"updated_at":1489761696000,"ria":true},{"id":1719,"topic":"麦肯锡工作法之电梯汇报法则","learn_goal":"通过本次现场的学习，学习者能够学会用30秒时间提出3个要点的","remark":"工作中，我们常常遇到这样的情况：你的领导每天都很忙，而你必须占用他的时间，请他为你的工作做决策，否则工作便无法继续。你上前说：“王总，关于某某事情，我有个问题想和您汇报一下......” \r\n—— “现在不行，我们再找时间沟通吧！”\r\n你的问题就这样被搁置了…\r\n如果你有这样的困惑，那就不要错过本期的拆书哦~露露将和你一起练习麦肯锡精英常使用的一个说话技巧，帮你争取到与上司交流的时间，不再因为领导而耽误自己的工作进度。当你用第一个片段的技巧成功地争取到上司的时间之后，接下来就必须简洁的表达你要说的内容。麦肯锡给出一个“电梯测试”的方法，教你如何用30秒的汇报技巧","level":"TF2-1","duration":25,"status":0,"type":0,"chaishujia":{"username":"牛魔王","city":"杭州市"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"开场： 大家好，下面进入我的带拆环节，先进行自我介绍，我用三个标签介绍自己。第一个标签：特别“牛”的姑娘（我属牛/金牛座/牛年结婚/职业生涯从蒙牛乳业开始）；第二个标签：营销实践者，营销砖家，从事营销工作7年，目前服务于零售行业；第三个标签：学习爱好者：现阶段专注于拆书技能的过级，走在成为三级拆书家的路上。","ratings_count":0,"texts":[{"id":4284,"quote":"\u003cp>习惯13：用30秒时间提出3个要点\u003c/p>\u003cp>当你用“可以占用您1分钟时间吗”成功的争取到上司的时间之后，接下来就必须简洁的完成“报、联、商”。\u003c/p>\u003cp>据说在美国的硅谷，有一位年轻的经营者在电梯前等待一位著名的投资人，趁着和他共同搭乘电梯的30秒时间介绍自己的事业，从而成功地获得巨额的资金援助，这就是著名的“电梯游说”。\u003c/p>\u003cp>先不管这个成功的创业故事是否真实，但这个方法确实是出自麦肯锡的“电梯测试”。\u003c/p>\u003cp>所谓“电梯测试”就是在搭乘电梯的30秒内，必须向顾客完美的说明现存的问题以及解决方案。也就是说，在麦肯锡工作的员工，用“可以占用您1分钟的时间吗”得到与上司交谈的许可之后，要用30秒的时间说明重点，然后给上司30秒的时间做出判断。\u003c/p>\u003cp>或许有人认为30秒的时间太短。但习惯之后你会发现30秒的时间已经绰绰有余。请思考一下，30秒的时间足够播放两段的电视广告。一段电视广告只有短短15秒，却足以使消费者产生购买的欲望，或者提出具体的解决办法和需要广而告之的事情，给人留下强烈的印象，当然我们没有电视广告那样准备充足的素材和背景音乐，但却多出一倍的时间。\u003c/p>\u003cp>为了在30秒内简洁地向对方说明情况，麦肯锡的优秀经营顾问们经常使用被称为“3个要点”的技巧。从心理学上来说，2个给人的感觉太少，4个太多，所以3个数量刚刚好。\u003c/p>\u003cp>他们在平时思考的时候就养成了将要点分成3部分的习惯。所以，越是在短时间内，他们所传达的内容越清晰、简洁、接近本质。反之，如果是持续30秒以上的交流，那么最想传达的内容可能变得不那么明确了。\u003c/p>\u003cp>那么，应该如何总结出3个要点呢？\u003c/p>\u003cp>不管是说明还是“报、联、商”，首先都要将想要传达的内容分为以下3个要素。\u003c/p>\u003cp>1.现在掌握的情况\u003c/p>\u003cp>2.对现状的解释以及理由\u003c/p>\u003cp>3.结论以及解决办法\u003c/p>\u003cp>最简单的例子就是第一章中提到过的“空、雨、伞”、假设你要劝一个准备 出门的人带雨伞，那么过程应该是这样的。例1：建议对方带雨伞：\u003c/p>\u003cp>1.现状的掌握情况\u003c/p>\u003cp>“xx先生，请等一下，抬头看一看，满天都是乌云。”\u003c/p>\u003cp>2，对现状的解释以及理由。\u003c/p>\u003cp>“这说明一会儿很有可能突然下雨，可能会被淋湿。”\u003c/p>\u003cp>3.结论以及解决方法。\u003c/p>\u003cp>“请带上这把雨伞。”\u003c/p>\u003cp>在实际应用中，顺序应该变更为“结论—理由”。特别是在商业领域，一般情况下都应该首先告诉对方结论，然后再告诉理由。\u003c/p>\u003cp>“请带上这把雨伞，抬头看一看，满天都是乌云，这说明一会儿很有可能突然下雨。”像这样先说出结论，然后补充理由。\u003c/p>\u003cp>当然30秒只是一个标准，并不意味着一定要限制在这么短的时间之内。关键在于将传达的信息集中在真正重要的内容上，并且将内容分为3个要点，这样更容易使对方理解。\u003c/p>\u003cp>不如明天就找一个在电梯上碰到的让你做一下练习吧！\u003c/p>","explains":"\u003cp>【导入：问题场景】1分钟\u003c/p>\u003cp>当你用第一个片段的技巧成功地争取到上司的时间之后，接下来就必须简洁的表达你要说的内容。麦肯锡给出一个“电梯测试”方法，教你如何用30秒的时间提出3个要点。\u003c/p>\u003cp>【图书介绍】：1-2分钟\u003c/p>\u003cp>&nbsp;今天我要拆解的片段选自《麦肯锡工作法—麦肯锡精英的39个工作习惯》，作者是大岛祥誉，曾在麦肯锡公司从事新事业开拓战略、公司战略以及经营战略的制定等咨询项目。2002年独立创业，从事高管培训、及领导力开发等咨询服务。书中的39个工作习惯是麦肯锡亲身实践的“立竿见影”的简单习惯。如果你读过麦肯锡的经典著作《金字塔原理》你会发现，这本书是根据原理的具体应用。\u003c/p>\u003cp>【FAB法介绍图书】\u003c/p>\u003cp>特点：1.整书将39个习惯进行了归类\u003c/p>\u003cp>2.每个章节很简短，但重点突出，并且每个习惯后有个小结提炼。\u003c/p>\u003cp>优势：方便学习者按照类别培养练习这些习惯，每章小结可以帮助学习者快速复习重点。\u003c/p>\u003cp>好处：通过学习本书并工作中不断练习这些的简单习惯，可以有效提高我们解决问题的能力及工作的品质与效率。\u003c/p>\u003cp>【R环节：用30秒时间提出3个要点】1-2分钟\u003c/p>\u003cp>【I环节：重述原文】3-5分钟\u003c/p>\u003cp>简明扼要的说明或汇报，首先要将想要传达的内容分为以下3个要素：\u003c/p>\u003cp>1.现在掌握的情况2.对现状的解释以及理由3.结论以及解决办法\u003c/p>\u003cp>其次，在实际表达时先说结论（要素3），再表达理由（要素1和2）\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>原文中也有强调，30秒只是一个标准，并不意味着一定要限制在这么短的时间之内。关键在于将传达的信息集中在真正重要的内容上，并且将内容分为3个要点，这样更容易使对方理解。\u003c/p>\u003cp>【强调不那样做的坏处】\u003c/p>\u003cp>人们一般向别人说明一件事情时，会从头到尾描述一遍事情的经过，而且在表达的过程中还会重点强调自己比较关注的细节的点。\u003c/p>\u003cp>但这样的表达，很有可能让听的人抓不住重点，越听越糊涂。因为在我们讲述的过程中，听众会假定你说的每一句话之间存在着某种逻辑关系，如果你不预先告诉听众结论，以及这个结论和事情本身的逻辑关系，人们一般会按照自己的逻辑进行推理，就会出现和你想表达的有偏差。\u003c/p>\u003cp>所以，在简短的时间范围，先说结论再阐述理由，是职场人学会表达的一个重要技能。\u003c/p>\u003cp>【举例子】\u003c/p>\u003cp>事情背景：需要设计师加急设计门店装饰物。原因是原计划在13档开展微信招募活动，但由于和总部安排的活动冲突，要调整在12档开展，下周二就要下发执行手册。\u003c/p>\u003cp>我：“鹏哥，总部13档开展了支付宝派券活动，经过系统压力测试，这档期不能再开展其他优惠券的活动了。我们13档有安排微信招募的优惠券活动，所以需要调整到12档。下周二要下发执行手册，需要在今天完成微信会员招募的装饰设计。需求已经发邮件给你了。”\u003c/p>\u003cp>案例反思：用今天的片段的技巧重新沟通，我会这样说：鹏哥，需要你帮忙今天完成一个微信招募的门店装饰物设计，需求在已经发送的邮件里。这么着急是因为我们的计划与总部发起的支付宝活动有冲突，下周二就要下发执行手册。\u003c/p>","interaction":"\u003cp>【分小组】\u003c/p>\u003cp>【A1环节：激活学习者经验】5分钟（4分钟，1分钟分享）\u003c/p>\u003cp>显像提问法：向领导汇报进度时，领导有没有用“哦……然后呢？……”这样类似的句式引导你往下说，最近一次发生这样的情形，请描述一下你是怎么说的？每人1分钟，请在小组内分享一个失败案例。\u003c/p>\u003cp>参与者分享：人力部突然召集我们产品部人员开会，要求在下周完成一个线上的课程。海霞回来和领导说：今天人力部找我们开会，这个会议不是市场部发起的，现在人力部让我们下周完成一个网课的内容，时间太紧，我完不成。领导说：那怎么办？\u003c/p>\u003cp>案例分析：这个案例在海霞和领导沟通时，没有结论以及解决办法，仅仅说明了时间太紧，自己完不成的现状。\u003c/p>\u003cp>【A1+环节：请学习者加工反思】5分钟（4分钟讨论，1分钟分享）\u003c/p>\u003cp>如果刚刚讲述的失败案例让你再说一遍，用今天片段给出的方法，你会怎么表达呢？每人参与者分享：如果重新沟通一次，我会和领导这样说：领导，今天人力资源部开会说需要我们在下周一提交一个关于XX产品的网课内容，根据我们部门这周的工作计划，无法按时完成，是否能请您与人力资源部协商一下时间?\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1482924557000,"updated_at":1482924557000,"ria":true},{"id":1450,"topic":"用1分钟作为开头争取沟通时间","learn_goal":"学会用占用1分钟作为开头争取沟通时间","remark":"工作中，我们常常遇到这样的情况：你的领导每天都很忙，而你必须占用他的时间，请他为你的工作做决策，否则工作便无法继续。——好不容易逮到领导在办公室，这时你赶紧上前说：“王总，关于某某事情，我有个问题想和您汇报一下......”  \r\n—— “现在不行，我们再找时间沟通吧！”\r\n你的问题就这样被搁置了…\r\n如果你有这样的困惑，那就不要错过本期的拆书哦~露露将和你一起练习麦肯锡精英常使用的一个说话技巧，帮你争取到与上司交流的时间，不再因为领导而耽误自己的工作进度。","level":"TF2-2","duration":25,"status":0,"type":0,"chaishujia":{"username":"牛魔王","city":"杭州市"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"大家好，下面进入我的带拆环节，先进行自我介绍，我用三个标签介绍自己。第一个标签：特别“牛”的姑娘（我属牛/金牛座/牛年结婚/职业生涯从蒙牛乳业开始）；第二个标签：营销实践者，营销砖家，从事营销工作7年，目前服务于零售行业；第三个标签：学习爱好者：现阶段专注于拆书技能的过级，走在成为三级拆书家的路上。","ratings_count":0,"texts":[{"id":3957,"quote":"\u003cp>用“只占用您1分钟时间可以吗”作为开头\u003c/p>\u003cp>上司与部下之间，最容易产生摩擦的就是“报、联、商”。也就是报告、联络、商谈。甚至可以说这三种情景的沟通方式，决定了今后工作的顺畅程度。\u003c/p>\u003cp>比如你的上司负责多个项目，每天都很忙。他经常不在办公桌前，回来时要么在打电话，要么在处理文件，然后就开始用电脑进行工作。而你现在的工作必须占用上司的时间，请他明确地做出判断，否则便无法取得进展，你的上司想必也不愿意看到这个结果。所以你趁着上司回来的时候立刻走上前去，说出这样一句话，“部长！明天下午两点有时间吗？”你原本想的是“趁现在提前约好明天下午2点的时间，明天只要有30分钟就足够把“报、联、商”全部消化完毕。”你心里是这么打算的。但上司的回答却完全出乎你的意料，甚至感觉冷冰冰的。“没时间，下次吧！”\u003c/p>\u003cp>为什么你的上司会表现出如此冷漠的态度？\u003c/p>\u003cp>首先，最关键的失误之处在于，你身为部下却安排了上司的时间，好一点的情况是被上司批评“我的时间一分一秒都很宝贵，你是不是搞错了啊”，如果换成“情感单独型”的上司可能瞬间就发火了。“你凭什么给我安排时间啊？”\u003c/p>\u003cp>第二个问题在于，你没有明确占用的时间长短。究竟要占用5分钟还是30分钟？你的上司完全无法判断。\u003c/p>\u003cp>第三个问题在于，你没有说出问题是什么。\u003c/p>\u003cp>你突然询问“明天有没有时间”，上司会想“难道说他要辞职吗？”“是不是遇到什么难事”，精神也会随之紧张起来。这时上司为了表现得平静一些，也会采取冷漠的态度。\u003c/p>\u003cp>那么，怎么问才好呢？这种情况下标准的答案是：“部长，关于XX的事，我可以占用您1分钟的时间吗？”问题是什么，需要多少时间，全都表达得清清楚楚。因为这项工作本身就是上司布置给你的，所以由他来决定是否应该在百忙之中拿出时间来接受你的商谈。如果他有更重要的事情要做，那么他会提出“不好意思，我10分钟后叫你”或者“晚上行么？”“给我发邮件”等替代方案。“只占用1分钟”的说法，可以给上司一种“很快结束”的安心感。\u003c/p>\u003cp>虽然尽可能简短、清楚的进行“报、联、商”是部下的责任，但上司一旦接受了你的商谈，肯定会让你把话说完。所以实际上不用真的在一分钟之内结束。当然，有时候确实只要一分钟就说完了，但也有持续5分钟或10分钟的情况。在这个过程中，你可以得到很多帮助的建议，工作的品质将得到大幅的提高，上司对你也会做出更高的评价。\u003c/p>\u003cp>只要改变一下说话的方式，上司和部下都能够顺畅地进行工作，如果不能顺利地争取到上司的时间，工作可能会被耽误一周甚至一个月之久。为了避免出现这种情况，请一定要掌握说话的方法，顺利争取到与上司交流的时间。\u003c/p>","explains":"\u003cp>【学习目标】\u003c/p>\u003cp>学会用“只占用您1分钟时间”作为与领导商谈的开头，顺利争取到与上司交流的时间。 \u003c/p>\u003cp>【导入：问题场景】1分钟\u003c/p>\u003cp>工作中，我们常常遇到这样的情况：你的领导负责很多项目，每天都很忙，而你现在的工作需要他决策后才能继续开展，你逮到领导在办公室时，赶紧上前说：“王总，关于xxx的事情，我有个问题想和您汇报一下......”领导经常会说“现在不行，我们再找时间沟通吧！”于是你的问题就这样被搁置了，你的时间节奏也被打乱了。这样的情况我们是不是只能被动等待呢？今天的片段就给出了一个说话的技巧，更容易争取到领导的时间。\u003c/p>\u003cp>【图书介绍】：1-2分钟\u003c/p>\u003cp>&nbsp;今天我要拆解的片段选自《麦肯锡工作法—麦肯锡精英的39个工作习惯》，作者是大岛祥誉，曾在麦肯锡公司从事新事业开拓战略、公司战略以及经营战略的制定等咨询项目。2002年独立创业，从事高管培训、及领导力开发等咨询服务。书中的39个工作习惯是麦肯锡亲身实践的“立竿见影”的简单习惯。如果你读过麦肯锡的经典著作《金字塔原理》你会发现，这本书是根据原理的具体应用。\u003c/p>\u003cp>【FAB法介绍图书】\u003c/p>\u003cp>特点：1.整书将39个习惯进行了归类\u003c/p>\u003cp>2.每个章节很简短，但重点突出，并且每个习惯后有个小结提炼。\u003c/p>\u003cp>优势：方便学习者按照类别培养练习这些习惯，每章小结可以帮助学习者快速复习重点。\u003c/p>\u003cp>好处：通过学习本书并工作中不断练习这些的简单习惯，可以有效提高我们解决问题的能力及工作的品质与效率。\u003c/p>\u003cp>【R环节：用“只占用您1分钟时间可以吗”作为开头】1-2分钟\u003c/p>\u003cp>【I环节：重述原文】2-3分钟\u003c/p>\u003cp>对上司说“关于XX的事，我可以占用您1分钟的时间吗？”作为开头，可以更容易争取到交流的时间。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>1.&nbsp; 和领导汇报或者沟通，是不是每次都要以这样的说话方式开头？\u003c/p>\u003cp>适用范围：你要沟通的内容不在领导的日程安排中，但需要领导有个决策才能往下进行。这样的事情通常是大方向已经确定，在执行过程中需要再和领导确认的重要细节或稍有偏差的小变化，用这样的方法比较合适。\u003c/p>\u003cp>2.&nbsp; 有些时候1分钟说根本说不完啊？\u003c/p>\u003cp>“只占用1分钟”的说法，可以给上司一种“很快结束”的安心感，目的是让上司不管多么繁忙都无法拒绝你的请求采用的一种说辞，真正的交谈中即使超出一些时间也没有关系。\u003c/p>\u003cp>3.&nbsp; 以这样的方式也未必能争取到时间？\u003c/p>\u003cp>是的，这样的说法也不一定能争取到上司的时间，但相比“领导，您现在有时间吗？”这样的说法，更容易争取到交流的时间，原因：你说明了要沟通的问题并告诉领导你需要的时间。\u003c/p>\u003cp>【举例子】1-2分钟\u003c/p>\u003cp>领导安排我做一份微信会员招募的全年计划，在做方案的过程中，需要和领导确认预算后再确定具体的送券金额。我：“领导，你现在有时间吗？微信会员招募计划我有个问题需要和您确认一下。”\u003c/p>\u003cp>领导：“我现在得回复一下郑总的安排的工作，等会我找你。”\u003c/p>\u003cp>这是一个失败的案例，分析：1：没有说明清晰出来具体的问题，2.没有告诉领导需要多长时间。\u003c/p>\u003cp>如果我换一种说法：“领导，关于微信招募的费用预算的事情，我能占用您一分钟时间吗？”\u003c/p>","interaction":"\u003cp>下面就进入到小组讨论环节\u003c/p>\u003cp>【分小组】5-10分钟\u003c/p>\u003cp>【A2环节：催化学习者应用】8分钟\u003c/p>\u003cp>回想一个近期需要领导决策后你才能开展的工作。设想一下周一到了办公室，趁着领导开完晨会的空隙，你要怎么说，才能更容易让领导能立即给你关于这个工作的答复呢？每人1分钟在小组内分享。\u003c/p>\u003cp>分享格式：简明扼要的事情背景+我要说的话\u003c/p>\u003cp>参与者海霞：上周我们开展一场培训，培训的PPT需要讲师审核，我问讲师：“夏老师，你有空吗？培训的PPT给你看下？”夏老师说：“现在没空，下午吧？”我就一直等到下午，下午也没有空，就等到了第二天才抽空给他看。\u003c/p>\u003cp>如果再来一次，我会说：夏老师，关于培训课件的主要框架，我想占用您一分钟的时间请您确认下可以吗?\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":3958,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1480211086000,"updated_at":1480212143000,"ria":true},{"id":680,"topic":"得情报者得天下看麦肯锡情报收集三步法","learn_goal":"情报收集","remark":"得情报者得天下看麦肯锡情报收集三步法","level":"TF2-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"陈健","city":"成都"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"开场： 大家晚上好，我是凝琪，真名陈健，三个标签：改变，计划，坚持。今天晚上我沿用大家先前的分组3组及组长人选。","ratings_count":0,"texts":[{"id":2077,"quote":"\u003cp>大岛祥誉《麦肯锡工作法》抄录\u003c/p>\u003cp>&nbsp;绝大多数的工作,都是从最基础的情报收集“research”开始的。这其中最重要的是收集的质量。如果收集的质量高则工作效率会迅速提升，品质也同样会得到提高。接下来我将为大家介绍麦肯锡的情报收集三步曲，掌握了这个方法你也可以成为情报收集专家。\u003c/p>\u003cp>第一步是明确“情报收集的目的”\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;当麦肯锡要为A公司提供建议时，首先会以找出“对A公司来说最重要的课题是什么”为目的进行收集。因为只有了解了这一点，才能够提出真正有建设性的建议。\u003c/p>\u003cp>第二步是“海量”调查\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;业界的市场发生了什么变化？A公司的强项和弱项是什么？竞争企业都有什么商品？这些信息都需要收集。资料也要海量收集。绝对不要依赖网络调查。之所以要在一开始就进行海量调查，主要是为了防止自我视角。\u003c/p>\u003cp>第三步是去“现场”\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 去现场一定会给你带来意外的收获，使你了解隐藏在统计和数据背后的真相。我认为再也没有什么比去现场更有趣、更能吸引我的了。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;得情报者得天下。\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;作者认为得情报者得天下。怎么样收集情报呢？这里有情报收集的三步曲，\u003cbr>&nbsp; &nbsp; &nbsp; &nbsp;第一步是明确“情报收集的目的”，明确目的如同找到定海神针,即找点-定位点。\u003cbr>&nbsp; &nbsp; &nbsp; &nbsp;第二步是“海量”调查，即“撒网”，广撒网好穷尽死角，找到最优。\u003cbr>&nbsp; &nbsp; &nbsp; &nbsp;第三步是去“现场”，即：“湿足”，只有亲自到现场，才能获得真实可靠的信息。\u003cbr>[强调不这么做的坏处]\u003cbr>&nbsp; &nbsp; &nbsp; &nbsp;以我个人为例，在拆书帮虽然有了第一步明确的目的，加入拆书帮就是因为我喜欢和别人分享一切我觉得有收获、有意思的东西，希望通过拆书把更多知识更有意思的传递给大家。有了这个目的，进而明确了现阶段的目标就是晋级，只有通过了2级拆书家才有可能实现这个目的的基本点。但是第二步就没有海量调查，只是就一些问题礼节性的询问了师傅，所以留了很多死角，比如第一次1-1晋级忘记了时间点的收集，结果要1--15分钟，我只做了8分钟失败了；在第一次晋级1-2时又忘了1-2的流程做成1-1也失败了,而在2-1的晋级中对于显像提问的理解不当到位，对时间的把控也出现了问题又失败了。这些都源于情报收集的自我死角。而真正感受最深刻的还是第三步，现场真实的拆书晋级，大家共同帮助我找出问题，让我纠正问题，获益良多。所以一定要到现场，身历其境才能深刻的感知背后的真相。\u003cbr>&nbsp; &nbsp; &nbsp; 所以，要想成功晋级，那收集情报一定要分三步走，找点、撒网、湿足。。。\u003c/p>","interaction":"\u003cp>&nbsp; &nbsp; 现在请大家想想，在自己周边的同事,朋友或者其他人，在找工作或者市场调查的时候，通常是怎么样收集情报的？有没有遇到过，因为前期情报准备工作做得不理想、有遗漏，结果导致找工作失败，项目丢失被竞争对手抢走的案例呢？。注意：每个人都要尽量表达，时间1-2分钟，组长要控制时间哈。\u003c/p>\u003cp>[学习者案例记录]：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 心怡分享小组2个案例：1.应聘时，没有对应聘公司进行调查失败率很高；2.创业初期作项目：只作了简单的调查，没有形成完整的调查报告，也不了解竞争对手的实力导致项目失败。\u003c/p>\u003cp>在刚才大家的分享的案例中，如果让你重新来过，你会如何运用刚才学习的三步法，你会怎么做？\u003c/p>\u003cp>[学习者案例记录]:\u003c/p>\u003cp>&nbsp;小龙分享：找工作分三步走：1.明确目的：想找什么样的工作?薪资大概是多少？环境要求是什么？2.海量调查：调查方法多种多样，可以到网上去查公司的基本介绍，利用qq和微信平台，加相关人员的qq或者微信了解他们的公司的真实状况，尤其是福利和抱怨等。3.到现场：到应聘公司现场查看或者现场面试应聘者可以通过跟面试官的交流确认一下自己找的工作的准备是否符合自己的目标和对方的需求，这样可以避免偏失。\u003c/p>\u003cp>谢谢小龙的分享，相信通过此次拆书学习，大家对于收集情报的三步法已经了解到了很多，我也真心的希望这三步法可以帮助大家在学习生活中少走弯路，在工作上提高竞争力。好，今天分享就到这儿，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1470133480000,"updated_at":1470133480000,"ria":true},{"id":622,"topic":"麦肯锡情报收集三步法","learn_goal":"怎么收集信息","remark":"教我们麦肯锡情报收集三步法得情报者得天下","level":"TF2-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"陈健","city":"成都"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":null,"ratings_count":0,"texts":[{"id":1801,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1468817925000,"updated_at":1470134207000}]};